  (4906, 5, '55:5', 54, 213, 468, 7, NULL, 'ٱلشَّمْسُ وَٱلْقَمَرُ بِحُسْبَانٍ', 55, 'الشمس والقمر بحسبان', 531, 27),
  (4907, 6, '55:6', 54, 213, 468, 7, NULL, 'وَٱلنَّجْمُ وَٱلشَّجَرُ يَسْجُدَانِ', 55, 'والنجم والشجر يسجدان', 531, 27),
  (4908, 7, '55:7', 54, 213, 468, 7, NULL, 'وَٱلسَّمَآءَ رَفَعَهَا وَوَضَعَ ٱلْمِيزَانَ', 55, 'والسماء رفعها ووضع الميزان', 531, 27),
  (4909, 8, '55:8', 54, 213, 468, 7, NULL, 'أَلَّا تَطْغَوْا۟ فِى ٱلْمِيزَانِ', 55, 'الا تطغوا في الميزان', 531, 27),
