  (4914, 13, '55:13', 54, 213, 468, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 531, 27),
  (4915, 14, '55:14', 54, 213, 468, 7, NULL, 'خَلَقَ ٱلْإِنسَـٰنَ مِن صَلْصَـٰلٍ كَٱلْفَخَّارِ', 55, 'خلق الانسان من صلصال كالفخار', 531, 27),
  (4916, 15, '55:15', 54, 213, 468, 7, NULL, 'وَخَلَقَ ٱلْجَآنَّ مِن مَّارِجٍ مِّن نَّارٍ', 55, 'وخلق الجان من مارج من نار', 531, 27),
