  (4920, 19, '55:19', 54, 213, 468, 7, NULL, 'مَرَجَ ٱلْبَحْرَيْنِ يَلْتَقِيَانِ', 55, 'مرج البحرين يلتقيان', 532, 27),
  (4921, 20, '55:20', 54, 213, 468, 7, NULL, 'بَيْنَهُمَا بَرْزَخٌ لَّا يَبْغِيَانِ', 55, 'بينهما برزخ لا يبغيان', 532, 27),
  (4922, 21, '55:21', 54, 213, 468, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 532, 27),
  (4923, 22, '55:22', 54, 213, 468, 7, NULL, 'يَخْرُجُ مِنْهُمَا ٱللُّؤْلُؤُ وَٱلْمَرْجَانُ', 55, 'يخرج منهما اللؤلؤ والمرجان', 532, 27),
