  (4953, 52, '55:52', 54, 213, 470, 7, NULL, 'فِيهِمَا مِن كُلِّ فَـٰكِهَةٍ زَوْجَانِ', 55, 'فيهما من كل فاكهة زوجان', 533, 27),
  (4954, 53, '55:53', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 533, 27),
  (4955, 54, '55:54', 54, 213, 470, 7, NULL, 'مُتَّكِـِٔينَ عَلَىٰ فُرُشٍۭ بَطَآئِنُهَا مِنْ إِسْتَبْرَقٍ ۚ وَجَنَى ٱلْجَنَّتَيْنِ دَانٍ', 55, 'متكئين على فرش بطائنها من استبرق وجنى الجنتين دان', 533, 27),
  (4956, 55, '55:55', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 533, 27),
  (4957, 56, '55:56', 54, 213, 470, 7, NULL, 'فِيهِنَّ قَـٰصِرَٰتُ ٱلطَّرْفِ لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَآنٌّ', 55, 'فيهن قاصرات الطرف لم يطمثهن انس قبلهم ولا جان', 533, 27),
  (4958, 57, '55:57', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 533, 27),
  (4959, 58, '55:58', 54, 213, 470, 7, NULL, 'كَأَنَّهُنَّ ٱلْيَاقُوتُ وَٱلْمَرْجَانُ', 55, 'كانهن الياقوت والمرجان', 533, 27),
  (4960, 59, '55:59', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 533, 27),
  (4961, 60, '55:60', 54, 213, 470, 7, NULL, 'هَلْ جَزَآءُ ٱلْإِحْسَـٰنِ إِلَّا ٱلْإِحْسَـٰنُ', 55, 'هل جزاء الاحسان الا الاحسان', 533, 27),
  (4962, 61, '55:61', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 533, 27),
  (4963, 62, '55:62', 54, 213, 470, 7, NULL, 'وَمِن دُونِهِمَا جَنَّتَانِ', 55, 'ومن دونهما جنتان', 533, 27),
  (4964, 63, '55:63', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 533, 27),
  (4965, 64, '55:64', 54, 213, 470, 7, NULL, 'مُدْهَآمَّتَانِ', 55, 'مدهامتان', 533, 27),
  (4966, 65, '55:65', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 533, 27),
  (4967, 66, '55:66', 54, 213, 470, 7, NULL, 'فِيهِمَا عَيْنَانِ نَضَّاخَتَانِ', 55, 'فيهما عينان نضاختان', 533, 27),
  (4968, 67, '55:67', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 533, 27),
  (4969, 68, '55:68', 54, 213, 470, 7, NULL, 'فِيهِمَا فَـٰكِهَةٌ وَنَخْلٌ وَرُمَّانٌ', 55, 'فيهما فاكهة ونخل ورمان', 534, 27),
  (4970, 69, '55:69', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 534, 27),
  (4971, 70, '55:70', 54, 213, 470, 7, NULL, 'فِيهِنَّ خَيْرَٰتٌ حِسَانٌ', 55, 'فيهن خيرات حسان', 534, 27),
  (4972, 71, '55:71', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 534, 27),
  (4973, 72, '55:72', 54, 213, 470, 7, NULL, 'حُورٌ مَّقْصُورَٰتٌ فِى ٱلْخِيَامِ', 55, 'حور مقصورات في الخيام', 534, 27),
  (4974, 73, '55:73', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 534, 27),
  (4975, 74, '55:74', 54, 213, 470, 7, NULL, 'لَمْ يَطْمِثْهُنَّ إِنسٌ قَبْلَهُمْ وَلَا جَآنٌّ', 55, 'لم يطمثهن انس قبلهم ولا جان', 534, 27),
  (4976, 75, '55:75', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 534, 27),
  (4977, 76, '55:76', 54, 213, 470, 7, NULL, 'مُتَّكِـِٔينَ عَلَىٰ رَفْرَفٍ خُضْرٍ وَعَبْقَرِىٍّ حِسَانٍ', 55, 'متكئين على رفرف خضر وعبقري حسان', 534, 27),
  (4978, 77, '55:77', 54, 213, 470, 7, NULL, 'فَبِأَىِّ ءَالَآءِ رَبِّكُمَا تُكَذِّبَانِ', 55, 'فباي الاء ربكما تكذبان', 534, 27),
  (4979, 78, '55:78', 54, 213, 470, 7, NULL, 'تَبَـٰرَكَ ٱسْمُ رَبِّكَ ذِى ٱلْجَلَـٰلِ وَٱلْإِكْرَامِ', 55, 'تبارك اسم ربك ذي الجلال والاكرام', 534, 27),
  (4980, 1, '56:1', 54, 214, 471, 7, NULL, ' إِذَا وَقَعَتِ ٱلْوَاقِعَةُ', 56, 'اذا وقعت الواقعة', 534, 27),
  (4981, 2, '56:2', 54, 214, 471, 7, NULL, 'لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ', 56, 'ليس لوقعتها كاذبة', 534, 27),
  (4982, 3, '56:3', 54, 214, 471, 7, NULL, 'خَافِضَةٌ رَّافِعَةٌ', 56, 'خافضة رافعة', 534, 27),
  (4983, 4, '56:4', 54, 214, 471, 7, NULL, 'إِذَا رُجَّتِ ٱلْأَرْضُ رَجًّا', 56, 'اذا رجت الارض رجا', 534, 27),
  (4984, 5, '56:5', 54, 214, 471, 7, NULL, 'وَبُسَّتِ ٱلْجِبَالُ بَسًّا', 56, 'وبست الجبال بسا', 534, 27),
  (4985, 6, '56:6', 54, 214, 471, 7, NULL, 'فَكَانَتْ هَبَآءً مُّنۢبَثًّا', 56, 'فكانت هباء منبثا', 534, 27),
  (4986, 7, '56:7', 54, 214, 471, 7, NULL, 'وَكُنتُمْ أَزْوَٰجًا ثَلَـٰثَةً', 56, 'وكنتم ازواجا ثلاثة', 534, 27),
  (4987, 8, '56:8', 54, 214, 471, 7, NULL, 'فَأَصْحَـٰبُ ٱلْمَيْمَنَةِ مَآ أَصْحَـٰبُ ٱلْمَيْمَنَةِ', 56, 'فاصحاب الميمنة ما اصحاب الميمنة', 534, 27),
  (4988, 9, '56:9', 54, 214, 471, 7, NULL, 'وَأَصْحَـٰبُ ٱلْمَشْـَٔمَةِ مَآ أَصْحَـٰبُ ٱلْمَشْـَٔمَةِ', 56, 'واصحاب المشامة ما اصحاب المشامة', 534, 27),
  (4989, 10, '56:10', 54, 214, 471, 7, NULL, 'وَٱلسَّـٰبِقُونَ ٱلسَّـٰبِقُونَ', 56, 'والسابقون السابقون', 534, 27),
  (4990, 11, '56:11', 54, 214, 471, 7, NULL, 'أُو۟لَـٰٓئِكَ ٱلْمُقَرَّبُونَ', 56, 'اولئك المقربون', 534, 27),
  (4991, 12, '56:12', 54, 214, 471, 7, NULL, 'فِى جَنَّـٰتِ ٱلنَّعِيمِ', 56, 'في جنات النعيم', 534, 27),
  (4992, 13, '56:13', 54, 214, 471, 7, NULL, 'ثُلَّةٌ مِّنَ ٱلْأَوَّلِينَ', 56, 'ثلة من الاولين', 534, 27),
  (4993, 14, '56:14', 54, 214, 471, 7, NULL, 'وَقَلِيلٌ مِّنَ ٱلْـَٔاخِرِينَ', 56, 'وقليل من الاخرين', 534, 27),
  (4994, 15, '56:15', 54, 214, 471, 7, NULL, 'عَلَىٰ سُرُرٍ مَّوْضُونَةٍ', 56, 'على سرر موضونة', 534, 27),
  (4995, 16, '56:16', 54, 214, 471, 7, NULL, 'مُّتَّكِـِٔينَ عَلَيْهَا مُتَقَـٰبِلِينَ', 56, 'متكئين عليها متقابلين', 534, 27),
  (4996, 17, '56:17', 54, 214, 471, 7, NULL, 'يَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ', 56, 'يطوف عليهم ولدان مخلدون', 535, 27),
  (4997, 18, '56:18', 54, 214, 471, 7, NULL, 'بِأَكْوَابٍ وَأَبَارِيقَ وَكَأْسٍ مِّن مَّعِينٍ', 56, 'باكواب واباريق وكاس من معين', 535, 27),
  (4998, 19, '56:19', 54, 214, 471, 7, NULL, 'لَّا يُصَدَّعُونَ عَنْهَا وَلَا يُنزِفُونَ', 56, 'لا يصدعون عنها ولا ينزفون', 535, 27),
  (4999, 20, '56:20', 54, 214, 471, 7, NULL, 'وَفَـٰكِهَةٍ مِّمَّا يَتَخَيَّرُونَ', 56, 'وفاكهة مما يتخيرون', 535, 27),
  (5000, 21, '56:21', 54, 214, 471, 7, NULL, 'وَلَحْمِ طَيْرٍ مِّمَّا يَشْتَهُونَ', 56, 'ولحم طير مما يشتهون', 535, 27);
INSERT INTO `verses` (`id`, `verse_number`, `verse_key`, `hizb_number`, `rub_el_hizb_number`, `ruku_number`, `manzil_number`, `sajdah_number`, `text_uthmani`, `chapter_id`, `text_imlaei_simple`, `page_number`, `juz_number`) VALUES
  (5001, 22, '56:22', 54, 214, 471, 7, NULL, 'وَحُورٌ عِينٌ', 56, 'وحور عين', 535, 27),
  (5002, 23, '56:23', 54, 214, 471, 7, NULL, 'كَأَمْثَـٰلِ ٱللُّؤْلُؤِ ٱلْمَكْنُونِ', 56, 'كامثال اللؤلؤ المكنون', 535, 27),
  (5003, 24, '56:24', 54, 214, 471, 7, NULL, 'جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ', 56, 'جزاء بما كانوا يعملون', 535, 27),
  (5004, 25, '56:25', 54, 214, 471, 7, NULL, 'لَا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا تَأْثِيمًا', 56, 'لا يسمعون فيها لغوا ولا تاثيما', 535, 27),
  (5005, 26, '56:26', 54, 214, 471, 7, NULL, 'إِلَّا قِيلًا سَلَـٰمًا سَلَـٰمًا', 56, 'الا قيلا سلاما سلاما', 535, 27),
  (5006, 27, '56:27', 54, 214, 471, 7, NULL, 'وَأَصْحَـٰبُ ٱلْيَمِينِ مَآ أَصْحَـٰبُ ٱلْيَمِينِ', 56, 'واصحاب اليمين ما اصحاب اليمين', 535, 27),
  (5007, 28, '56:28', 54, 214, 471, 7, NULL, 'فِى سِدْرٍ مَّخْضُودٍ', 56, 'في سدر مخضود', 535, 27),
  (5008, 29, '56:29', 54, 214, 471, 7, NULL, 'وَطَلْحٍ مَّنضُودٍ', 56, 'وطلح منضود', 535, 27),
  (5009, 30, '56:30', 54, 214, 471, 7, NULL, 'وَظِلٍّ مَّمْدُودٍ', 56, 'وظل ممدود', 535, 27),
  (5010, 31, '56:31', 54, 214, 471, 7, NULL, 'وَمَآءٍ مَّسْكُوبٍ', 56, 'وماء مسكوب', 535, 27),
  (5011, 32, '56:32', 54, 214, 471, 7, NULL, 'وَفَـٰكِهَةٍ كَثِيرَةٍ', 56, 'وفاكهة كثيرة', 535, 27),
  (5012, 33, '56:33', 54, 214, 471, 7, NULL, 'لَّا مَقْطُوعَةٍ وَلَا مَمْنُوعَةٍ', 56, 'لا مقطوعة ولا ممنوعة', 535, 27),
  (5013, 34, '56:34', 54, 214, 471, 7, NULL, 'وَفُرُشٍ مَّرْفُوعَةٍ', 56, 'وفرش مرفوعة', 535, 27),
  (5014, 35, '56:35', 54, 214, 471, 7, NULL, 'إِنَّآ أَنشَأْنَـٰهُنَّ إِنشَآءً', 56, 'انا انشاناهن انشاء', 535, 27),
  (5015, 36, '56:36', 54, 214, 471, 7, NULL, 'فَجَعَلْنَـٰهُنَّ أَبْكَارًا', 56, 'فجعلناهن ابكارا', 535, 27),
  (5016, 37, '56:37', 54, 214, 471, 7, NULL, 'عُرُبًا أَتْرَابًا', 56, 'عربا اترابا', 535, 27),
  (5017, 38, '56:38', 54, 214, 471, 7, NULL, 'لِّأَصْحَـٰبِ ٱلْيَمِينِ', 56, 'لاصحاب اليمين', 535, 27),
  (5018, 39, '56:39', 54, 214, 472, 7, NULL, 'ثُلَّةٌ مِّنَ ٱلْأَوَّلِينَ', 56, 'ثلة من الاولين', 535, 27),
  (5019, 40, '56:40', 54, 214, 472, 7, NULL, 'وَثُلَّةٌ مِّنَ ٱلْـَٔاخِرِينَ', 56, 'وثلة من الاخرين', 535, 27),
  (5020, 41, '56:41', 54, 214, 472, 7, NULL, 'وَأَصْحَـٰبُ ٱلشِّمَالِ مَآ أَصْحَـٰبُ ٱلشِّمَالِ', 56, 'واصحاب الشمال ما اصحاب الشمال', 535, 27),
  (5021, 42, '56:42', 54, 214, 472, 7, NULL, 'فِى سَمُومٍ وَحَمِيمٍ', 56, 'في سموم وحميم', 535, 27),
  (5022, 43, '56:43', 54, 214, 472, 7, NULL, 'وَظِلٍّ مِّن يَحْمُومٍ', 56, 'وظل من يحموم', 535, 27),
  (5023, 44, '56:44', 54, 214, 472, 7, NULL, 'لَّا بَارِدٍ وَلَا كَرِيمٍ', 56, 'لا بارد ولا كريم', 535, 27),
  (5024, 45, '56:45', 54, 214, 472, 7, NULL, 'إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُتْرَفِينَ', 56, 'انهم كانوا قبل ذلك مترفين', 535, 27),
  (5025, 46, '56:46', 54, 214, 472, 7, NULL, 'وَكَانُوا۟ يُصِرُّونَ عَلَى ٱلْحِنثِ ٱلْعَظِيمِ', 56, 'وكانوا يصرون على الحنث العظيم', 535, 27),
  (5026, 47, '56:47', 54, 214, 472, 7, NULL, 'وَكَانُوا۟ يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَـٰمًا أَءِنَّا لَمَبْعُوثُونَ', 56, 'وكانوا يقولون ائذا متنا وكنا ترابا وعظاما اانا لمبعوثون', 535, 27),
  (5027, 48, '56:48', 54, 214, 472, 7, NULL, 'أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ', 56, 'اواباؤنا الاولون', 535, 27),
  (5028, 49, '56:49', 54, 214, 472, 7, NULL, 'قُلْ إِنَّ ٱلْأَوَّلِينَ وَٱلْـَٔاخِرِينَ', 56, 'قل ان الاولين والاخرين', 535, 27),
  (5029, 50, '56:50', 54, 214, 472, 7, NULL, 'لَمَجْمُوعُونَ إِلَىٰ مِيقَـٰتِ يَوْمٍ مَّعْلُومٍ', 56, 'لمجموعون الى ميقات يوم معلوم', 535, 27),
  (5030, 51, '56:51', 54, 214, 472, 7, NULL, 'ثُمَّ إِنَّكُمْ أَيُّهَا ٱلضَّآلُّونَ ٱلْمُكَذِّبُونَ', 56, 'ثم انكم ايها الضالون المكذبون', 536, 27),
  (5031, 52, '56:52', 54, 214, 472, 7, NULL, 'لَـَٔاكِلُونَ مِن شَجَرٍ مِّن زَقُّومٍ', 56, 'لاكلون من شجر من زقوم', 536, 27),
  (5032, 53, '56:53', 54, 214, 472, 7, NULL, 'فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ', 56, 'فمالئون منها البطون', 536, 27),
  (5033, 54, '56:54', 54, 214, 472, 7, NULL, 'فَشَـٰرِبُونَ عَلَيْهِ مِنَ ٱلْحَمِيمِ', 56, 'فشاربون عليه من الحميم', 536, 27),
  (5034, 55, '56:55', 54, 214, 472, 7, NULL, 'فَشَـٰرِبُونَ شُرْبَ ٱلْهِيمِ', 56, 'فشاربون شرب الهيم', 536, 27),
  (5035, 56, '56:56', 54, 214, 472, 7, NULL, 'هَـٰذَا نُزُلُهُمْ يَوْمَ ٱلدِّينِ', 56, 'هذا نزلهم يوم الدين', 536, 27),
  (5036, 57, '56:57', 54, 214, 472, 7, NULL, 'نَحْنُ خَلَقْنَـٰكُمْ فَلَوْلَا تُصَدِّقُونَ', 56, 'نحن خلقناكم فلولا تصدقون', 536, 27),
  (5037, 58, '56:58', 54, 214, 472, 7, NULL, 'أَفَرَءَيْتُم مَّا تُمْنُونَ', 56, 'افرايتم ما تمنون', 536, 27),
  (5038, 59, '56:59', 54, 214, 472, 7, NULL, 'ءَأَنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ٱلْخَـٰلِقُونَ', 56, 'اانتم تخلقونه ام نحن الخالقون', 536, 27),
  (5039, 60, '56:60', 54, 214, 472, 7, NULL, 'نَحْنُ قَدَّرْنَا بَيْنَكُمُ ٱلْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ', 56, 'نحن قدرنا بينكم الموت وما نحن بمسبوقين', 536, 27),
  (5040, 61, '56:61', 54, 214, 472, 7, NULL, 'عَلَىٰٓ أَن نُّبَدِّلَ أَمْثَـٰلَكُمْ وَنُنشِئَكُمْ فِى مَا لَا تَعْلَمُونَ', 56, 'على ان نبدل امثالكم وننشئكم في ما لا تعلمون', 536, 27),
  (5041, 62, '56:62', 54, 214, 472, 7, NULL, 'وَلَقَدْ عَلِمْتُمُ ٱلنَّشْأَةَ ٱلْأُولَىٰ فَلَوْلَا تَذَكَّرُونَ', 56, 'ولقد علمتم النشاة الاولى فلولا تذكرون', 536, 27),
  (5042, 63, '56:63', 54, 214, 472, 7, NULL, 'أَفَرَءَيْتُم مَّا تَحْرُثُونَ', 56, 'افرايتم ما تحرثون', 536, 27),
  (5043, 64, '56:64', 54, 214, 472, 7, NULL, 'ءَأَنتُمْ تَزْرَعُونَهُۥٓ أَمْ نَحْنُ ٱلزَّٰرِعُونَ', 56, 'اانتم تزرعونه ام نحن الزارعون', 536, 27),
  (5044, 65, '56:65', 54, 214, 472, 7, NULL, 'لَوْ نَشَآءُ لَجَعَلْنَـٰهُ حُطَـٰمًا فَظَلْتُمْ تَفَكَّهُونَ', 56, 'لو نشاء لجعلناه حطاما فظلتم تفكهون', 536, 27),
  (5045, 66, '56:66', 54, 214, 472, 7, NULL, 'إِنَّا لَمُغْرَمُونَ', 56, 'انا لمغرمون', 536, 27),
  (5046, 67, '56:67', 54, 214, 472, 7, NULL, 'بَلْ نَحْنُ مَحْرُومُونَ', 56, 'بل نحن محرومون', 536, 27),
  (5047, 68, '56:68', 54, 214, 472, 7, NULL, 'أَفَرَءَيْتُمُ ٱلْمَآءَ ٱلَّذِى تَشْرَبُونَ', 56, 'افرايتم الماء الذي تشربون', 536, 27),
  (5048, 69, '56:69', 54, 214, 472, 7, NULL, 'ءَأَنتُمْ أَنزَلْتُمُوهُ مِنَ ٱلْمُزْنِ أَمْ نَحْنُ ٱلْمُنزِلُونَ', 56, 'اانتم انزلتموه من المزن ام نحن المنزلون', 536, 27),
  (5049, 70, '56:70', 54, 214, 472, 7, NULL, 'لَوْ نَشَآءُ جَعَلْنَـٰهُ أُجَاجًا فَلَوْلَا تَشْكُرُونَ', 56, 'لو نشاء جعلناه اجاجا فلولا تشكرون', 536, 27),
  (5050, 71, '56:71', 54, 214, 472, 7, NULL, 'أَفَرَءَيْتُمُ ٱلنَّارَ ٱلَّتِى تُورُونَ', 56, 'افرايتم النار التي تورون', 536, 27),
  (5051, 72, '56:72', 54, 214, 472, 7, NULL, 'ءَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ٱلْمُنشِـُٔونَ', 56, 'اانتم انشاتم شجرتها ام نحن المنشئون', 536, 27),
  (5052, 73, '56:73', 54, 214, 472, 7, NULL, 'نَحْنُ جَعَلْنَـٰهَا تَذْكِرَةً وَمَتَـٰعًا لِّلْمُقْوِينَ', 56, 'نحن جعلناها تذكرة ومتاعا للمقوين', 536, 27),
  (5053, 74, '56:74', 54, 214, 472, 7, NULL, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 56, 'فسبح باسم ربك العظيم', 536, 27),
  (5054, 75, '56:75', 54, 215, 473, 7, NULL, '۞ فَلَآ أُقْسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ', 56, 'فلا اقسم بمواقع النجوم', 536, 27),
  (5055, 76, '56:76', 54, 215, 473, 7, NULL, 'وَإِنَّهُۥ لَقَسَمٌ لَّوْ تَعْلَمُونَ عَظِيمٌ', 56, 'وانه لقسم لو تعلمون عظيم', 536, 27),
  (5056, 77, '56:77', 54, 215, 473, 7, NULL, 'إِنَّهُۥ لَقُرْءَانٌ كَرِيمٌ', 56, 'انه لقران كريم', 537, 27),
  (5057, 78, '56:78', 54, 215, 473, 7, NULL, 'فِى كِتَـٰبٍ مَّكْنُونٍ', 56, 'في كتاب مكنون', 537, 27),
  (5058, 79, '56:79', 54, 215, 473, 7, NULL, 'لَّا يَمَسُّهُۥٓ إِلَّا ٱلْمُطَهَّرُونَ', 56, 'لا يمسه الا المطهرون', 537, 27),
  (5059, 80, '56:80', 54, 215, 473, 7, NULL, 'تَنزِيلٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ', 56, 'تنزيل من رب العالمين', 537, 27),
  (5060, 81, '56:81', 54, 215, 473, 7, NULL, 'أَفَبِهَـٰذَا ٱلْحَدِيثِ أَنتُم مُّدْهِنُونَ', 56, 'افبهذا الحديث انتم مدهنون', 537, 27),
  (5061, 82, '56:82', 54, 215, 473, 7, NULL, 'وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ', 56, 'وتجعلون رزقكم انكم تكذبون', 537, 27),
  (5062, 83, '56:83', 54, 215, 473, 7, NULL, 'فَلَوْلَآ إِذَا بَلَغَتِ ٱلْحُلْقُومَ', 56, 'فلولا اذا بلغت الحلقوم', 537, 27),
  (5063, 84, '56:84', 54, 215, 473, 7, NULL, 'وَأَنتُمْ حِينَئِذٍ تَنظُرُونَ', 56, 'وانتم حينئذ تنظرون', 537, 27),
  (5064, 85, '56:85', 54, 215, 473, 7, NULL, 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَـٰكِن لَّا تُبْصِرُونَ', 56, 'ونحن اقرب اليه منكم ولكن لا تبصرون', 537, 27),
  (5065, 86, '56:86', 54, 215, 473, 7, NULL, 'فَلَوْلَآ إِن كُنتُمْ غَيْرَ مَدِينِينَ', 56, 'فلولا ان كنتم غير مدينين', 537, 27),
  (5066, 87, '56:87', 54, 215, 473, 7, NULL, 'تَرْجِعُونَهَآ إِن كُنتُمْ صَـٰدِقِينَ', 56, 'ترجعونها ان كنتم صادقين', 537, 27),
  (5067, 88, '56:88', 54, 215, 473, 7, NULL, 'فَأَمَّآ إِن كَانَ مِنَ ٱلْمُقَرَّبِينَ', 56, 'فاما ان كان من المقربين', 537, 27),
  (5068, 89, '56:89', 54, 215, 473, 7, NULL, 'فَرَوْحٌ وَرَيْحَانٌ وَجَنَّتُ نَعِيمٍ', 56, 'فروح وريحان وجنت نعيم', 537, 27),
  (5069, 90, '56:90', 54, 215, 473, 7, NULL, 'وَأَمَّآ إِن كَانَ مِنْ أَصْحَـٰبِ ٱلْيَمِينِ', 56, 'واما ان كان من اصحاب اليمين', 537, 27),
  (5070, 91, '56:91', 54, 215, 473, 7, NULL, 'فَسَلَـٰمٌ لَّكَ مِنْ أَصْحَـٰبِ ٱلْيَمِينِ', 56, 'فسلام لك من اصحاب اليمين', 537, 27),
  (5071, 92, '56:92', 54, 215, 473, 7, NULL, 'وَأَمَّآ إِن كَانَ مِنَ ٱلْمُكَذِّبِينَ ٱلضَّآلِّينَ', 56, 'واما ان كان من المكذبين الضالين', 537, 27),
  (5072, 93, '56:93', 54, 215, 473, 7, NULL, 'فَنُزُلٌ مِّنْ حَمِيمٍ', 56, 'فنزل من حميم', 537, 27),
  (5073, 94, '56:94', 54, 215, 473, 7, NULL, 'وَتَصْلِيَةُ جَحِيمٍ', 56, 'وتصلية جحيم', 537, 27),
  (5074, 95, '56:95', 54, 215, 473, 7, NULL, 'إِنَّ هَـٰذَا لَهُوَ حَقُّ ٱلْيَقِينِ', 56, 'ان هذا لهو حق اليقين', 537, 27),
  (5075, 96, '56:96', 54, 215, 473, 7, NULL, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 56, 'فسبح باسم ربك العظيم', 537, 27),
  (5076, 1, '57:1', 54, 215, 474, 7, NULL, ' سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 57, 'سبح لله ما في السماوات والارض وهو العزيز الحكيم', 537, 27),
  (5077, 2, '57:2', 54, 215, 474, 7, NULL, 'لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ يُحْىِۦ وَيُمِيتُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 57, 'له ملك السماوات والارض يحيي ويميت وهو على كل شيء قدير', 537, 27),
  (5078, 3, '57:3', 54, 215, 474, 7, NULL, 'هُوَ ٱلْأَوَّلُ وَٱلْـَٔاخِرُ وَٱلظَّـٰهِرُ وَٱلْبَاطِنُ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ', 57, 'هو الاول والاخر والظاهر والباطن وهو بكل شيء عليم', 537, 27),
  (5079, 4, '57:4', 54, 215, 474, 7, NULL, 'هُوَ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ ۚ يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا ۖ وَهُوَ مَعَكُمْ أَيْنَ مَا كُنتُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 57, 'هو الذي خلق السماوات والارض في ستة ايام ثم استوى على العرش يعلم ما يلج في الارض وما يخرج منها وما ينزل من السماء وما يعرج فيها وهو معكم اين ما كنتم والله بما تعملون بصير', 538, 27),
  (5080, 5, '57:5', 54, 215, 474, 7, NULL, 'لَّهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ', 57, 'له ملك السماوات والارض والى الله ترجع الامور', 538, 27),
  (5081, 6, '57:6', 54, 215, 474, 7, NULL, 'يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ ۚ وَهُوَ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 57, 'يولج الليل في النهار ويولج النهار في الليل وهو عليم بذات الصدور', 538, 27),
  (5082, 7, '57:7', 54, 215, 474, 7, NULL, 'ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسْتَخْلَفِينَ فِيهِ ۖ فَٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَأَنفَقُوا۟ لَهُمْ أَجْرٌ كَبِيرٌ', 57, 'امنوا بالله ورسوله وانفقوا مما جعلكم مستخلفين فيه فالذين امنوا منكم وانفقوا لهم اجر كبير', 538, 27),
  (5083, 8, '57:8', 54, 215, 474, 7, NULL, 'وَمَا لَكُمْ لَا تُؤْمِنُونَ بِٱللَّهِ ۙ وَٱلرَّسُولُ يَدْعُوكُمْ لِتُؤْمِنُوا۟ بِرَبِّكُمْ وَقَدْ أَخَذَ مِيثَـٰقَكُمْ إِن كُنتُم مُّؤْمِنِينَ', 57, 'وما لكم لا تؤمنون بالله والرسول يدعوكم لتؤمنوا بربكم وقد اخذ ميثاقكم ان كنتم مؤمنين', 538, 27),
  (5084, 9, '57:9', 54, 215, 474, 7, NULL, 'هُوَ ٱلَّذِى يُنَزِّلُ عَلَىٰ عَبْدِهِۦٓ ءَايَـٰتٍۭ بَيِّنَـٰتٍ لِّيُخْرِجَكُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ ۚ وَإِنَّ ٱللَّهَ بِكُمْ لَرَءُوفٌ رَّحِيمٌ', 57, 'هو الذي ينزل على عبده ايات بينات ليخرجكم من الظلمات الى النور وان الله بكم لرءوف رحيم', 538, 27),
  (5085, 10, '57:10', 54, 215, 474, 7, NULL, 'وَمَا لَكُمْ أَلَّا تُنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلِلَّهِ مِيرَٰثُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ لَا يَسْتَوِى مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ ٱلْفَتْحِ وَقَـٰتَلَ ۚ أُو۟لَـٰٓئِكَ أَعْظَمُ دَرَجَةً مِّنَ ٱلَّذِينَ أَنفَقُوا۟ مِنۢ بَعْدُ وَقَـٰتَلُوا۟ ۚ وَكُلًّا وَعَدَ ٱللَّهُ ٱلْحُسْنَىٰ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 57, 'وما لكم الا تنفقوا في سبيل الله ولله ميراث السماوات والارض لا يستوي منكم من انفق من قبل الفتح وقاتل اولئك اعظم درجة من الذين انفقوا من بعد وقاتلوا وكلا وعد الله الحسنى والله بما تعملون خبير', 538, 27),
  (5086, 11, '57:11', 54, 215, 475, 7, NULL, 'مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَـٰعِفَهُۥ لَهُۥ وَلَهُۥٓ أَجْرٌ كَرِيمٌ', 57, 'من ذا الذي يقرض الله قرضا حسنا فيضاعفه له وله اجر كريم', 538, 27),
  (5087, 12, '57:12', 54, 215, 475, 7, NULL, 'يَوْمَ تَرَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ يَسْعَىٰ نُورُهُم بَيْنَ أَيْدِيهِمْ وَبِأَيْمَـٰنِهِم بُشْرَىٰكُمُ ٱلْيَوْمَ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ', 57, 'يوم ترى المؤمنين والمؤمنات يسعى نورهم بين ايديهم وبايمانهم بشراكم اليوم جنات تجري من تحتها الانهار خالدين فيها ذلك هو الفوز العظيم', 539, 27),
  (5088, 13, '57:13', 54, 215, 475, 7, NULL, 'يَوْمَ يَقُولُ ٱلْمُنَـٰفِقُونَ وَٱلْمُنَـٰفِقَـٰتُ لِلَّذِينَ ءَامَنُوا۟ ٱنظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ٱرْجِعُوا۟ وَرَآءَكُمْ فَٱلْتَمِسُوا۟ نُورًا فَضُرِبَ بَيْنَهُم بِسُورٍ لَّهُۥ بَابٌۢ بَاطِنُهُۥ فِيهِ ٱلرَّحْمَةُ وَظَـٰهِرُهُۥ مِن قِبَلِهِ ٱلْعَذَابُ', 57, 'يوم يقول المنافقون والمنافقات للذين امنوا انظرونا نقتبس من نوركم قيل ارجعوا وراءكم فالتمسوا نورا فضرب بينهم بسور له باب باطنه فيه الرحمة وظاهره من قبله العذاب', 539, 27),
  (5089, 14, '57:14', 54, 215, 475, 7, NULL, 'يُنَادُونَهُمْ أَلَمْ نَكُن مَّعَكُمْ ۖ قَالُوا۟ بَلَىٰ وَلَـٰكِنَّكُمْ فَتَنتُمْ أَنفُسَكُمْ وَتَرَبَّصْتُمْ وَٱرْتَبْتُمْ وَغَرَّتْكُمُ ٱلْأَمَانِىُّ حَتَّىٰ جَآءَ أَمْرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلْغَرُورُ', 57, 'ينادونهم الم نكن معكم قالوا بلى ولكنكم فتنتم انفسكم وتربصتم وارتبتم وغرتكم الاماني حتى جاء امر الله وغركم بالله الغرور', 539, 27),
  (5090, 15, '57:15', 54, 215, 475, 7, NULL, 'فَٱلْيَوْمَ لَا يُؤْخَذُ مِنكُمْ فِدْيَةٌ وَلَا مِنَ ٱلَّذِينَ كَفَرُوا۟ ۚ مَأْوَىٰكُمُ ٱلنَّارُ ۖ هِىَ مَوْلَىٰكُمْ ۖ وَبِئْسَ ٱلْمَصِيرُ', 57, 'فاليوم لا يؤخذ منكم فدية ولا من الذين كفروا ماواكم النار هي مولاكم وبئس المصير', 539, 27),
  (5091, 16, '57:16', 54, 216, 475, 7, NULL, '۞ أَلَمْ يَأْنِ لِلَّذِينَ ءَامَنُوٓا۟ أَن تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلْحَقِّ وَلَا يَكُونُوا۟ كَٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ مِن قَبْلُ فَطَالَ عَلَيْهِمُ ٱلْأَمَدُ فَقَسَتْ قُلُوبُهُمْ ۖ وَكَثِيرٌ مِّنْهُمْ فَـٰسِقُونَ', 57, 'الم يان للذين امنوا ان تخشع قلوبهم لذكر الله وما نزل من الحق ولا يكونوا كالذين اوتوا الكتاب من قبل فطال عليهم الامد فقست قلوبهم وكثير منهم فاسقون', 539, 27),
  (5092, 17, '57:17', 54, 216, 475, 7, NULL, 'ٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يُحْىِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْـَٔايَـٰتِ لَعَلَّكُمْ تَعْقِلُونَ', 57, 'اعلموا ان الله يحيي الارض بعد موتها قد بينا لكم الايات لعلكم تعقلون', 539, 27),
  (5093, 18, '57:18', 54, 216, 475, 7, NULL, 'إِنَّ ٱلْمُصَّدِّقِينَ وَٱلْمُصَّدِّقَـٰتِ وَأَقْرَضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَـٰعَفُ لَهُمْ وَلَهُمْ أَجْرٌ كَرِيمٌ', 57, 'ان المصدقين والمصدقات واقرضوا الله قرضا حسنا يضاعف لهم ولهم اجر كريم', 539, 27),
  (5094, 19, '57:19', 54, 216, 475, 7, NULL, 'وَٱلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦٓ أُو۟لَـٰٓئِكَ هُمُ ٱلصِّدِّيقُونَ ۖ وَٱلشُّهَدَآءُ عِندَ رَبِّهِمْ لَهُمْ أَجْرُهُمْ وَنُورُهُمْ ۖ وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْجَحِيمِ', 57, 'والذين امنوا بالله ورسله اولئك هم الصديقون والشهداء عند ربهم لهم اجرهم ونورهم والذين كفروا وكذبوا باياتنا اولئك اصحاب الجحيم', 540, 27),
  (5095, 20, '57:20', 54, 216, 476, 7, NULL, 'ٱعْلَمُوٓا۟ أَنَّمَا ٱلْحَيَوٰةُ ٱلدُّنْيَا لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفَاخُرٌۢ بَيْنَكُمْ وَتَكَاثُرٌ فِى ٱلْأَمْوَٰلِ وَٱلْأَوْلَـٰدِ ۖ كَمَثَلِ غَيْثٍ أَعْجَبَ ٱلْكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَكُونُ حُطَـٰمًا ۖ وَفِى ٱلْـَٔاخِرَةِ عَذَابٌ شَدِيدٌ وَمَغْفِرَةٌ مِّنَ ٱللَّهِ وَرِضْوَٰنٌ ۚ وَمَا ٱلْحَيَوٰةُ ٱلدُّنْيَآ إِلَّا مَتَـٰعُ ٱلْغُرُورِ', 57, 'اعلموا انما الحياة الدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر في الاموال والاولاد كمثل غيث اعجب الكفار نباته ثم يهيج فتراه مصفرا ثم يكون حطاما وفي الاخرة عذاب شديد ومغفرة من الله ورضوان وما الحياة الدنيا الا متاع الغرور', 540, 27),
  (5096, 21, '57:21', 54, 216, 476, 7, NULL, 'سَابِقُوٓا۟ إِلَىٰ مَغْفِرَةٍ مِّن رَّبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ ٱلسَّمَآءِ وَٱلْأَرْضِ أُعِدَّتْ لِلَّذِينَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۚ ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 57, 'سابقوا الى مغفرة من ربكم وجنة عرضها كعرض السماء والارض اعدت للذين امنوا بالله ورسله ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم', 540, 27),
  (5097, 22, '57:22', 54, 216, 476, 7, NULL, 'مَآ أَصَابَ مِن مُّصِيبَةٍ فِى ٱلْأَرْضِ وَلَا فِىٓ أَنفُسِكُمْ إِلَّا فِى كِتَـٰبٍ مِّن قَبْلِ أَن نَّبْرَأَهَآ ۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 57, 'ما اصاب من مصيبة في الارض ولا في انفسكم الا في كتاب من قبل ان نبراها ان ذلك على الله يسير', 540, 27),
  (5098, 23, '57:23', 54, 216, 476, 7, NULL, 'لِّكَيْلَا تَأْسَوْا۟ عَلَىٰ مَا فَاتَكُمْ وَلَا تَفْرَحُوا۟ بِمَآ ءَاتَىٰكُمْ ۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ', 57, 'لكيلا تاسوا على ما فاتكم ولا تفرحوا بما اتاكم والله لا يحب كل مختال فخور', 540, 27),
  (5099, 24, '57:24', 54, 216, 476, 7, NULL, 'ٱلَّذِينَ يَبْخَلُونَ وَيَأْمُرُونَ ٱلنَّاسَ بِٱلْبُخْلِ ۗ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 57, 'الذين يبخلون ويامرون الناس بالبخل ومن يتول فان الله هو الغني الحميد', 540, 27),
  (5100, 25, '57:25', 54, 216, 476, 7, NULL, 'لَقَدْ أَرْسَلْنَا رُسُلَنَا بِٱلْبَيِّنَـٰتِ وَأَنزَلْنَا مَعَهُمُ ٱلْكِتَـٰبَ وَٱلْمِيزَانَ لِيَقُومَ ٱلنَّاسُ بِٱلْقِسْطِ ۖ وَأَنزَلْنَا ٱلْحَدِيدَ فِيهِ بَأْسٌ شَدِيدٌ وَمَنَـٰفِعُ لِلنَّاسِ وَلِيَعْلَمَ ٱللَّهُ مَن يَنصُرُهُۥ وَرُسُلَهُۥ بِٱلْغَيْبِ ۚ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ', 57, 'لقد ارسلنا رسلنا بالبينات وانزلنا معهم الكتاب والميزان ليقوم الناس بالقسط وانزلنا الحديد فيه باس شديد ومنافع للناس وليعلم الله من ينصره ورسله بالغيب ان الله قوي عزيز', 541, 27),
  (5101, 26, '57:26', 54, 216, 477, 7, NULL, 'وَلَقَدْ أَرْسَلْنَا نُوحًا وَإِبْرَٰهِيمَ وَجَعَلْنَا فِى ذُرِّيَّتِهِمَا ٱلنُّبُوَّةَ وَٱلْكِتَـٰبَ ۖ فَمِنْهُم مُّهْتَدٍ ۖ وَكَثِيرٌ مِّنْهُمْ فَـٰسِقُونَ', 57, 'ولقد ارسلنا نوحا وابراهيم وجعلنا في ذريتهما النبوة والكتاب فمنهم مهتد وكثير منهم فاسقون', 541, 27),
  (5102, 27, '57:27', 54, 216, 477, 7, NULL, 'ثُمَّ قَفَّيْنَا عَلَىٰٓ ءَاثَـٰرِهِم بِرُسُلِنَا وَقَفَّيْنَا بِعِيسَى ٱبْنِ مَرْيَمَ وَءَاتَيْنَـٰهُ ٱلْإِنجِيلَ وَجَعَلْنَا فِى قُلُوبِ ٱلَّذِينَ ٱتَّبَعُوهُ رَأْفَةً وَرَحْمَةً وَرَهْبَانِيَّةً ٱبْتَدَعُوهَا مَا كَتَبْنَـٰهَا عَلَيْهِمْ إِلَّا ٱبْتِغَآءَ رِضْوَٰنِ ٱللَّهِ فَمَا رَعَوْهَا حَقَّ رِعَايَتِهَا ۖ فَـَٔاتَيْنَا ٱلَّذِينَ ءَامَنُوا۟ مِنْهُمْ أَجْرَهُمْ ۖ وَكَثِيرٌ مِّنْهُمْ فَـٰسِقُونَ', 57, 'ثم قفينا على اثارهم برسلنا وقفينا بعيسى ابن مريم واتيناه الانجيل وجعلنا في قلوب الذين اتبعوه رافة ورحمة ورهبانية ابتدعوها ما كتبناها عليهم الا ابتغاء رضوان الله فما رعوها حق رعايتها فاتينا الذين امنوا منهم اجرهم وكثير منهم فاسقون', 541, 27),
  (5103, 28, '57:28', 54, 216, 477, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِۦ وَيَجْعَل لَّكُمْ نُورًا تَمْشُونَ بِهِۦ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 57, 'يا ايها الذين امنوا اتقوا الله وامنوا برسوله يؤتكم كفلين من رحمته ويجعل لكم نورا تمشون به ويغفر لكم والله غفور رحيم', 541, 27),
  (5104, 29, '57:29', 54, 216, 477, 7, NULL, 'لِّئَلَّا يَعْلَمَ أَهْلُ ٱلْكِتَـٰبِ أَلَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّن فَضْلِ ٱللَّهِ ۙ وَأَنَّ ٱلْفَضْلَ بِيَدِ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 57, 'لئلا يعلم اهل الكتاب الا يقدرون على شيء من فضل الله وان الفضل بيد الله يؤتيه من يشاء والله ذو الفضل العظيم', 541, 27),
  (5105, 1, '58:1', 55, 217, 478, 7, NULL, ' قَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّتِى تُجَـٰدِلُكَ فِى زَوْجِهَا وَتَشْتَكِىٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ ۚ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ', 58, 'قد سمع الله قول التي تجادلك في زوجها وتشتكي الى الله والله يسمع تحاوركما ان الله سميع بصير', 542, 28),
  (5106, 2, '58:2', 55, 217, 478, 7, NULL, 'ٱلَّذِينَ يُظَـٰهِرُونَ مِنكُم مِّن نِّسَآئِهِم مَّا هُنَّ أُمَّهَـٰتِهِمْ ۖ إِنْ أُمَّهَـٰتُهُمْ إِلَّا ٱلَّـٰٓـِٔى وَلَدْنَهُمْ ۚ وَإِنَّهُمْ لَيَقُولُونَ مُنكَرًا مِّنَ ٱلْقَوْلِ وَزُورًا ۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٌ', 58, 'الذين يظاهرون منكم من نسائهم ما هن امهاتهم ان امهاتهم الا اللائي ولدنهم وانهم ليقولون منكرا من القول وزورا وان الله لعفو غفور', 542, 28),
  (5107, 3, '58:3', 55, 217, 478, 7, NULL, 'وَٱلَّذِينَ يُظَـٰهِرُونَ مِن نِّسَآئِهِمْ ثُمَّ يَعُودُونَ لِمَا قَالُوا۟ فَتَحْرِيرُ رَقَبَةٍ مِّن قَبْلِ أَن يَتَمَآسَّا ۚ ذَٰلِكُمْ تُوعَظُونَ بِهِۦ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 58, 'والذين يظاهرون من نسائهم ثم يعودون لما قالوا فتحرير رقبة من قبل ان يتماسا ذلكم توعظون به والله بما تعملون خبير', 542, 28),
  (5108, 4, '58:4', 55, 217, 478, 7, NULL, 'فَمَن لَّمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ مِن قَبْلِ أَن يَتَمَآسَّا ۖ فَمَن لَّمْ يَسْتَطِعْ فَإِطْعَامُ سِتِّينَ مِسْكِينًا ۚ ذَٰلِكَ لِتُؤْمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۗ وَلِلْكَـٰفِرِينَ عَذَابٌ أَلِيمٌ', 58, 'فمن لم يجد فصيام شهرين متتابعين من قبل ان يتماسا فمن لم يستطع فاطعام ستين مسكينا ذلك لتؤمنوا بالله ورسوله وتلك حدود الله وللكافرين عذاب اليم', 542, 28),
  (5109, 5, '58:5', 55, 217, 478, 7, NULL, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِينَ مِن قَبْلِهِمْ ۚ وَقَدْ أَنزَلْنَآ ءَايَـٰتٍۭ بَيِّنَـٰتٍ ۚ وَلِلْكَـٰفِرِينَ عَذَابٌ مُّهِينٌ', 58, 'ان الذين يحادون الله ورسوله كبتوا كما كبت الذين من قبلهم وقد انزلنا ايات بينات وللكافرين عذاب مهين', 542, 28),
  (5110, 6, '58:6', 55, 217, 478, 7, NULL, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيُنَبِّئُهُم بِمَا عَمِلُوٓا۟ ۚ أَحْصَىٰهُ ٱللَّهُ وَنَسُوهُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 58, 'يوم يبعثهم الله جميعا فينبئهم بما عملوا احصاه الله ونسوه والله على كل شيء شهيد', 542, 28),
  (5111, 7, '58:7', 55, 217, 479, 7, NULL, 'أَلَمْ تَرَ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ مَا يَكُونُ مِن نَّجْوَىٰ ثَلَـٰثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَآ أَدْنَىٰ مِن ذَٰلِكَ وَلَآ أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا۟ ۖ ثُمَّ يُنَبِّئُهُم بِمَا عَمِلُوا۟ يَوْمَ ٱلْقِيَـٰمَةِ ۚ إِنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ', 58, 'الم تر ان الله يعلم ما في السماوات وما في الارض ما يكون من نجوى ثلاثة الا هو رابعهم ولا خمسة الا هو سادسهم ولا ادنى من ذلك ولا اكثر الا هو معهم اين ما كانوا ثم ينبئهم بما عملوا يوم القيامة ان الله بكل شيء عليم', 543, 28),
  (5112, 8, '58:8', 55, 217, 479, 7, NULL, 'أَلَمْ تَرَ إِلَى ٱلَّذِينَ نُهُوا۟ عَنِ ٱلنَّجْوَىٰ ثُمَّ يَعُودُونَ لِمَا نُهُوا۟ عَنْهُ وَيَتَنَـٰجَوْنَ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَإِذَا جَآءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ ٱللَّهُ وَيَقُولُونَ فِىٓ أَنفُسِهِمْ لَوْلَا يُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُ ۚ حَسْبُهُمْ جَهَنَّمُ يَصْلَوْنَهَا ۖ فَبِئْسَ ٱلْمَصِيرُ', 58, 'الم تر الى الذين نهوا عن النجوى ثم يعودون لما نهوا عنه ويتناجون بالاثم والعدوان ومعصيت الرسول واذا جاءوك حيوك بما لم يحيك به الله ويقولون في انفسهم لولا يعذبنا الله بما نقول حسبهم جهنم يصلونها فبئس المصير', 543, 28),
  (5113, 9, '58:9', 55, 217, 479, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَنَـٰجَيْتُمْ فَلَا تَتَنَـٰجَوْا۟ بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَمَعْصِيَتِ ٱلرَّسُولِ وَتَنَـٰجَوْا۟ بِٱلْبِرِّ وَٱلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ إِلَيْهِ تُحْشَرُونَ', 58, 'يا ايها الذين امنوا اذا تناجيتم فلا تتناجوا بالاثم والعدوان ومعصيت الرسول وتناجوا بالبر والتقوى واتقوا الله الذي اليه تحشرون', 543, 28),
  (5114, 10, '58:10', 55, 217, 479, 7, NULL, 'إِنَّمَا ٱلنَّجْوَىٰ مِنَ ٱلشَّيْطَـٰنِ لِيَحْزُنَ ٱلَّذِينَ ءَامَنُوا۟ وَلَيْسَ بِضَآرِّهِمْ شَيْـًٔا إِلَّا بِإِذْنِ ٱللَّهِ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 58, 'انما النجوى من الشيطان ليحزن الذين امنوا وليس بضارهم شيئا الا باذن الله وعلى الله فليتوكل المؤمنون', 543, 28),
  (5115, 11, '58:11', 55, 217, 479, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا قِيلَ لَكُمْ تَفَسَّحُوا۟ فِى ٱلْمَجَـٰلِسِ فَٱفْسَحُوا۟ يَفْسَحِ ٱللَّهُ لَكُمْ ۖ وَإِذَا قِيلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ يَرْفَعِ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ دَرَجَـٰتٍ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 58, 'يا ايها الذين امنوا اذا قيل لكم تفسحوا في المجالس فافسحوا يفسح الله لكم واذا قيل انشزوا فانشزوا يرفع الله الذين امنوا منكم والذين اوتوا العلم درجات والله بما تعملون خبير', 543, 28),
  (5116, 12, '58:12', 55, 217, 479, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَـٰجَيْتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَةً ۚ ذَٰلِكَ خَيْرٌ لَّكُمْ وَأَطْهَرُ ۚ فَإِن لَّمْ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 58, 'يا ايها الذين امنوا اذا ناجيتم الرسول فقدموا بين يدي نجواكم صدقة ذلك خير لكم واطهر فان لم تجدوا فان الله غفور رحيم', 544, 28),
  (5117, 13, '58:13', 55, 217, 479, 7, NULL, 'ءَأَشْفَقْتُمْ أَن تُقَدِّمُوا۟ بَيْنَ يَدَىْ نَجْوَىٰكُمْ صَدَقَـٰتٍ ۚ فَإِذْ لَمْ تَفْعَلُوا۟ وَتَابَ ٱللَّهُ عَلَيْكُمْ فَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِيعُوا۟ ٱللَّهَ وَرَسُولَهُۥ ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 58, 'ااشفقتم ان تقدموا بين يدي نجواكم صدقات فاذ لم تفعلوا وتاب الله عليكم فاقيموا الصلاة واتوا الزكاة واطيعوا الله ورسوله والله خبير بما تعملون', 544, 28),
  (5118, 14, '58:14', 55, 218, 480, 7, NULL, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ تَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِم مَّا هُم مِّنكُمْ وَلَا مِنْهُمْ وَيَحْلِفُونَ عَلَى ٱلْكَذِبِ وَهُمْ يَعْلَمُونَ', 58, 'الم تر الى الذين تولوا قوما غضب الله عليهم ما هم منكم ولا منهم ويحلفون على الكذب وهم يعلمون', 544, 28),
  (5119, 15, '58:15', 55, 218, 480, 7, NULL, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا ۖ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 58, 'اعد الله لهم عذابا شديدا انهم ساء ما كانوا يعملون', 544, 28),
  (5120, 16, '58:16', 55, 218, 480, 7, NULL, 'ٱتَّخَذُوٓا۟ أَيْمَـٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ فَلَهُمْ عَذَابٌ مُّهِينٌ', 58, 'اتخذوا ايمانهم جنة فصدوا عن سبيل الله فلهم عذاب مهين', 544, 28),
  (5121, 17, '58:17', 55, 218, 480, 7, NULL, 'لَّن تُغْنِىَ عَنْهُمْ أَمْوَٰلُهُمْ وَلَآ أَوْلَـٰدُهُم مِّنَ ٱللَّهِ شَيْـًٔا ۚ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَـٰلِدُونَ', 58, 'لن تغني عنهم اموالهم ولا اولادهم من الله شيئا اولئك اصحاب النار هم فيها خالدون', 544, 28),
  (5122, 18, '58:18', 55, 218, 480, 7, NULL, 'يَوْمَ يَبْعَثُهُمُ ٱللَّهُ جَمِيعًا فَيَحْلِفُونَ لَهُۥ كَمَا يَحْلِفُونَ لَكُمْ ۖ وَيَحْسَبُونَ أَنَّهُمْ عَلَىٰ شَىْءٍ ۚ أَلَآ إِنَّهُمْ هُمُ ٱلْكَـٰذِبُونَ', 58, 'يوم يبعثهم الله جميعا فيحلفون له كما يحلفون لكم ويحسبون انهم على شيء الا انهم هم الكاذبون', 544, 28),
  (5123, 19, '58:19', 55, 218, 480, 7, NULL, 'ٱسْتَحْوَذَ عَلَيْهِمُ ٱلشَّيْطَـٰنُ فَأَنسَىٰهُمْ ذِكْرَ ٱللَّهِ ۚ أُو۟لَـٰٓئِكَ حِزْبُ ٱلشَّيْطَـٰنِ ۚ أَلَآ إِنَّ حِزْبَ ٱلشَّيْطَـٰنِ هُمُ ٱلْخَـٰسِرُونَ', 58, 'استحوذ عليهم الشيطان فانساهم ذكر الله اولئك حزب الشيطان الا ان حزب الشيطان هم الخاسرون', 544, 28),
  (5124, 20, '58:20', 55, 218, 480, 7, NULL, 'إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥٓ أُو۟لَـٰٓئِكَ فِى ٱلْأَذَلِّينَ', 58, 'ان الذين يحادون الله ورسوله اولئك في الاذلين', 544, 28),
  (5125, 21, '58:21', 55, 218, 480, 7, NULL, 'كَتَبَ ٱللَّهُ لَأَغْلِبَنَّ أَنَا۠ وَرُسُلِىٓ ۚ إِنَّ ٱللَّهَ قَوِىٌّ عَزِيزٌ', 58, 'كتب الله لاغلبن انا ورسلي ان الله قوي عزيز', 544, 28),
  (5126, 22, '58:22', 55, 218, 480, 7, NULL, 'لَّا تَجِدُ قَوْمًا يُؤْمِنُونَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ يُوَآدُّونَ مَنْ حَآدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوْ كَانُوٓا۟ ءَابَآءَهُمْ أَوْ أَبْنَآءَهُمْ أَوْ إِخْوَٰنَهُمْ أَوْ عَشِيرَتَهُمْ ۚ أُو۟لَـٰٓئِكَ كَتَبَ فِى قُلُوبِهِمُ ٱلْإِيمَـٰنَ وَأَيَّدَهُم بِرُوحٍ مِّنْهُ ۖ وَيُدْخِلُهُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَا ۚ رَضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ أُو۟لَـٰٓئِكَ حِزْبُ ٱللَّهِ ۚ أَلَآ إِنَّ حِزْبَ ٱللَّهِ هُمُ ٱلْمُفْلِحُونَ', 58, 'لا تجد قوما يؤمنون بالله واليوم الاخر يوادون من حاد الله ورسوله ولو كانوا اباءهم او ابناءهم او اخوانهم او عشيرتهم اولئك كتب في قلوبهم الايمان وايدهم بروح منه ويدخلهم جنات تجري من تحتها الانهار خالدين فيها رضي الله عنهم ورضوا عنه اولئك حزب الله الا ان حزب الله هم المفلحون', 545, 28),
  (5127, 1, '59:1', 55, 218, 481, 7, NULL, ' سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 59, 'سبح لله ما في السماوات وما في الارض وهو العزيز الحكيم', 545, 28),
  (5128, 2, '59:2', 55, 218, 481, 7, NULL, 'هُوَ ٱلَّذِىٓ أَخْرَجَ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ مِن دِيَـٰرِهِمْ لِأَوَّلِ ٱلْحَشْرِ ۚ مَا ظَنَنتُمْ أَن يَخْرُجُوا۟ ۖ وَظَنُّوٓا۟ أَنَّهُم مَّانِعَتُهُمْ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا۟ ۖ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ ۚ يُخْرِبُونَ بُيُوتَهُم بِأَيْدِيهِمْ وَأَيْدِى ٱلْمُؤْمِنِينَ فَٱعْتَبِرُوا۟ يَـٰٓأُو۟لِى ٱلْأَبْصَـٰرِ', 59, 'هو الذي اخرج الذين كفروا من اهل الكتاب من ديارهم لاول الحشر ما ظننتم ان يخرجوا وظنوا انهم مانعتهم حصونهم من الله فاتاهم الله من حيث لم يحتسبوا وقذف في قلوبهم الرعب يخربون بيوتهم بايديهم وايدي المؤمنين فاعتبروا يا اولي الابصار', 545, 28),
  (5129, 3, '59:3', 55, 218, 481, 7, NULL, 'وَلَوْلَآ أَن كَتَبَ ٱللَّهُ عَلَيْهِمُ ٱلْجَلَآءَ لَعَذَّبَهُمْ فِى ٱلدُّنْيَا ۖ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابُ ٱلنَّارِ', 59, 'ولولا ان كتب الله عليهم الجلاء لعذبهم في الدنيا ولهم في الاخرة عذاب النار', 545, 28),
  (5130, 4, '59:4', 55, 218, 481, 7, NULL, 'ذَٰلِكَ بِأَنَّهُمْ شَآقُّوا۟ ٱللَّهَ وَرَسُولَهُۥ ۖ وَمَن يُشَآقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 59, 'ذلك بانهم شاقوا الله ورسوله ومن يشاق الله فان الله شديد العقاب', 546, 28),
  (5131, 5, '59:5', 55, 218, 481, 7, NULL, 'مَا قَطَعْتُم مِّن لِّينَةٍ أَوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ٱللَّهِ وَلِيُخْزِىَ ٱلْفَـٰسِقِينَ', 59, 'ما قطعتم من لينة او تركتموها قائمة على اصولها فباذن الله وليخزي الفاسقين', 546, 28),
  (5132, 6, '59:6', 55, 218, 481, 7, NULL, 'وَمَآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْهُمْ فَمَآ أَوْجَفْتُمْ عَلَيْهِ مِنْ خَيْلٍ وَلَا رِكَابٍ وَلَـٰكِنَّ ٱللَّهَ يُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن يَشَآءُ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 59, 'وما افاء الله على رسوله منهم فما اوجفتم عليه من خيل ولا ركاب ولكن الله يسلط رسله على من يشاء والله على كل شيء قدير', 546, 28),
  (5133, 7, '59:7', 55, 218, 481, 7, NULL, 'مَّآ أَفَآءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنْ أَهْلِ ٱلْقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَٱبْنِ ٱلسَّبِيلِ كَىْ لَا يَكُونَ دُولَةًۢ بَيْنَ ٱلْأَغْنِيَآءِ مِنكُمْ ۚ وَمَآ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمْ عَنْهُ فَٱنتَهُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ', 59, 'ما افاء الله على رسوله من اهل القرى فلله وللرسول ولذي القربى واليتامى والمساكين وابن السبيل كي لا يكون دولة بين الاغنياء منكم وما اتاكم الرسول فخذوه وما نهاكم عنه فانتهوا واتقوا الله ان الله شديد العقاب', 546, 28),
  (5134, 8, '59:8', 55, 218, 481, 7, NULL, 'لِلْفُقَرَآءِ ٱلْمُهَـٰجِرِينَ ٱلَّذِينَ أُخْرِجُوا۟ مِن دِيَـٰرِهِمْ وَأَمْوَٰلِهِمْ يَبْتَغُونَ فَضْلًا مِّنَ ٱللَّهِ وَرِضْوَٰنًا وَيَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلصَّـٰدِقُونَ', 59, 'للفقراء المهاجرين الذين اخرجوا من ديارهم واموالهم يبتغون فضلا من الله ورضوانا وينصرون الله ورسوله اولئك هم الصادقون', 546, 28),
  (5135, 9, '59:9', 55, 218, 481, 7, NULL, 'وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلْإِيمَـٰنَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِى صُدُورِهِمْ حَاجَةً مِّمَّآ أُوتُوا۟ وَيُؤْثِرُونَ عَلَىٰٓ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ ۚ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 59, 'والذين تبوءوا الدار والايمان من قبلهم يحبون من هاجر اليهم ولا يجدون في صدورهم حاجة مما اوتوا ويؤثرون على انفسهم ولو كان بهم خصاصة ومن يوق شح نفسه فاولئك هم المفلحون', 546, 28),
  (5136, 10, '59:10', 55, 218, 481, 7, NULL, 'وَٱلَّذِينَ جَآءُو مِنۢ بَعْدِهِمْ يَقُولُونَ رَبَّنَا ٱغْفِرْ لَنَا وَلِإِخْوَٰنِنَا ٱلَّذِينَ سَبَقُونَا بِٱلْإِيمَـٰنِ وَلَا تَجْعَلْ فِى قُلُوبِنَا غِلًّا لِّلَّذِينَ ءَامَنُوا۟ رَبَّنَآ إِنَّكَ رَءُوفٌ رَّحِيمٌ', 59, 'والذين جاءوا من بعدهم يقولون ربنا اغفر لنا ولاخواننا الذين سبقونا بالايمان ولا تجعل في قلوبنا غلا للذين امنوا ربنا انك رءوف رحيم', 547, 28),
  (5137, 11, '59:11', 55, 219, 482, 7, NULL, '۞ أَلَمْ تَرَ إِلَى ٱلَّذِينَ نَافَقُوا۟ يَقُولُونَ لِإِخْوَٰنِهِمُ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ لَئِنْ أُخْرِجْتُمْ لَنَخْرُجَنَّ مَعَكُمْ وَلَا نُطِيعُ فِيكُمْ أَحَدًا أَبَدًا وَإِن قُوتِلْتُمْ لَنَنصُرَنَّكُمْ وَٱللَّهُ يَشْهَدُ إِنَّهُمْ لَكَـٰذِبُونَ', 59, 'الم تر الى الذين نافقوا يقولون لاخوانهم الذين كفروا من اهل الكتاب لئن اخرجتم لنخرجن معكم ولا نطيع فيكم احدا ابدا وان قوتلتم لننصرنكم والله يشهد انهم لكاذبون', 547, 28),
  (5138, 12, '59:12', 55, 219, 482, 7, NULL, 'لَئِنْ أُخْرِجُوا۟ لَا يَخْرُجُونَ مَعَهُمْ وَلَئِن قُوتِلُوا۟ لَا يَنصُرُونَهُمْ وَلَئِن نَّصَرُوهُمْ لَيُوَلُّنَّ ٱلْأَدْبَـٰرَ ثُمَّ لَا يُنصَرُونَ', 59, 'لئن اخرجوا لا يخرجون معهم ولئن قوتلوا لا ينصرونهم ولئن نصروهم ليولن الادبار ثم لا ينصرون', 547, 28),
  (5139, 13, '59:13', 55, 219, 482, 7, NULL, 'لَأَنتُمْ أَشَدُّ رَهْبَةً فِى صُدُورِهِم مِّنَ ٱللَّهِ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَفْقَهُونَ', 59, 'لانتم اشد رهبة في صدورهم من الله ذلك بانهم قوم لا يفقهون', 547, 28),
  (5140, 14, '59:14', 55, 219, 482, 7, NULL, 'لَا يُقَـٰتِلُونَكُمْ جَمِيعًا إِلَّا فِى قُرًى مُّحَصَّنَةٍ أَوْ مِن وَرَآءِ جُدُرٍۭ ۚ بَأْسُهُم بَيْنَهُمْ شَدِيدٌ ۚ تَحْسَبُهُمْ جَمِيعًا وَقُلُوبُهُمْ شَتَّىٰ ۚ ذَٰلِكَ بِأَنَّهُمْ قَوْمٌ لَّا يَعْقِلُونَ', 59, 'لا يقاتلونكم جميعا الا في قرى محصنة او من وراء جدر باسهم بينهم شديد تحسبهم جميعا وقلوبهم شتى ذلك بانهم قوم لا يعقلون', 547, 28),
  (5141, 15, '59:15', 55, 219, 482, 7, NULL, 'كَمَثَلِ ٱلَّذِينَ مِن قَبْلِهِمْ قَرِيبًا ۖ ذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 59, 'كمثل الذين من قبلهم قريبا ذاقوا وبال امرهم ولهم عذاب اليم', 547, 28),
  (5142, 16, '59:16', 55, 219, 482, 7, NULL, 'كَمَثَلِ ٱلشَّيْطَـٰنِ إِذْ قَالَ لِلْإِنسَـٰنِ ٱكْفُرْ فَلَمَّا كَفَرَ قَالَ إِنِّى بَرِىٓءٌ مِّنكَ إِنِّىٓ أَخَافُ ٱللَّهَ رَبَّ ٱلْعَـٰلَمِينَ', 59, 'كمثل الشيطان اذ قال للانسان اكفر فلما كفر قال اني بريء منك اني اخاف الله رب العالمين', 547, 28),
  (5143, 17, '59:17', 55, 219, 482, 7, NULL, 'فَكَانَ عَـٰقِبَتَهُمَآ أَنَّهُمَا فِى ٱلنَّارِ خَـٰلِدَيْنِ فِيهَا ۚ وَذَٰلِكَ جَزَٰٓؤُا۟ ٱلظَّـٰلِمِينَ', 59, 'فكان عاقبتهما انهما في النار خالدين فيها وذلك جزاء الظالمين', 548, 28),
  (5144, 18, '59:18', 55, 219, 483, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلْتَنظُرْ نَفْسٌ مَّا قَدَّمَتْ لِغَدٍ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 59, 'يا ايها الذين امنوا اتقوا الله ولتنظر نفس ما قدمت لغد واتقوا الله ان الله خبير بما تعملون', 548, 28),
  (5145, 19, '59:19', 55, 219, 483, 7, NULL, 'وَلَا تَكُونُوا۟ كَٱلَّذِينَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمْ أَنفُسَهُمْ ۚ أُو۟لَـٰٓئِكَ هُمُ ٱلْفَـٰسِقُونَ', 59, 'ولا تكونوا كالذين نسوا الله فانساهم انفسهم اولئك هم الفاسقون', 548, 28),
  (5146, 20, '59:20', 55, 219, 483, 7, NULL, 'لَا يَسْتَوِىٓ أَصْحَـٰبُ ٱلنَّارِ وَأَصْحَـٰبُ ٱلْجَنَّةِ ۚ أَصْحَـٰبُ ٱلْجَنَّةِ هُمُ ٱلْفَآئِزُونَ', 59, 'لا يستوي اصحاب النار واصحاب الجنة اصحاب الجنة هم الفائزون', 548, 28),
  (5147, 21, '59:21', 55, 219, 483, 7, NULL, 'لَوْ أَنزَلْنَا هَـٰذَا ٱلْقُرْءَانَ عَلَىٰ جَبَلٍ لَّرَأَيْتَهُۥ خَـٰشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ ٱللَّهِ ۚ وَتِلْكَ ٱلْأَمْثَـٰلُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ', 59, 'لو انزلنا هذا القران على جبل لرايته خاشعا متصدعا من خشية الله وتلك الامثال نضربها للناس لعلهم يتفكرون', 548, 28),
  (5148, 22, '59:22', 55, 219, 483, 7, NULL, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَـٰهَ إِلَّا هُوَ ۖ عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ۖ هُوَ ٱلرَّحْمَـٰنُ ٱلرَّحِيمُ', 59, 'هو الله الذي لا اله الا هو عالم الغيب والشهادة هو الرحمن الرحيم', 548, 28),
  (5149, 23, '59:23', 55, 219, 483, 7, NULL, 'هُوَ ٱللَّهُ ٱلَّذِى لَآ إِلَـٰهَ إِلَّا هُوَ ٱلْمَلِكُ ٱلْقُدُّوسُ ٱلسَّلَـٰمُ ٱلْمُؤْمِنُ ٱلْمُهَيْمِنُ ٱلْعَزِيزُ ٱلْجَبَّارُ ٱلْمُتَكَبِّرُ ۚ سُبْحَـٰنَ ٱللَّهِ عَمَّا يُشْرِكُونَ', 59, 'هو الله الذي لا اله الا هو الملك القدوس السلام المؤمن المهيمن العزيز الجبار المتكبر سبحان الله عما يشركون', 548, 28),
  (5150, 24, '59:24', 55, 219, 483, 7, NULL, 'هُوَ ٱللَّهُ ٱلْخَـٰلِقُ ٱلْبَارِئُ ٱلْمُصَوِّرُ ۖ لَهُ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ ۚ يُسَبِّحُ لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 59, 'هو الله الخالق البارئ المصور له الاسماء الحسنى يسبح له ما في السماوات والارض وهو العزيز الحكيم', 548, 28),
  (5151, 1, '60:1', 55, 219, 484, 7, NULL, ' يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّى وَعَدُوَّكُمْ أَوْلِيَآءَ تُلْقُونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَقَدْ كَفَرُوا۟ بِمَا جَآءَكُم مِّنَ ٱلْحَقِّ يُخْرِجُونَ ٱلرَّسُولَ وَإِيَّاكُمْ ۙ أَن تُؤْمِنُوا۟ بِٱللَّهِ رَبِّكُمْ إِن كُنتُمْ خَرَجْتُمْ جِهَـٰدًا فِى سَبِيلِى وَٱبْتِغَآءَ مَرْضَاتِى ۚ تُسِرُّونَ إِلَيْهِم بِٱلْمَوَدَّةِ وَأَنَا۠ أَعْلَمُ بِمَآ أَخْفَيْتُمْ وَمَآ أَعْلَنتُمْ ۚ وَمَن يَفْعَلْهُ مِنكُمْ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ', 60, 'يا ايها الذين امنوا لا تتخذوا عدوي وعدوكم اولياء تلقون اليهم بالمودة وقد كفروا بما جاءكم من الحق يخرجون الرسول واياكم ان تؤمنوا بالله ربكم ان كنتم خرجتم جهادا في سبيلي وابتغاء مرضاتي تسرون اليهم بالمودة وانا اعلم بما اخفيتم وما اعلنتم ومن يفعله منكم فقد ضل سواء السبيل', 549, 28),
  (5152, 2, '60:2', 55, 219, 484, 7, NULL, 'إِن يَثْقَفُوكُمْ يَكُونُوا۟ لَكُمْ أَعْدَآءً وَيَبْسُطُوٓا۟ إِلَيْكُمْ أَيْدِيَهُمْ وَأَلْسِنَتَهُم بِٱلسُّوٓءِ وَوَدُّوا۟ لَوْ تَكْفُرُونَ', 60, 'ان يثقفوكم يكونوا لكم اعداء ويبسطوا اليكم ايديهم والسنتهم بالسوء وودوا لو تكفرون', 549, 28),
  (5153, 3, '60:3', 55, 219, 484, 7, NULL, 'لَن تَنفَعَكُمْ أَرْحَامُكُمْ وَلَآ أَوْلَـٰدُكُمْ ۚ يَوْمَ ٱلْقِيَـٰمَةِ يَفْصِلُ بَيْنَكُمْ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 60, 'لن تنفعكم ارحامكم ولا اولادكم يوم القيامة يفصل بينكم والله بما تعملون بصير', 549, 28),
  (5154, 4, '60:4', 55, 219, 484, 7, NULL, 'قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِىٓ إِبْرَٰهِيمَ وَٱلَّذِينَ مَعَهُۥٓ إِذْ قَالُوا۟ لِقَوْمِهِمْ إِنَّا بُرَءَٰٓؤُا۟ مِنكُمْ وَمِمَّا تَعْبُدُونَ مِن دُونِ ٱللَّهِ كَفَرْنَا بِكُمْ وَبَدَا بَيْنَنَا وَبَيْنَكُمُ ٱلْعَدَٰوَةُ وَٱلْبَغْضَآءُ أَبَدًا حَتَّىٰ تُؤْمِنُوا۟ بِٱللَّهِ وَحْدَهُۥٓ إِلَّا قَوْلَ إِبْرَٰهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ وَمَآ أَمْلِكُ لَكَ مِنَ ٱللَّهِ مِن شَىْءٍ ۖ رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ ٱلْمَصِيرُ', 60, 'قد كانت لكم اسوة حسنة في ابراهيم والذين معه اذ قالوا لقومهم انا براء منكم ومما تعبدون من دون الله كفرنا بكم وبدا بيننا وبينكم العداوة والبغضاء ابدا حتى تؤمنوا بالله وحده الا قول ابراهيم لابيه لاستغفرن لك وما املك لك من الله من شيء ربنا عليك توكلنا واليك انبنا واليك المصير', 549, 28),
  (5155, 5, '60:5', 55, 219, 484, 7, NULL, 'رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ وَٱغْفِرْ لَنَا رَبَّنَآ ۖ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 60, 'ربنا لا تجعلنا فتنة للذين كفروا واغفر لنا ربنا انك انت العزيز الحكيم', 549, 28),
  (5156, 6, '60:6', 55, 219, 484, 7, NULL, 'لَقَدْ كَانَ لَكُمْ فِيهِمْ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْـَٔاخِرَ ۚ وَمَن يَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ', 60, 'لقد كان لكم فيهم اسوة حسنة لمن كان يرجو الله واليوم الاخر ومن يتول فان الله هو الغني الحميد', 550, 28),
  (5157, 7, '60:7', 55, 220, 485, 7, NULL, '۞ عَسَى ٱللَّهُ أَن يَجْعَلَ بَيْنَكُمْ وَبَيْنَ ٱلَّذِينَ عَادَيْتُم مِّنْهُم مَّوَدَّةً ۚ وَٱللَّهُ قَدِيرٌ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 60, 'عسى الله ان يجعل بينكم وبين الذين عاديتم منهم مودة والله قدير والله غفور رحيم', 550, 28),
  (5158, 8, '60:8', 55, 220, 485, 7, NULL, 'لَّا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمْ يُقَـٰتِلُوكُمْ فِى ٱلدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَـٰرِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓا۟ إِلَيْهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ', 60, 'لا ينهاكم الله عن الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم ان تبروهم وتقسطوا اليهم ان الله يحب المقسطين', 550, 28),
  (5159, 9, '60:9', 55, 220, 485, 7, NULL, 'إِنَّمَا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ قَـٰتَلُوكُمْ فِى ٱلدِّينِ وَأَخْرَجُوكُم مِّن دِيَـٰرِكُمْ وَظَـٰهَرُوا۟ عَلَىٰٓ إِخْرَاجِكُمْ أَن تَوَلَّوْهُمْ ۚ وَمَن يَتَوَلَّهُمْ فَأُو۟لَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ', 60, 'انما ينهاكم الله عن الذين قاتلوكم في الدين واخرجوكم من دياركم وظاهروا على اخراجكم ان تولوهم ومن يتولهم فاولئك هم الظالمون', 550, 28),
  (5160, 10, '60:10', 55, 220, 485, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا جَآءَكُمُ ٱلْمُؤْمِنَـٰتُ مُهَـٰجِرَٰتٍ فَٱمْتَحِنُوهُنَّ ۖ ٱللَّهُ أَعْلَمُ بِإِيمَـٰنِهِنَّ ۖ فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَـٰتٍ فَلَا تَرْجِعُوهُنَّ إِلَى ٱلْكُفَّارِ ۖ لَا هُنَّ حِلٌّ لَّهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ ۖ وَءَاتُوهُم مَّآ أَنفَقُوا۟ ۚ وَلَا جُنَاحَ عَلَيْكُمْ أَن تَنكِحُوهُنَّ إِذَآ ءَاتَيْتُمُوهُنَّ أُجُورَهُنَّ ۚ وَلَا تُمْسِكُوا۟ بِعِصَمِ ٱلْكَوَافِرِ وَسْـَٔلُوا۟ مَآ أَنفَقْتُمْ وَلْيَسْـَٔلُوا۟ مَآ أَنفَقُوا۟ ۚ ذَٰلِكُمْ حُكْمُ ٱللَّهِ ۖ يَحْكُمُ بَيْنَكُمْ ۚ وَٱللَّهُ عَلِيمٌ حَكِيمٌ', 60, 'يا ايها الذين امنوا اذا جاءكم المؤمنات مهاجرات فامتحنوهن الله اعلم بايمانهن فان علمتموهن مؤمنات فلا ترجعوهن الى الكفار لا هن حل لهم ولا هم يحلون لهن واتوهم ما انفقوا ولا جناح عليكم ان تنكحوهن اذا اتيتموهن اجورهن ولا تمسكوا بعصم الكوافر واسالوا ما انفقتم وليسالوا ما انفقوا ذلكم حكم الله يحكم بينكم والله عليم حكيم', 550, 28),
  (5161, 11, '60:11', 55, 220, 485, 7, NULL, 'وَإِن فَاتَكُمْ شَىْءٌ مِّنْ أَزْوَٰجِكُمْ إِلَى ٱلْكُفَّارِ فَعَاقَبْتُمْ فَـَٔاتُوا۟ ٱلَّذِينَ ذَهَبَتْ أَزْوَٰجُهُم مِّثْلَ مَآ أَنفَقُوا۟ ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِىٓ أَنتُم بِهِۦ مُؤْمِنُونَ', 60, 'وان فاتكم شيء من ازواجكم الى الكفار فعاقبتم فاتوا الذين ذهبت ازواجهم مثل ما انفقوا واتقوا الله الذي انتم به مؤمنون', 550, 28),
  (5162, 12, '60:12', 55, 220, 485, 7, NULL, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا جَآءَكَ ٱلْمُؤْمِنَـٰتُ يُبَايِعْنَكَ عَلَىٰٓ أَن لَّا يُشْرِكْنَ بِٱللَّهِ شَيْـًٔا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ وَلَا يَقْتُلْنَ أَوْلَـٰدَهُنَّ وَلَا يَأْتِينَ بِبُهْتَـٰنٍ يَفْتَرِينَهُۥ بَيْنَ أَيْدِيهِنَّ وَأَرْجُلِهِنَّ وَلَا يَعْصِينَكَ فِى مَعْرُوفٍ ۙ فَبَايِعْهُنَّ وَٱسْتَغْفِرْ لَهُنَّ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 60, 'يا ايها النبي اذا جاءك المؤمنات يبايعنك على ان لا يشركن بالله شيئا ولا يسرقن ولا يزنين ولا يقتلن اولادهن ولا ياتين ببهتان يفترينه بين ايديهن وارجلهن ولا يعصينك في معروف فبايعهن واستغفر لهن الله ان الله غفور رحيم', 551, 28),
  (5163, 13, '60:13', 55, 220, 485, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَتَوَلَّوْا۟ قَوْمًا غَضِبَ ٱللَّهُ عَلَيْهِمْ قَدْ يَئِسُوا۟ مِنَ ٱلْـَٔاخِرَةِ كَمَا يَئِسَ ٱلْكُفَّارُ مِنْ أَصْحَـٰبِ ٱلْقُبُورِ', 60, 'يا ايها الذين امنوا لا تتولوا قوما غضب الله عليهم قد يئسوا من الاخرة كما يئس الكفار من اصحاب القبور', 551, 28),
  (5164, 1, '61:1', 55, 220, 486, 7, NULL, ' سَبَّحَ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 61, 'سبح لله ما في السماوات وما في الارض وهو العزيز الحكيم', 551, 28),
  (5165, 2, '61:2', 55, 220, 486, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ', 61, 'يا ايها الذين امنوا لم تقولون ما لا تفعلون', 551, 28),
  (5166, 3, '61:3', 55, 220, 486, 7, NULL, 'كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ', 61, 'كبر مقتا عند الله ان تقولوا ما لا تفعلون', 551, 28),
  (5167, 4, '61:4', 55, 220, 486, 7, NULL, 'إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَـٰتِلُونَ فِى سَبِيلِهِۦ صَفًّا كَأَنَّهُم بُنْيَـٰنٌ مَّرْصُوصٌ', 61, 'ان الله يحب الذين يقاتلون في سبيله صفا كانهم بنيان مرصوص', 551, 28),
  (5168, 5, '61:5', 55, 220, 486, 7, NULL, 'وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَـٰقَوْمِ لِمَ تُؤْذُونَنِى وَقَد تَّعْلَمُونَ أَنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ ۖ فَلَمَّا زَاغُوٓا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمْ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ', 61, 'واذ قال موسى لقومه يا قوم لم تؤذونني وقد تعلمون اني رسول الله اليكم فلما زاغوا ازاغ الله قلوبهم والله لا يهدي القوم الفاسقين', 551, 28),
  (5169, 6, '61:6', 55, 220, 486, 7, NULL, 'وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَـٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ ۖ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَـٰتِ قَالُوا۟ هَـٰذَا سِحْرٌ مُّبِينٌ', 61, 'واذ قال عيسى ابن مريم يا بني اسرائيل اني رسول الله اليكم مصدقا لما بين يدي من التوراة ومبشرا برسول ياتي من بعدي اسمه احمد فلما جاءهم بالبينات قالوا هذا سحر مبين', 552, 28),
  (5170, 7, '61:7', 55, 220, 486, 7, NULL, 'وَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ ٱلْكَذِبَ وَهُوَ يُدْعَىٰٓ إِلَى ٱلْإِسْلَـٰمِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', 61, 'ومن اظلم ممن افترى على الله الكذب وهو يدعى الى الاسلام والله لا يهدي القوم الظالمين', 552, 28),
  (5171, 8, '61:8', 55, 220, 486, 7, NULL, 'يُرِيدُونَ لِيُطْفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفْوَٰهِهِمْ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوْ كَرِهَ ٱلْكَـٰفِرُونَ', 61, 'يريدون ليطفئوا نور الله بافواههم والله متم نوره ولو كره الكافرون', 552, 28),
  (5172, 9, '61:9', 55, 220, 486, 7, NULL, 'هُوَ ٱلَّذِىٓ أَرْسَلَ رَسُولَهُۥ بِٱلْهُدَىٰ وَدِينِ ٱلْحَقِّ لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوْ كَرِهَ ٱلْمُشْرِكُونَ', 61, 'هو الذي ارسل رسوله بالهدى ودين الحق ليظهره على الدين كله ولو كره المشركون', 552, 28),
  (5173, 10, '61:10', 55, 220, 487, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ هَلْ أَدُلُّكُمْ عَلَىٰ تِجَـٰرَةٍ تُنجِيكُم مِّنْ عَذَابٍ أَلِيمٍ', 61, 'يا ايها الذين امنوا هل ادلكم على تجارة تنجيكم من عذاب اليم', 552, 28),
  (5174, 11, '61:11', 55, 220, 487, 7, NULL, 'تُؤْمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَـٰهِدُونَ فِى سَبِيلِ ٱللَّهِ بِأَمْوَٰلِكُمْ وَأَنفُسِكُمْ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 61, 'تؤمنون بالله ورسوله وتجاهدون في سبيل الله باموالكم وانفسكم ذلكم خير لكم ان كنتم تعلمون', 552, 28),
  (5175, 12, '61:12', 55, 220, 487, 7, NULL, 'يَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَيُدْخِلْكُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ وَمَسَـٰكِنَ طَيِّبَةً فِى جَنَّـٰتِ عَدْنٍ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 61, 'يغفر لكم ذنوبكم ويدخلكم جنات تجري من تحتها الانهار ومساكن طيبة في جنات عدن ذلك الفوز العظيم', 552, 28),
  (5176, 13, '61:13', 55, 220, 487, 7, NULL, 'وَأُخْرَىٰ تُحِبُّونَهَا ۖ نَصْرٌ مِّنَ ٱللَّهِ وَفَتْحٌ قَرِيبٌ ۗ وَبَشِّرِ ٱلْمُؤْمِنِينَ', 61, 'واخرى تحبونها نصر من الله وفتح قريب وبشر المؤمنين', 552, 28),
  (5177, 14, '61:14', 55, 220, 487, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوٓا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِيسَى ٱبْنُ مَرْيَمَ لِلْحَوَارِيِّـۧنَ مَنْ أَنصَارِىٓ إِلَى ٱللَّهِ ۖ قَالَ ٱلْحَوَارِيُّونَ نَحْنُ أَنصَارُ ٱللَّهِ ۖ فَـَٔامَنَت طَّآئِفَةٌ مِّنۢ بَنِىٓ إِسْرَٰٓءِيلَ وَكَفَرَت طَّآئِفَةٌ ۖ فَأَيَّدْنَا ٱلَّذِينَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمْ فَأَصْبَحُوا۟ ظَـٰهِرِينَ', 61, 'يا ايها الذين امنوا كونوا انصار الله كما قال عيسى ابن مريم للحواريين من انصاري الى الله قال الحواريون نحن انصار الله فامنت طائفة من بني اسرائيل وكفرت طائفة فايدنا الذين امنوا على عدوهم فاصبحوا ظاهرين', 552, 28),
  (5178, 1, '62:1', 56, 221, 488, 7, NULL, ' يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ٱلْمَلِكِ ٱلْقُدُّوسِ ٱلْعَزِيزِ ٱلْحَكِيمِ', 62, 'يسبح لله ما في السماوات وما في الارض الملك القدوس العزيز الحكيم', 553, 28),
  (5179, 2, '62:2', 56, 221, 488, 7, NULL, 'هُوَ ٱلَّذِى بَعَثَ فِى ٱلْأُمِّيِّـۧنَ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَـٰتِهِۦ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ ٱلْكِتَـٰبَ وَٱلْحِكْمَةَ وَإِن كَانُوا۟ مِن قَبْلُ لَفِى ضَلَـٰلٍ مُّبِينٍ', 62, 'هو الذي بعث في الاميين رسولا منهم يتلو عليهم اياته ويزكيهم ويعلمهم الكتاب والحكمة وان كانوا من قبل لفي ضلال مبين', 553, 28),
  (5180, 3, '62:3', 56, 221, 488, 7, NULL, 'وَءَاخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا۟ بِهِمْ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ', 62, 'واخرين منهم لما يلحقوا بهم وهو العزيز الحكيم', 553, 28),
  (5181, 4, '62:4', 56, 221, 488, 7, NULL, 'ذَٰلِكَ فَضْلُ ٱللَّهِ يُؤْتِيهِ مَن يَشَآءُ ۚ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ', 62, 'ذلك فضل الله يؤتيه من يشاء والله ذو الفضل العظيم', 553, 28),
  (5182, 5, '62:5', 56, 221, 488, 7, NULL, 'مَثَلُ ٱلَّذِينَ حُمِّلُوا۟ ٱلتَّوْرَىٰةَ ثُمَّ لَمْ يَحْمِلُوهَا كَمَثَلِ ٱلْحِمَارِ يَحْمِلُ أَسْفَارًۢا ۚ بِئْسَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَـٰتِ ٱللَّهِ ۚ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّـٰلِمِينَ', 62, 'مثل الذين حملوا التوراة ثم لم يحملوها كمثل الحمار يحمل اسفارا بئس مثل القوم الذين كذبوا بايات الله والله لا يهدي القوم الظالمين', 553, 28),
  (5183, 6, '62:6', 56, 221, 488, 7, NULL, 'قُلْ يَـٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَـٰدِقِينَ', 62, 'قل يا ايها الذين هادوا ان زعمتم انكم اولياء لله من دون الناس فتمنوا الموت ان كنتم صادقين', 553, 28),
  (5184, 7, '62:7', 56, 221, 488, 7, NULL, 'وَلَا يَتَمَنَّوْنَهُۥٓ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۚ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّـٰلِمِينَ', 62, 'ولا يتمنونه ابدا بما قدمت ايديهم والله عليم بالظالمين', 553, 28),
  (5185, 8, '62:8', 56, 221, 488, 7, NULL, 'قُلْ إِنَّ ٱلْمَوْتَ ٱلَّذِى تَفِرُّونَ مِنْهُ فَإِنَّهُۥ مُلَـٰقِيكُمْ ۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ', 62, 'قل ان الموت الذي تفرون منه فانه ملاقيكم ثم تردون الى عالم الغيب والشهادة فينبئكم بما كنتم تعملون', 553, 28),
  (5186, 9, '62:9', 56, 221, 489, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نُودِىَ لِلصَّلَوٰةِ مِن يَوْمِ ٱلْجُمُعَةِ فَٱسْعَوْا۟ إِلَىٰ ذِكْرِ ٱللَّهِ وَذَرُوا۟ ٱلْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 62, 'يا ايها الذين امنوا اذا نودي للصلاة من يوم الجمعة فاسعوا الى ذكر الله وذروا البيع ذلكم خير لكم ان كنتم تعلمون', 554, 28),
  (5187, 10, '62:10', 56, 221, 489, 7, NULL, 'فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ وَٱذْكُرُوا۟ ٱللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ', 62, 'فاذا قضيت الصلاة فانتشروا في الارض وابتغوا من فضل الله واذكروا الله كثيرا لعلكم تفلحون', 554, 28),
  (5188, 11, '62:11', 56, 221, 489, 7, NULL, 'وَإِذَا رَأَوْا۟ تِجَـٰرَةً أَوْ لَهْوًا ٱنفَضُّوٓا۟ إِلَيْهَا وَتَرَكُوكَ قَآئِمًا ۚ قُلْ مَا عِندَ ٱللَّهِ خَيْرٌ مِّنَ ٱللَّهْوِ وَمِنَ ٱلتِّجَـٰرَةِ ۚ وَٱللَّهُ خَيْرُ ٱلرَّٰزِقِينَ', 62, 'واذا راوا تجارة او لهوا انفضوا اليها وتركوك قائما قل ما عند الله خير من اللهو ومن التجارة والله خير الرازقين', 554, 28),
  (5189, 1, '63:1', 56, 221, 490, 7, NULL, ' إِذَا جَآءَكَ ٱلْمُنَـٰفِقُونَ قَالُوا۟ نَشْهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِ ۗ وَٱللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ يَشْهَدُ إِنَّ ٱلْمُنَـٰفِقِينَ لَكَـٰذِبُونَ', 63, 'اذا جاءك المنافقون قالوا نشهد انك لرسول الله والله يعلم انك لرسوله والله يشهد ان المنافقين لكاذبون', 554, 28),
  (5190, 2, '63:2', 56, 221, 490, 7, NULL, 'ٱتَّخَذُوٓا۟ أَيْمَـٰنَهُمْ جُنَّةً فَصَدُّوا۟ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّهُمْ سَآءَ مَا كَانُوا۟ يَعْمَلُونَ', 63, 'اتخذوا ايمانهم جنة فصدوا عن سبيل الله انهم ساء ما كانوا يعملون', 554, 28),
  (5191, 3, '63:3', 56, 221, 490, 7, NULL, 'ذَٰلِكَ بِأَنَّهُمْ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ', 63, 'ذلك بانهم امنوا ثم كفروا فطبع على قلوبهم فهم لا يفقهون', 554, 28),
  (5192, 4, '63:4', 56, 222, 490, 7, NULL, '۞ وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ ۖ وَإِن يَقُولُوا۟ تَسْمَعْ لِقَوْلِهِمْ ۖ كَأَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ ۖ يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ ۚ هُمُ ٱلْعَدُوُّ فَٱحْذَرْهُمْ ۚ قَـٰتَلَهُمُ ٱللَّهُ ۖ أَنَّىٰ يُؤْفَكُونَ', 63, 'واذا رايتهم تعجبك اجسامهم وان يقولوا تسمع لقولهم كانهم خشب مسندة يحسبون كل صيحة عليهم هم العدو فاحذرهم قاتلهم الله انى يؤفكون', 554, 28),
  (5193, 5, '63:5', 56, 222, 490, 7, NULL, 'وَإِذَا قِيلَ لَهُمْ تَعَالَوْا۟ يَسْتَغْفِرْ لَكُمْ رَسُولُ ٱللَّهِ لَوَّوْا۟ رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ', 63, 'واذا قيل لهم تعالوا يستغفر لكم رسول الله لووا رءوسهم ورايتهم يصدون وهم مستكبرون', 555, 28),
  (5194, 6, '63:6', 56, 222, 490, 7, NULL, 'سَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ ٱللَّهُ لَهُمْ ۚ إِنَّ ٱللَّهَ لَا يَهْدِى ٱلْقَوْمَ ٱلْفَـٰسِقِينَ', 63, 'سواء عليهم استغفرت لهم ام لم تستغفر لهم لن يغفر الله لهم ان الله لا يهدي القوم الفاسقين', 555, 28),
  (5195, 7, '63:7', 56, 222, 490, 7, NULL, 'هُمُ ٱلَّذِينَ يَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنْ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ يَنفَضُّوا۟ ۗ وَلِلَّهِ خَزَآئِنُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَلَـٰكِنَّ ٱلْمُنَـٰفِقِينَ لَا يَفْقَهُونَ', 63, 'هم الذين يقولون لا تنفقوا على من عند رسول الله حتى ينفضوا ولله خزائن السماوات والارض ولكن المنافقين لا يفقهون', 555, 28),
  (5196, 8, '63:8', 56, 222, 490, 7, NULL, 'يَقُولُونَ لَئِن رَّجَعْنَآ إِلَى ٱلْمَدِينَةِ لَيُخْرِجَنَّ ٱلْأَعَزُّ مِنْهَا ٱلْأَذَلَّ ۚ وَلِلَّهِ ٱلْعِزَّةُ وَلِرَسُولِهِۦ وَلِلْمُؤْمِنِينَ وَلَـٰكِنَّ ٱلْمُنَـٰفِقِينَ لَا يَعْلَمُونَ', 63, 'يقولون لئن رجعنا الى المدينة ليخرجن الاعز منها الاذل ولله العزة ولرسوله وللمؤمنين ولكن المنافقين لا يعلمون', 555, 28),
  (5197, 9, '63:9', 56, 222, 491, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُلْهِكُمْ أَمْوَٰلُكُمْ وَلَآ أَوْلَـٰدُكُمْ عَن ذِكْرِ ٱللَّهِ ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْخَـٰسِرُونَ', 63, 'يا ايها الذين امنوا لا تلهكم اموالكم ولا اولادكم عن ذكر الله ومن يفعل ذلك فاولئك هم الخاسرون', 555, 28),
  (5198, 10, '63:10', 56, 222, 491, 7, NULL, 'وَأَنفِقُوا۟ مِن مَّا رَزَقْنَـٰكُم مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ ٱلْمَوْتُ فَيَقُولَ رَبِّ لَوْلَآ أَخَّرْتَنِىٓ إِلَىٰٓ أَجَلٍ قَرِيبٍ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّـٰلِحِينَ', 63, 'وانفقوا من ما رزقناكم من قبل ان ياتي احدكم الموت فيقول رب لولا اخرتني الى اجل قريب فاصدق واكن من الصالحين', 555, 28),
  (5199, 11, '63:11', 56, 222, 491, 7, NULL, 'وَلَن يُؤَخِّرَ ٱللَّهُ نَفْسًا إِذَا جَآءَ أَجَلُهَا ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَ', 63, 'ولن يؤخر الله نفسا اذا جاء اجلها والله خبير بما تعملون', 555, 28),
  (5200, 1, '64:1', 56, 222, 492, 7, NULL, ' يُسَبِّحُ لِلَّهِ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۖ لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ ۖ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 64, 'يسبح لله ما في السماوات وما في الارض له الملك وله الحمد وهو على كل شيء قدير', 556, 28),
  (5201, 2, '64:2', 56, 222, 492, 7, NULL, 'هُوَ ٱلَّذِى خَلَقَكُمْ فَمِنكُمْ كَافِرٌ وَمِنكُم مُّؤْمِنٌ ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ', 64, 'هو الذي خلقكم فمنكم كافر ومنكم مؤمن والله بما تعملون بصير', 556, 28),
  (5202, 3, '64:3', 56, 222, 492, 7, NULL, 'خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ ۖ وَإِلَيْهِ ٱلْمَصِيرُ', 64, 'خلق السماوات والارض بالحق وصوركم فاحسن صوركم واليه المصير', 556, 28),
  (5203, 4, '64:4', 56, 222, 492, 7, NULL, 'يَعْلَمُ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ ۚ وَٱللَّهُ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 64, 'يعلم ما في السماوات والارض ويعلم ما تسرون وما تعلنون والله عليم بذات الصدور', 556, 28),
  (5204, 5, '64:5', 56, 222, 492, 7, NULL, 'أَلَمْ يَأْتِكُمْ نَبَؤُا۟ ٱلَّذِينَ كَفَرُوا۟ مِن قَبْلُ فَذَاقُوا۟ وَبَالَ أَمْرِهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ', 64, 'الم ياتكم نبا الذين كفروا من قبل فذاقوا وبال امرهم ولهم عذاب اليم', 556, 28),
  (5205, 6, '64:6', 56, 222, 492, 7, NULL, 'ذَٰلِكَ بِأَنَّهُۥ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَـٰتِ فَقَالُوٓا۟ أَبَشَرٌ يَهْدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ ۚ وَّٱسْتَغْنَى ٱللَّهُ ۚ وَٱللَّهُ غَنِىٌّ حَمِيدٌ', 64, 'ذلك بانه كانت تاتيهم رسلهم بالبينات فقالوا ابشر يهدوننا فكفروا وتولوا واستغنى الله والله غني حميد', 556, 28),
  (5206, 7, '64:7', 56, 222, 492, 7, NULL, 'زَعَمَ ٱلَّذِينَ كَفَرُوٓا۟ أَن لَّن يُبْعَثُوا۟ ۚ قُلْ بَلَىٰ وَرَبِّى لَتُبْعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلْتُمْ ۚ وَذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ', 64, 'زعم الذين كفروا ان لن يبعثوا قل بلى وربي لتبعثن ثم لتنبؤن بما عملتم وذلك على الله يسير', 556, 28),
  (5207, 8, '64:8', 56, 222, 492, 7, NULL, 'فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِىٓ أَنزَلْنَا ۚ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ', 64, 'فامنوا بالله ورسوله والنور الذي انزلنا والله بما تعملون خبير', 556, 28),
  (5208, 9, '64:9', 56, 222, 492, 7, NULL, 'يَوْمَ يَجْمَعُكُمْ لِيَوْمِ ٱلْجَمْعِ ۖ ذَٰلِكَ يَوْمُ ٱلتَّغَابُنِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَـٰلِحًا يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْعَظِيمُ', 64, 'يوم يجمعكم ليوم الجمع ذلك يوم التغابن ومن يؤمن بالله ويعمل صالحا يكفر عنه سيئاته ويدخله جنات تجري من تحتها الانهار خالدين فيها ابدا ذلك الفوز العظيم', 556, 28),
  (5209, 10, '64:10', 56, 222, 492, 7, NULL, 'وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَـٰتِنَآ أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلنَّارِ خَـٰلِدِينَ فِيهَا ۖ وَبِئْسَ ٱلْمَصِيرُ', 64, 'والذين كفروا وكذبوا باياتنا اولئك اصحاب النار خالدين فيها وبئس المصير', 557, 28),
  (5210, 11, '64:11', 56, 222, 493, 7, NULL, 'مَآ أَصَابَ مِن مُّصِيبَةٍ إِلَّا بِإِذْنِ ٱللَّهِ ۗ وَمَن يُؤْمِنۢ بِٱللَّهِ يَهْدِ قَلْبَهُۥ ۚ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ', 64, 'ما اصاب من مصيبة الا باذن الله ومن يؤمن بالله يهد قلبه والله بكل شيء عليم', 557, 28),
  (5211, 12, '64:12', 56, 222, 493, 7, NULL, 'وَأَطِيعُوا۟ ٱللَّهَ وَأَطِيعُوا۟ ٱلرَّسُولَ ۚ فَإِن تَوَلَّيْتُمْ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلْبَلَـٰغُ ٱلْمُبِينُ', 64, 'واطيعوا الله واطيعوا الرسول فان توليتم فانما على رسولنا البلاغ المبين', 557, 28),
  (5212, 13, '64:13', 56, 222, 493, 7, NULL, 'ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ ۚ وَعَلَى ٱللَّهِ فَلْيَتَوَكَّلِ ٱلْمُؤْمِنُونَ', 64, 'الله لا اله الا هو وعلى الله فليتوكل المؤمنون', 557, 28),
  (5213, 14, '64:14', 56, 222, 493, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ مِنْ أَزْوَٰجِكُمْ وَأَوْلَـٰدِكُمْ عَدُوًّا لَّكُمْ فَٱحْذَرُوهُمْ ۚ وَإِن تَعْفُوا۟ وَتَصْفَحُوا۟ وَتَغْفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ', 64, 'يا ايها الذين امنوا ان من ازواجكم واولادكم عدوا لكم فاحذروهم وان تعفوا وتصفحوا وتغفروا فان الله غفور رحيم', 557, 28),
  (5214, 15, '64:15', 56, 222, 493, 7, NULL, 'إِنَّمَآ أَمْوَٰلُكُمْ وَأَوْلَـٰدُكُمْ فِتْنَةٌ ۚ وَٱللَّهُ عِندَهُۥٓ أَجْرٌ عَظِيمٌ', 64, 'انما اموالكم واولادكم فتنة والله عنده اجر عظيم', 557, 28),
  (5215, 16, '64:16', 56, 222, 493, 7, NULL, 'فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسْتَطَعْتُمْ وَٱسْمَعُوا۟ وَأَطِيعُوا۟ وَأَنفِقُوا۟ خَيْرًا لِّأَنفُسِكُمْ ۗ وَمَن يُوقَ شُحَّ نَفْسِهِۦ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ', 64, 'فاتقوا الله ما استطعتم واسمعوا واطيعوا وانفقوا خيرا لانفسكم ومن يوق شح نفسه فاولئك هم المفلحون', 557, 28),
  (5216, 17, '64:17', 56, 222, 493, 7, NULL, 'إِن تُقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا يُضَـٰعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ ۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ', 64, 'ان تقرضوا الله قرضا حسنا يضاعفه لكم ويغفر لكم والله شكور حليم', 557, 28),
  (5217, 18, '64:18', 56, 222, 493, 7, NULL, 'عَـٰلِمُ ٱلْغَيْبِ وَٱلشَّهَـٰدَةِ ٱلْعَزِيزُ ٱلْحَكِيمُ', 64, 'عالم الغيب والشهادة العزيز الحكيم', 557, 28),
  (5218, 1, '65:1', 56, 223, 494, 7, NULL, ' يَـٰٓأَيُّهَا ٱلنَّبِىُّ إِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا۟ ٱلْعِدَّةَ ۖ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمْ ۖ لَا تُخْرِجُوهُنَّ مِنۢ بُيُوتِهِنَّ وَلَا يَخْرُجْنَ إِلَّآ أَن يَأْتِينَ بِفَـٰحِشَةٍ مُّبَيِّنَةٍ ۚ وَتِلْكَ حُدُودُ ٱللَّهِ ۚ وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدْ ظَلَمَ نَفْسَهُۥ ۚ لَا تَدْرِى لَعَلَّ ٱللَّهَ يُحْدِثُ بَعْدَ ذَٰلِكَ أَمْرًا', 65, 'يا ايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العدة واتقوا الله ربكم لا تخرجوهن من بيوتهن ولا يخرجن الا ان ياتين بفاحشة مبينة وتلك حدود الله ومن يتعد حدود الله فقد ظلم نفسه لا تدري لعل الله يحدث بعد ذلك امرا', 558, 28),
  (5219, 2, '65:2', 56, 223, 494, 7, NULL, 'فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا۟ ذَوَىْ عَدْلٍ مِّنكُمْ وَأَقِيمُوا۟ ٱلشَّهَـٰدَةَ لِلَّهِ ۚ ذَٰلِكُمْ يُوعَظُ بِهِۦ مَن كَانَ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًا', 65, 'فاذا بلغن اجلهن فامسكوهن بمعروف او فارقوهن بمعروف واشهدوا ذوي عدل منكم واقيموا الشهادة لله ذلكم يوعظ به من كان يؤمن بالله واليوم الاخر ومن يتق الله يجعل له مخرجا', 558, 28),
  (5220, 3, '65:3', 56, 223, 494, 7, NULL, 'وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ ۚ وَمَن يَتَوَكَّلْ عَلَى ٱللَّهِ فَهُوَ حَسْبُهُۥٓ ۚ إِنَّ ٱللَّهَ بَـٰلِغُ أَمْرِهِۦ ۚ قَدْ جَعَلَ ٱللَّهُ لِكُلِّ شَىْءٍ قَدْرًا', 65, 'ويرزقه من حيث لا يحتسب ومن يتوكل على الله فهو حسبه ان الله بالغ امره قد جعل الله لكل شيء قدرا', 558, 28),
  (5221, 4, '65:4', 56, 223, 494, 7, NULL, 'وَٱلَّـٰٓـِٔى يَئِسْنَ مِنَ ٱلْمَحِيضِ مِن نِّسَآئِكُمْ إِنِ ٱرْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَـٰثَةُ أَشْهُرٍ وَٱلَّـٰٓـِٔى لَمْ يَحِضْنَ ۚ وَأُو۟لَـٰتُ ٱلْأَحْمَالِ أَجَلُهُنَّ أَن يَضَعْنَ حَمْلَهُنَّ ۚ وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مِنْ أَمْرِهِۦ يُسْرًا', 65, 'واللائي يئسن من المحيض من نسائكم ان ارتبتم فعدتهن ثلاثة اشهر واللائي لم يحضن واولات الاحمال اجلهن ان يضعن حملهن ومن يتق الله يجعل له من امره يسرا', 558, 28),
  (5222, 5, '65:5', 56, 223, 494, 7, NULL, 'ذَٰلِكَ أَمْرُ ٱللَّهِ أَنزَلَهُۥٓ إِلَيْكُمْ ۚ وَمَن يَتَّقِ ٱللَّهَ يُكَفِّرْ عَنْهُ سَيِّـَٔاتِهِۦ وَيُعْظِمْ لَهُۥٓ أَجْرًا', 65, 'ذلك امر الله انزله اليكم ومن يتق الله يكفر عنه سيئاته ويعظم له اجرا', 558, 28),
  (5223, 6, '65:6', 56, 223, 494, 7, NULL, 'أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنتُم مِّن وُجْدِكُمْ وَلَا تُضَآرُّوهُنَّ لِتُضَيِّقُوا۟ عَلَيْهِنَّ ۚ وَإِن كُنَّ أُو۟لَـٰتِ حَمْلٍ فَأَنفِقُوا۟ عَلَيْهِنَّ حَتَّىٰ يَضَعْنَ حَمْلَهُنَّ ۚ فَإِنْ أَرْضَعْنَ لَكُمْ فَـَٔاتُوهُنَّ أُجُورَهُنَّ ۖ وَأْتَمِرُوا۟ بَيْنَكُم بِمَعْرُوفٍ ۖ وَإِن تَعَاسَرْتُمْ فَسَتُرْضِعُ لَهُۥٓ أُخْرَىٰ', 65, 'اسكنوهن من حيث سكنتم من وجدكم ولا تضاروهن لتضيقوا عليهن وان كن اولات حمل فانفقوا عليهن حتى يضعن حملهن فان ارضعن لكم فاتوهن اجورهن واتمروا بينكم بمعروف وان تعاسرتم فسترضع له اخرى', 559, 28),
  (5224, 7, '65:7', 56, 223, 494, 7, NULL, 'لِيُنفِقْ ذُو سَعَةٍ مِّن سَعَتِهِۦ ۖ وَمَن قُدِرَ عَلَيْهِ رِزْقُهُۥ فَلْيُنفِقْ مِمَّآ ءَاتَىٰهُ ٱللَّهُ ۚ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا مَآ ءَاتَىٰهَا ۚ سَيَجْعَلُ ٱللَّهُ بَعْدَ عُسْرٍ يُسْرًا', 65, 'لينفق ذو سعة من سعته ومن قدر عليه رزقه فلينفق مما اتاه الله لا يكلف الله نفسا الا ما اتاها سيجعل الله بعد عسر يسرا', 559, 28),
  (5225, 8, '65:8', 56, 223, 495, 7, NULL, 'وَكَأَيِّن مِّن قَرْيَةٍ عَتَتْ عَنْ أَمْرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبْنَـٰهَا حِسَابًا شَدِيدًا وَعَذَّبْنَـٰهَا عَذَابًا نُّكْرًا', 65, 'وكاين من قرية عتت عن امر ربها ورسله فحاسبناها حسابا شديدا وعذبناها عذابا نكرا', 559, 28),
  (5226, 9, '65:9', 56, 223, 495, 7, NULL, 'فَذَاقَتْ وَبَالَ أَمْرِهَا وَكَانَ عَـٰقِبَةُ أَمْرِهَا خُسْرًا', 65, 'فذاقت وبال امرها وكان عاقبة امرها خسرا', 559, 28),
  (5227, 10, '65:10', 56, 223, 495, 7, NULL, 'أَعَدَّ ٱللَّهُ لَهُمْ عَذَابًا شَدِيدًا ۖ فَٱتَّقُوا۟ ٱللَّهَ يَـٰٓأُو۟لِى ٱلْأَلْبَـٰبِ ٱلَّذِينَ ءَامَنُوا۟ ۚ قَدْ أَنزَلَ ٱللَّهُ إِلَيْكُمْ ذِكْرًا', 65, 'اعد الله لهم عذابا شديدا فاتقوا الله يا اولي الالباب الذين امنوا قد انزل الله اليكم ذكرا', 559, 28),
  (5228, 11, '65:11', 56, 223, 495, 7, NULL, 'رَّسُولًا يَتْلُوا۟ عَلَيْكُمْ ءَايَـٰتِ ٱللَّهِ مُبَيِّنَـٰتٍ لِّيُخْرِجَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ ۚ وَمَن يُؤْمِنۢ بِٱللَّهِ وَيَعْمَلْ صَـٰلِحًا يُدْخِلْهُ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ قَدْ أَحْسَنَ ٱللَّهُ لَهُۥ رِزْقًا', 65, 'رسولا يتلو عليكم ايات الله مبينات ليخرج الذين امنوا وعملوا الصالحات من الظلمات الى النور ومن يؤمن بالله ويعمل صالحا يدخله جنات تجري من تحتها الانهار خالدين فيها ابدا قد احسن الله له رزقا', 559, 28),
  (5229, 12, '65:12', 56, 223, 495, 7, NULL, 'ٱللَّهُ ٱلَّذِى خَلَقَ سَبْعَ سَمَـٰوَٰتٍ وَمِنَ ٱلْأَرْضِ مِثْلَهُنَّ يَتَنَزَّلُ ٱلْأَمْرُ بَيْنَهُنَّ لِتَعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ وَأَنَّ ٱللَّهَ قَدْ أَحَاطَ بِكُلِّ شَىْءٍ عِلْمًۢا', 65, 'الله الذي خلق سبع سماوات ومن الارض مثلهن يتنزل الامر بينهن لتعلموا ان الله على كل شيء قدير وان الله قد احاط بكل شيء علما', 559, 28),
  (5230, 1, '66:1', 56, 224, 496, 7, NULL, ' يَـٰٓأَيُّهَا ٱلنَّبِىُّ لِمَ تُحَرِّمُ مَآ أَحَلَّ ٱللَّهُ لَكَ ۖ تَبْتَغِى مَرْضَاتَ أَزْوَٰجِكَ ۚ وَٱللَّهُ غَفُورٌ رَّحِيمٌ', 66, 'يا ايها النبي لم تحرم ما احل الله لك تبتغي مرضات ازواجك والله غفور رحيم', 560, 28),
  (5231, 2, '66:2', 56, 224, 496, 7, NULL, 'قَدْ فَرَضَ ٱللَّهُ لَكُمْ تَحِلَّةَ أَيْمَـٰنِكُمْ ۚ وَٱللَّهُ مَوْلَىٰكُمْ ۖ وَهُوَ ٱلْعَلِيمُ ٱلْحَكِيمُ', 66, 'قد فرض الله لكم تحلة ايمانكم والله مولاكم وهو العليم الحكيم', 560, 28),
  (5232, 3, '66:3', 56, 224, 496, 7, NULL, 'وَإِذْ أَسَرَّ ٱلنَّبِىُّ إِلَىٰ بَعْضِ أَزْوَٰجِهِۦ حَدِيثًا فَلَمَّا نَبَّأَتْ بِهِۦ وَأَظْهَرَهُ ٱللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُۥ وَأَعْرَضَ عَنۢ بَعْضٍ ۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتْ مَنْ أَنۢبَأَكَ هَـٰذَا ۖ قَالَ نَبَّأَنِىَ ٱلْعَلِيمُ ٱلْخَبِيرُ', 66, 'واذ اسر النبي الى بعض ازواجه حديثا فلما نبات به واظهره الله عليه عرف بعضه واعرض عن بعض فلما نباها به قالت من انباك هذا قال نباني العليم الخبير', 560, 28),
  (5233, 4, '66:4', 56, 224, 496, 7, NULL, 'إِن تَتُوبَآ إِلَى ٱللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا ۖ وَإِن تَظَـٰهَرَا عَلَيْهِ فَإِنَّ ٱللَّهَ هُوَ مَوْلَىٰهُ وَجِبْرِيلُ وَصَـٰلِحُ ٱلْمُؤْمِنِينَ ۖ وَٱلْمَلَـٰٓئِكَةُ بَعْدَ ذَٰلِكَ ظَهِيرٌ', 66, 'ان تتوبا الى الله فقد صغت قلوبكما وان تظاهرا عليه فان الله هو مولاه وجبريل وصالح المؤمنين والملائكة بعد ذلك ظهير', 560, 28),
  (5234, 5, '66:5', 56, 224, 496, 7, NULL, 'عَسَىٰ رَبُّهُۥٓ إِن طَلَّقَكُنَّ أَن يُبْدِلَهُۥٓ أَزْوَٰجًا خَيْرًا مِّنكُنَّ مُسْلِمَـٰتٍ مُّؤْمِنَـٰتٍ قَـٰنِتَـٰتٍ تَـٰٓئِبَـٰتٍ عَـٰبِدَٰتٍ سَـٰٓئِحَـٰتٍ ثَيِّبَـٰتٍ وَأَبْكَارًا', 66, 'عسى ربه ان طلقكن ان يبدله ازواجا خيرا منكن مسلمات مؤمنات قانتات تائبات عابدات سائحات ثيبات وابكارا', 560, 28),
  (5235, 6, '66:6', 56, 224, 496, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ عَلَيْهَا مَلَـٰٓئِكَةٌ غِلَاظٌ شِدَادٌ لَّا يَعْصُونَ ٱللَّهَ مَآ أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ', 66, 'يا ايها الذين امنوا قوا انفسكم واهليكم نارا وقودها الناس والحجارة عليها ملائكة غلاظ شداد لا يعصون الله ما امرهم ويفعلون ما يؤمرون', 560, 28),
  (5236, 7, '66:7', 56, 224, 496, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ كَفَرُوا۟ لَا تَعْتَذِرُوا۟ ٱلْيَوْمَ ۖ إِنَّمَا تُجْزَوْنَ مَا كُنتُمْ تَعْمَلُونَ', 66, 'يا ايها الذين كفروا لا تعتذروا اليوم انما تجزون ما كنتم تعملون', 560, 28),
  (5237, 8, '66:8', 56, 224, 497, 7, NULL, 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ تُوبُوٓا۟ إِلَى ٱللَّهِ تَوْبَةً نَّصُوحًا عَسَىٰ رَبُّكُمْ أَن يُكَفِّرَ عَنكُمْ سَيِّـَٔاتِكُمْ وَيُدْخِلَكُمْ جَنَّـٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ يَوْمَ لَا يُخْزِى ٱللَّهُ ٱلنَّبِىَّ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ ۖ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَـٰنِهِمْ يَقُولُونَ رَبَّنَآ أَتْمِمْ لَنَا نُورَنَا وَٱغْفِرْ لَنَآ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 66, 'يا ايها الذين امنوا توبوا الى الله توبة نصوحا عسى ربكم ان يكفر عنكم سيئاتكم ويدخلكم جنات تجري من تحتها الانهار يوم لا يخزي الله النبي والذين امنوا معه نورهم يسعى بين ايديهم وبايمانهم يقولون ربنا اتمم لنا نورنا واغفر لنا انك على كل شيء قدير', 561, 28),
  (5238, 9, '66:9', 56, 224, 497, 7, NULL, 'يَـٰٓأَيُّهَا ٱلنَّبِىُّ جَـٰهِدِ ٱلْكُفَّارَ وَٱلْمُنَـٰفِقِينَ وَٱغْلُظْ عَلَيْهِمْ ۚ وَمَأْوَىٰهُمْ جَهَنَّمُ ۖ وَبِئْسَ ٱلْمَصِيرُ', 66, 'يا ايها النبي جاهد الكفار والمنافقين واغلظ عليهم وماواهم جهنم وبئس المصير', 561, 28),
  (5239, 10, '66:10', 56, 224, 497, 7, NULL, 'ضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ كَفَرُوا۟ ٱمْرَأَتَ نُوحٍ وَٱمْرَأَتَ لُوطٍ ۖ كَانَتَا تَحْتَ عَبْدَيْنِ مِنْ عِبَادِنَا صَـٰلِحَيْنِ فَخَانَتَاهُمَا فَلَمْ يُغْنِيَا عَنْهُمَا مِنَ ٱللَّهِ شَيْـًٔا وَقِيلَ ٱدْخُلَا ٱلنَّارَ مَعَ ٱلدَّٰخِلِينَ', 66, 'ضرب الله مثلا للذين كفروا امرات نوح وامرات لوط كانتا تحت عبدين من عبادنا صالحين فخانتاهما فلم يغنيا عنهما من الله شيئا وقيل ادخلا النار مع الداخلين', 561, 28),
  (5240, 11, '66:11', 56, 224, 497, 7, NULL, 'وَضَرَبَ ٱللَّهُ مَثَلًا لِّلَّذِينَ ءَامَنُوا۟ ٱمْرَأَتَ فِرْعَوْنَ إِذْ قَالَتْ رَبِّ ٱبْنِ لِى عِندَكَ بَيْتًا فِى ٱلْجَنَّةِ وَنَجِّنِى مِن فِرْعَوْنَ وَعَمَلِهِۦ وَنَجِّنِى مِنَ ٱلْقَوْمِ ٱلظَّـٰلِمِينَ', 66, 'وضرب الله مثلا للذين امنوا امرات فرعون اذ قالت رب ابن لي عندك بيتا في الجنة ونجني من فرعون وعمله ونجني من القوم الظالمين', 561, 28),
  (5241, 12, '66:12', 56, 224, 497, 7, NULL, 'وَمَرْيَمَ ٱبْنَتَ عِمْرَٰنَ ٱلَّتِىٓ أَحْصَنَتْ فَرْجَهَا فَنَفَخْنَا فِيهِ مِن رُّوحِنَا وَصَدَّقَتْ بِكَلِمَـٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتْ مِنَ ٱلْقَـٰنِتِينَ', 66, 'ومريم ابنت عمران التي احصنت فرجها فنفخنا فيه من روحنا وصدقت بكلمات ربها وكتبه وكانت من القانتين', 561, 28),
  (5242, 1, '67:1', 57, 225, 498, 7, NULL, ' تَبَـٰرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ', 67, 'تبارك الذي بيده الملك وهو على كل شيء قدير', 562, 29),
  (5243, 2, '67:2', 57, 225, 498, 7, NULL, 'ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ', 67, 'الذي خلق الموت والحياة ليبلوكم ايكم احسن عملا وهو العزيز الغفور', 562, 29),
  (5244, 3, '67:3', 57, 225, 498, 7, NULL, 'ٱلَّذِى خَلَقَ سَبْعَ سَمَـٰوَٰتٍ طِبَاقًا ۖ مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَـٰنِ مِن تَفَـٰوُتٍ ۖ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ', 67, 'الذي خلق سبع سماوات طباقا ما ترى في خلق الرحمن من تفاوت فارجع البصر هل ترى من فطور', 562, 29),
  (5245, 4, '67:4', 57, 225, 498, 7, NULL, 'ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ', 67, 'ثم ارجع البصر كرتين ينقلب اليك البصر خاسئا وهو حسير', 562, 29),
  (5246, 5, '67:5', 57, 225, 498, 7, NULL, 'وَلَقَدْ زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَـٰبِيحَ وَجَعَلْنَـٰهَا رُجُومًا لِّلشَّيَـٰطِينِ ۖ وَأَعْتَدْنَا لَهُمْ عَذَابَ ٱلسَّعِيرِ', 67, 'ولقد زينا السماء الدنيا بمصابيح وجعلناها رجوما للشياطين واعتدنا لهم عذاب السعير', 562, 29),
  (5247, 6, '67:6', 57, 225, 498, 7, NULL, 'وَلِلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ عَذَابُ جَهَنَّمَ ۖ وَبِئْسَ ٱلْمَصِيرُ', 67, 'وللذين كفروا بربهم عذاب جهنم وبئس المصير', 562, 29),
  (5248, 7, '67:7', 57, 225, 498, 7, NULL, 'إِذَآ أُلْقُوا۟ فِيهَا سَمِعُوا۟ لَهَا شَهِيقًا وَهِىَ تَفُورُ', 67, 'اذا القوا فيها سمعوا لها شهيقا وهي تفور', 562, 29),
  (5249, 8, '67:8', 57, 225, 498, 7, NULL, 'تَكَادُ تَمَيَّزُ مِنَ ٱلْغَيْظِ ۖ كُلَّمَآ أُلْقِىَ فِيهَا فَوْجٌ سَأَلَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ نَذِيرٌ', 67, 'تكاد تميز من الغيظ كلما القي فيها فوج سالهم خزنتها الم ياتكم نذير', 562, 29),
  (5250, 9, '67:9', 57, 225, 498, 7, NULL, 'قَالُوا۟ بَلَىٰ قَدْ جَآءَنَا نَذِيرٌ فَكَذَّبْنَا وَقُلْنَا مَا نَزَّلَ ٱللَّهُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا فِى ضَلَـٰلٍ كَبِيرٍ', 67, 'قالوا بلى قد جاءنا نذير فكذبنا وقلنا ما نزل الله من شيء ان انتم الا في ضلال كبير', 562, 29),
  (5251, 10, '67:10', 57, 225, 498, 7, NULL, 'وَقَالُوا۟ لَوْ كُنَّا نَسْمَعُ أَوْ نَعْقِلُ مَا كُنَّا فِىٓ أَصْحَـٰبِ ٱلسَّعِيرِ', 67, 'وقالوا لو كنا نسمع او نعقل ما كنا في اصحاب السعير', 562, 29),
  (5252, 11, '67:11', 57, 225, 498, 7, NULL, 'فَٱعْتَرَفُوا۟ بِذَنۢبِهِمْ فَسُحْقًا لِّأَصْحَـٰبِ ٱلسَّعِيرِ', 67, 'فاعترفوا بذنبهم فسحقا لاصحاب السعير', 562, 29),
  (5253, 12, '67:12', 57, 225, 498, 7, NULL, 'إِنَّ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ', 67, 'ان الذين يخشون ربهم بالغيب لهم مغفرة واجر كبير', 562, 29),
  (5254, 13, '67:13', 57, 225, 498, 7, NULL, 'وَأَسِرُّوا۟ قَوْلَكُمْ أَوِ ٱجْهَرُوا۟ بِهِۦٓ ۖ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ', 67, 'واسروا قولكم او اجهروا به انه عليم بذات الصدور', 563, 29),
  (5255, 14, '67:14', 57, 225, 498, 7, NULL, 'أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 67, 'الا يعلم من خلق وهو اللطيف الخبير', 563, 29),
  (5256, 15, '67:15', 57, 225, 499, 7, NULL, 'هُوَ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ ذَلُولًا فَٱمْشُوا۟ فِى مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزْقِهِۦ ۖ وَإِلَيْهِ ٱلنُّشُورُ', 67, 'هو الذي جعل لكم الارض ذلولا فامشوا في مناكبها وكلوا من رزقه واليه النشور', 563, 29),
  (5257, 16, '67:16', 57, 225, 499, 7, NULL, 'ءَأَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يَخْسِفَ بِكُمُ ٱلْأَرْضَ فَإِذَا هِىَ تَمُورُ', 67, 'اامنتم من في السماء ان يخسف بكم الارض فاذا هي تمور', 563, 29),
  (5258, 17, '67:17', 57, 225, 499, 7, NULL, 'أَمْ أَمِنتُم مَّن فِى ٱلسَّمَآءِ أَن يُرْسِلَ عَلَيْكُمْ حَاصِبًا ۖ فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ', 67, 'ام امنتم من في السماء ان يرسل عليكم حاصبا فستعلمون كيف نذير', 563, 29),
  (5259, 18, '67:18', 57, 225, 499, 7, NULL, 'وَلَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَكَيْفَ كَانَ نَكِيرِ', 67, 'ولقد كذب الذين من قبلهم فكيف كان نكير', 563, 29),
  (5260, 19, '67:19', 57, 225, 499, 7, NULL, 'أَوَلَمْ يَرَوْا۟ إِلَى ٱلطَّيْرِ فَوْقَهُمْ صَـٰٓفَّـٰتٍ وَيَقْبِضْنَ ۚ مَا يُمْسِكُهُنَّ إِلَّا ٱلرَّحْمَـٰنُ ۚ إِنَّهُۥ بِكُلِّ شَىْءٍۭ بَصِيرٌ', 67, 'اولم يروا الى الطير فوقهم صافات ويقبضن ما يمسكهن الا الرحمن انه بكل شيء بصير', 563, 29),
  (5261, 20, '67:20', 57, 225, 499, 7, NULL, 'أَمَّنْ هَـٰذَا ٱلَّذِى هُوَ جُندٌ لَّكُمْ يَنصُرُكُم مِّن دُونِ ٱلرَّحْمَـٰنِ ۚ إِنِ ٱلْكَـٰفِرُونَ إِلَّا فِى غُرُورٍ', 67, 'امن هذا الذي هو جند لكم ينصركم من دون الرحمن ان الكافرون الا في غرور', 563, 29),
  (5262, 21, '67:21', 57, 225, 499, 7, NULL, 'أَمَّنْ هَـٰذَا ٱلَّذِى يَرْزُقُكُمْ إِنْ أَمْسَكَ رِزْقَهُۥ ۚ بَل لَّجُّوا۟ فِى عُتُوٍّ وَنُفُورٍ', 67, 'امن هذا الذي يرزقكم ان امسك رزقه بل لجوا في عتو ونفور', 563, 29),
  (5263, 22, '67:22', 57, 225, 499, 7, NULL, 'أَفَمَن يَمْشِى مُكِبًّا عَلَىٰ وَجْهِهِۦٓ أَهْدَىٰٓ أَمَّن يَمْشِى سَوِيًّا عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ', 67, 'افمن يمشي مكبا على وجهه اهدى امن يمشي سويا على صراط مستقيم', 563, 29),
  (5264, 23, '67:23', 57, 225, 499, 7, NULL, 'قُلْ هُوَ ٱلَّذِىٓ أَنشَأَكُمْ وَجَعَلَ لَكُمُ ٱلسَّمْعَ وَٱلْأَبْصَـٰرَ وَٱلْأَفْـِٔدَةَ ۖ قَلِيلًا مَّا تَشْكُرُونَ', 67, 'قل هو الذي انشاكم وجعل لكم السمع والابصار والافئدة قليلا ما تشكرون', 563, 29),
  (5265, 24, '67:24', 57, 225, 499, 7, NULL, 'قُلْ هُوَ ٱلَّذِى ذَرَأَكُمْ فِى ٱلْأَرْضِ وَإِلَيْهِ تُحْشَرُونَ', 67, 'قل هو الذي ذراكم في الارض واليه تحشرون', 563, 29),
  (5266, 25, '67:25', 57, 225, 499, 7, NULL, 'وَيَقُولُونَ مَتَىٰ هَـٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَـٰدِقِينَ', 67, 'ويقولون متى هذا الوعد ان كنتم صادقين', 563, 29),
  (5267, 26, '67:26', 57, 225, 499, 7, NULL, 'قُلْ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَإِنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ', 67, 'قل انما العلم عند الله وانما انا نذير مبين', 563, 29),
  (5268, 27, '67:27', 57, 225, 499, 7, NULL, 'فَلَمَّا رَأَوْهُ زُلْفَةً سِيٓـَٔتْ وُجُوهُ ٱلَّذِينَ كَفَرُوا۟ وَقِيلَ هَـٰذَا ٱلَّذِى كُنتُم بِهِۦ تَدَّعُونَ', 67, 'فلما راوه زلفة سيئت وجوه الذين كفروا وقيل هذا الذي كنتم به تدعون', 564, 29),
  (5269, 28, '67:28', 57, 225, 499, 7, NULL, 'قُلْ أَرَءَيْتُمْ إِنْ أَهْلَكَنِىَ ٱللَّهُ وَمَن مَّعِىَ أَوْ رَحِمَنَا فَمَن يُجِيرُ ٱلْكَـٰفِرِينَ مِنْ عَذَابٍ أَلِيمٍ', 67, 'قل ارايتم ان اهلكني الله ومن معي او رحمنا فمن يجير الكافرين من عذاب اليم', 564, 29),
  (5270, 29, '67:29', 57, 225, 499, 7, NULL, 'قُلْ هُوَ ٱلرَّحْمَـٰنُ ءَامَنَّا بِهِۦ وَعَلَيْهِ تَوَكَّلْنَا ۖ فَسَتَعْلَمُونَ مَنْ هُوَ فِى ضَلَـٰلٍ مُّبِينٍ', 67, 'قل هو الرحمن امنا به وعليه توكلنا فستعلمون من هو في ضلال مبين', 564, 29),
  (5271, 30, '67:30', 57, 225, 499, 7, NULL, 'قُلْ أَرَءَيْتُمْ إِنْ أَصْبَحَ مَآؤُكُمْ غَوْرًا فَمَن يَأْتِيكُم بِمَآءٍ مَّعِينٍۭ', 67, 'قل ارايتم ان اصبح ماؤكم غورا فمن ياتيكم بماء معين', 564, 29),
  (5272, 1, '68:1', 57, 226, 500, 7, NULL, ' نٓ ۚ وَٱلْقَلَمِ وَمَا يَسْطُرُونَ', 68, 'ن والقلم وما يسطرون', 564, 29),
  (5273, 2, '68:2', 57, 226, 500, 7, NULL, 'مَآ أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍ', 68, 'ما انت بنعمة ربك بمجنون', 564, 29),
  (5274, 3, '68:3', 57, 226, 500, 7, NULL, 'وَإِنَّ لَكَ لَأَجْرًا غَيْرَ مَمْنُونٍ', 68, 'وان لك لاجرا غير ممنون', 564, 29),
  (5275, 4, '68:4', 57, 226, 500, 7, NULL, 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ', 68, 'وانك لعلى خلق عظيم', 564, 29),
  (5276, 5, '68:5', 57, 226, 500, 7, NULL, 'فَسَتُبْصِرُ وَيُبْصِرُونَ', 68, 'فستبصر ويبصرون', 564, 29),
  (5277, 6, '68:6', 57, 226, 500, 7, NULL, 'بِأَييِّكُمُ ٱلْمَفْتُونُ', 68, 'باييكم المفتون', 564, 29),
  (5278, 7, '68:7', 57, 226, 500, 7, NULL, 'إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ', 68, 'ان ربك هو اعلم بمن ضل عن سبيله وهو اعلم بالمهتدين', 564, 29),
  (5279, 8, '68:8', 57, 226, 500, 7, NULL, 'فَلَا تُطِعِ ٱلْمُكَذِّبِينَ', 68, 'فلا تطع المكذبين', 564, 29),
  (5280, 9, '68:9', 57, 226, 500, 7, NULL, 'وَدُّوا۟ لَوْ تُدْهِنُ فَيُدْهِنُونَ', 68, 'ودوا لو تدهن فيدهنون', 564, 29),
  (5281, 10, '68:10', 57, 226, 500, 7, NULL, 'وَلَا تُطِعْ كُلَّ حَلَّافٍ مَّهِينٍ', 68, 'ولا تطع كل حلاف مهين', 564, 29),
  (5282, 11, '68:11', 57, 226, 500, 7, NULL, 'هَمَّازٍ مَّشَّآءٍۭ بِنَمِيمٍ', 68, 'هماز مشاء بنميم', 564, 29),
  (5283, 12, '68:12', 57, 226, 500, 7, NULL, 'مَّنَّاعٍ لِّلْخَيْرِ مُعْتَدٍ أَثِيمٍ', 68, 'مناع للخير معتد اثيم', 564, 29),
  (5284, 13, '68:13', 57, 226, 500, 7, NULL, 'عُتُلٍّۭ بَعْدَ ذَٰلِكَ زَنِيمٍ', 68, 'عتل بعد ذلك زنيم', 564, 29),
  (5285, 14, '68:14', 57, 226, 500, 7, NULL, 'أَن كَانَ ذَا مَالٍ وَبَنِينَ', 68, 'ان كان ذا مال وبنين', 564, 29),
  (5286, 15, '68:15', 57, 226, 500, 7, NULL, 'إِذَا تُتْلَىٰ عَلَيْهِ ءَايَـٰتُنَا قَالَ أَسَـٰطِيرُ ٱلْأَوَّلِينَ', 68, 'اذا تتلى عليه اياتنا قال اساطير الاولين', 564, 29),
  (5287, 16, '68:16', 57, 226, 500, 7, NULL, 'سَنَسِمُهُۥ عَلَى ٱلْخُرْطُومِ', 68, 'سنسمه على الخرطوم', 565, 29),
  (5288, 17, '68:17', 57, 226, 500, 7, NULL, 'إِنَّا بَلَوْنَـٰهُمْ كَمَا بَلَوْنَآ أَصْحَـٰبَ ٱلْجَنَّةِ إِذْ أَقْسَمُوا۟ لَيَصْرِمُنَّهَا مُصْبِحِينَ', 68, 'انا بلوناهم كما بلونا اصحاب الجنة اذ اقسموا ليصرمنها مصبحين', 565, 29),
  (5289, 18, '68:18', 57, 226, 500, 7, NULL, 'وَلَا يَسْتَثْنُونَ', 68, 'ولا يستثنون', 565, 29),
  (5290, 19, '68:19', 57, 226, 500, 7, NULL, 'فَطَافَ عَلَيْهَا طَآئِفٌ مِّن رَّبِّكَ وَهُمْ نَآئِمُونَ', 68, 'فطاف عليها طائف من ربك وهم نائمون', 565, 29),
  (5291, 20, '68:20', 57, 226, 500, 7, NULL, 'فَأَصْبَحَتْ كَٱلصَّرِيمِ', 68, 'فاصبحت كالصريم', 565, 29),
  (5292, 21, '68:21', 57, 226, 500, 7, NULL, 'فَتَنَادَوْا۟ مُصْبِحِينَ', 68, 'فتنادوا مصبحين', 565, 29),
  (5293, 22, '68:22', 57, 226, 500, 7, NULL, 'أَنِ ٱغْدُوا۟ عَلَىٰ حَرْثِكُمْ إِن كُنتُمْ صَـٰرِمِينَ', 68, 'ان اغدوا على حرثكم ان كنتم صارمين', 565, 29),
  (5294, 23, '68:23', 57, 226, 500, 7, NULL, 'فَٱنطَلَقُوا۟ وَهُمْ يَتَخَـٰفَتُونَ', 68, 'فانطلقوا وهم يتخافتون', 565, 29),
  (5295, 24, '68:24', 57, 226, 500, 7, NULL, 'أَن لَّا يَدْخُلَنَّهَا ٱلْيَوْمَ عَلَيْكُم مِّسْكِينٌ', 68, 'ان لا يدخلنها اليوم عليكم مسكين', 565, 29),
  (5296, 25, '68:25', 57, 226, 500, 7, NULL, 'وَغَدَوْا۟ عَلَىٰ حَرْدٍ قَـٰدِرِينَ', 68, 'وغدوا على حرد قادرين', 565, 29),
  (5297, 26, '68:26', 57, 226, 500, 7, NULL, 'فَلَمَّا رَأَوْهَا قَالُوٓا۟ إِنَّا لَضَآلُّونَ', 68, 'فلما راوها قالوا انا لضالون', 565, 29),
  (5298, 27, '68:27', 57, 226, 500, 7, NULL, 'بَلْ نَحْنُ مَحْرُومُونَ', 68, 'بل نحن محرومون', 565, 29),
  (5299, 28, '68:28', 57, 226, 500, 7, NULL, 'قَالَ أَوْسَطُهُمْ أَلَمْ أَقُل لَّكُمْ لَوْلَا تُسَبِّحُونَ', 68, 'قال اوسطهم الم اقل لكم لولا تسبحون', 565, 29),
  (5300, 29, '68:29', 57, 226, 500, 7, NULL, 'قَالُوا۟ سُبْحَـٰنَ رَبِّنَآ إِنَّا كُنَّا ظَـٰلِمِينَ', 68, 'قالوا سبحان ربنا انا كنا ظالمين', 565, 29),
  (5301, 30, '68:30', 57, 226, 500, 7, NULL, 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَلَـٰوَمُونَ', 68, 'فاقبل بعضهم على بعض يتلاومون', 565, 29),
  (5302, 31, '68:31', 57, 226, 500, 7, NULL, 'قَالُوا۟ يَـٰوَيْلَنَآ إِنَّا كُنَّا طَـٰغِينَ', 68, 'قالوا يا ويلنا انا كنا طاغين', 565, 29),
  (5303, 32, '68:32', 57, 226, 500, 7, NULL, 'عَسَىٰ رَبُّنَآ أَن يُبْدِلَنَا خَيْرًا مِّنْهَآ إِنَّآ إِلَىٰ رَبِّنَا رَٰغِبُونَ', 68, 'عسى ربنا ان يبدلنا خيرا منها انا الى ربنا راغبون', 565, 29),
  (5304, 33, '68:33', 57, 226, 500, 7, NULL, 'كَذَٰلِكَ ٱلْعَذَابُ ۖ وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَكْبَرُ ۚ لَوْ كَانُوا۟ يَعْلَمُونَ', 68, 'كذلك العذاب ولعذاب الاخرة اكبر لو كانوا يعلمون', 565, 29),
  (5305, 34, '68:34', 57, 226, 501, 7, NULL, 'إِنَّ لِلْمُتَّقِينَ عِندَ رَبِّهِمْ جَنَّـٰتِ ٱلنَّعِيمِ', 68, 'ان للمتقين عند ربهم جنات النعيم', 565, 29),
  (5306, 35, '68:35', 57, 226, 501, 7, NULL, 'أَفَنَجْعَلُ ٱلْمُسْلِمِينَ كَٱلْمُجْرِمِينَ', 68, 'افنجعل المسلمين كالمجرمين', 565, 29),
  (5307, 36, '68:36', 57, 226, 501, 7, NULL, 'مَا لَكُمْ كَيْفَ تَحْكُمُونَ', 68, 'ما لكم كيف تحكمون', 565, 29),
  (5308, 37, '68:37', 57, 226, 501, 7, NULL, 'أَمْ لَكُمْ كِتَـٰبٌ فِيهِ تَدْرُسُونَ', 68, 'ام لكم كتاب فيه تدرسون', 565, 29),
  (5309, 38, '68:38', 57, 226, 501, 7, NULL, 'إِنَّ لَكُمْ فِيهِ لَمَا تَخَيَّرُونَ', 68, 'ان لكم فيه لما تخيرون', 565, 29),
  (5310, 39, '68:39', 57, 226, 501, 7, NULL, 'أَمْ لَكُمْ أَيْمَـٰنٌ عَلَيْنَا بَـٰلِغَةٌ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ ۙ إِنَّ لَكُمْ لَمَا تَحْكُمُونَ', 68, 'ام لكم ايمان علينا بالغة الى يوم القيامة ان لكم لما تحكمون', 565, 29),
  (5311, 40, '68:40', 57, 226, 501, 7, NULL, 'سَلْهُمْ أَيُّهُم بِذَٰلِكَ زَعِيمٌ', 68, 'سلهم ايهم بذلك زعيم', 565, 29),
  (5312, 41, '68:41', 57, 226, 501, 7, NULL, 'أَمْ لَهُمْ شُرَكَآءُ فَلْيَأْتُوا۟ بِشُرَكَآئِهِمْ إِن كَانُوا۟ صَـٰدِقِينَ', 68, 'ام لهم شركاء فلياتوا بشركائهم ان كانوا صادقين', 565, 29),
  (5313, 42, '68:42', 57, 226, 501, 7, NULL, 'يَوْمَ يُكْشَفُ عَن سَاقٍ وَيُدْعَوْنَ إِلَى ٱلسُّجُودِ فَلَا يَسْتَطِيعُونَ', 68, 'يوم يكشف عن ساق ويدعون الى السجود فلا يستطيعون', 565, 29),
  (5314, 43, '68:43', 57, 226, 501, 7, NULL, 'خَـٰشِعَةً أَبْصَـٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ۖ وَقَدْ كَانُوا۟ يُدْعَوْنَ إِلَى ٱلسُّجُودِ وَهُمْ سَـٰلِمُونَ', 68, 'خاشعة ابصارهم ترهقهم ذلة وقد كانوا يدعون الى السجود وهم سالمون', 566, 29),
  (5315, 44, '68:44', 57, 226, 501, 7, NULL, 'فَذَرْنِى وَمَن يُكَذِّبُ بِهَـٰذَا ٱلْحَدِيثِ ۖ سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ', 68, 'فذرني ومن يكذب بهذا الحديث سنستدرجهم من حيث لا يعلمون', 566, 29),
  (5316, 45, '68:45', 57, 226, 501, 7, NULL, 'وَأُمْلِى لَهُمْ ۚ إِنَّ كَيْدِى مَتِينٌ', 68, 'واملي لهم ان كيدي متين', 566, 29),
  (5317, 46, '68:46', 57, 226, 501, 7, NULL, 'أَمْ تَسْـَٔلُهُمْ أَجْرًا فَهُم مِّن مَّغْرَمٍ مُّثْقَلُونَ', 68, 'ام تسالهم اجرا فهم من مغرم مثقلون', 566, 29),
  (5318, 47, '68:47', 57, 226, 501, 7, NULL, 'أَمْ عِندَهُمُ ٱلْغَيْبُ فَهُمْ يَكْتُبُونَ', 68, 'ام عندهم الغيب فهم يكتبون', 566, 29),
  (5319, 48, '68:48', 57, 226, 501, 7, NULL, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلْحُوتِ إِذْ نَادَىٰ وَهُوَ مَكْظُومٌ', 68, 'فاصبر لحكم ربك ولا تكن كصاحب الحوت اذ نادى وهو مكظوم', 566, 29),
  (5320, 49, '68:49', 57, 226, 501, 7, NULL, 'لَّوْلَآ أَن تَدَٰرَكَهُۥ نِعْمَةٌ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلْعَرَآءِ وَهُوَ مَذْمُومٌ', 68, 'لولا ان تداركه نعمة من ربه لنبذ بالعراء وهو مذموم', 566, 29),
  (5321, 50, '68:50', 57, 226, 501, 7, NULL, 'فَٱجْتَبَـٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّـٰلِحِينَ', 68, 'فاجتباه ربه فجعله من الصالحين', 566, 29),
  (5322, 51, '68:51', 57, 226, 501, 7, NULL, 'وَإِن يَكَادُ ٱلَّذِينَ كَفَرُوا۟ لَيُزْلِقُونَكَ بِأَبْصَـٰرِهِمْ لَمَّا سَمِعُوا۟ ٱلذِّكْرَ وَيَقُولُونَ إِنَّهُۥ لَمَجْنُونٌ', 68, 'وان يكاد الذين كفروا ليزلقونك بابصارهم لما سمعوا الذكر ويقولون انه لمجنون', 566, 29),
  (5323, 52, '68:52', 57, 226, 501, 7, NULL, 'وَمَا هُوَ إِلَّا ذِكْرٌ لِّلْعَـٰلَمِينَ', 68, 'وما هو الا ذكر للعالمين', 566, 29),
  (5324, 1, '69:1', 57, 227, 502, 7, NULL, ' ٱلْحَآقَّةُ', 69, 'الحاقة', 566, 29),
  (5325, 2, '69:2', 57, 227, 502, 7, NULL, 'مَا ٱلْحَآقَّةُ', 69, 'ما الحاقة', 566, 29),
  (5326, 3, '69:3', 57, 227, 502, 7, NULL, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحَآقَّةُ', 69, 'وما ادراك ما الحاقة', 566, 29),
  (5327, 4, '69:4', 57, 227, 502, 7, NULL, 'كَذَّبَتْ ثَمُودُ وَعَادٌۢ بِٱلْقَارِعَةِ', 69, 'كذبت ثمود وعاد بالقارعة', 566, 29),
  (5328, 5, '69:5', 57, 227, 502, 7, NULL, 'فَأَمَّا ثَمُودُ فَأُهْلِكُوا۟ بِٱلطَّاغِيَةِ', 69, 'فاما ثمود فاهلكوا بالطاغية', 566, 29),
  (5329, 6, '69:6', 57, 227, 502, 7, NULL, 'وَأَمَّا عَادٌ فَأُهْلِكُوا۟ بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ', 69, 'واما عاد فاهلكوا بريح صرصر عاتية', 566, 29),
  (5330, 7, '69:7', 57, 227, 502, 7, NULL, 'سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَثَمَـٰنِيَةَ أَيَّامٍ حُسُومًا فَتَرَى ٱلْقَوْمَ فِيهَا صَرْعَىٰ كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍ', 69, 'سخرها عليهم سبع ليال وثمانية ايام حسوما فترى القوم فيها صرعى كانهم اعجاز نخل خاوية', 566, 29),
  (5331, 8, '69:8', 57, 227, 502, 7, NULL, 'فَهَلْ تَرَىٰ لَهُم مِّنۢ بَاقِيَةٍ', 69, 'فهل ترى لهم من باقية', 566, 29),
  (5332, 9, '69:9', 57, 227, 502, 7, NULL, 'وَجَآءَ فِرْعَوْنُ وَمَن قَبْلَهُۥ وَٱلْمُؤْتَفِكَـٰتُ بِٱلْخَاطِئَةِ', 69, 'وجاء فرعون ومن قبله والمؤتفكات بالخاطئة', 567, 29),
  (5333, 10, '69:10', 57, 227, 502, 7, NULL, 'فَعَصَوْا۟ رَسُولَ رَبِّهِمْ فَأَخَذَهُمْ أَخْذَةً رَّابِيَةً', 69, 'فعصوا رسول ربهم فاخذهم اخذة رابية', 567, 29),
  (5334, 11, '69:11', 57, 227, 502, 7, NULL, 'إِنَّا لَمَّا طَغَا ٱلْمَآءُ حَمَلْنَـٰكُمْ فِى ٱلْجَارِيَةِ', 69, 'انا لما طغى الماء حملناكم في الجارية', 567, 29),
  (5335, 12, '69:12', 57, 227, 502, 7, NULL, 'لِنَجْعَلَهَا لَكُمْ تَذْكِرَةً وَتَعِيَهَآ أُذُنٌ وَٰعِيَةٌ', 69, 'لنجعلها لكم تذكرة وتعيها اذن واعية', 567, 29),
  (5336, 13, '69:13', 57, 227, 502, 7, NULL, 'فَإِذَا نُفِخَ فِى ٱلصُّورِ نَفْخَةٌ وَٰحِدَةٌ', 69, 'فاذا نفخ في الصور نفخة واحدة', 567, 29),
  (5337, 14, '69:14', 57, 227, 502, 7, NULL, 'وَحُمِلَتِ ٱلْأَرْضُ وَٱلْجِبَالُ فَدُكَّتَا دَكَّةً وَٰحِدَةً', 69, 'وحملت الارض والجبال فدكتا دكة واحدة', 567, 29),
  (5338, 15, '69:15', 57, 227, 502, 7, NULL, 'فَيَوْمَئِذٍ وَقَعَتِ ٱلْوَاقِعَةُ', 69, 'فيومئذ وقعت الواقعة', 567, 29),
  (5339, 16, '69:16', 57, 227, 502, 7, NULL, 'وَٱنشَقَّتِ ٱلسَّمَآءُ فَهِىَ يَوْمَئِذٍ وَاهِيَةٌ', 69, 'وانشقت السماء فهي يومئذ واهية', 567, 29),
  (5340, 17, '69:17', 57, 227, 502, 7, NULL, 'وَٱلْمَلَكُ عَلَىٰٓ أَرْجَآئِهَا ۚ وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمَـٰنِيَةٌ', 69, 'والملك على ارجائها ويحمل عرش ربك فوقهم يومئذ ثمانية', 567, 29),
  (5341, 18, '69:18', 57, 227, 502, 7, NULL, 'يَوْمَئِذٍ تُعْرَضُونَ لَا تَخْفَىٰ مِنكُمْ خَافِيَةٌ', 69, 'يومئذ تعرضون لا تخفى منكم خافية', 567, 29),
  (5342, 19, '69:19', 57, 227, 502, 7, NULL, 'فَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقْرَءُوا۟ كِتَـٰبِيَهْ', 69, 'فاما من اوتي كتابه بيمينه فيقول هاؤم اقرءوا كتابيه', 567, 29),
  (5343, 20, '69:20', 57, 227, 502, 7, NULL, 'إِنِّى ظَنَنتُ أَنِّى مُلَـٰقٍ حِسَابِيَهْ', 69, 'اني ظننت اني ملاق حسابيه', 567, 29),
  (5344, 21, '69:21', 57, 227, 502, 7, NULL, 'فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ', 69, 'فهو في عيشة راضية', 567, 29),
  (5345, 22, '69:22', 57, 227, 502, 7, NULL, 'فِى جَنَّةٍ عَالِيَةٍ', 69, 'في جنة عالية', 567, 29),
  (5346, 23, '69:23', 57, 227, 502, 7, NULL, 'قُطُوفُهَا دَانِيَةٌ', 69, 'قطوفها دانية', 567, 29),
  (5347, 24, '69:24', 57, 227, 502, 7, NULL, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَآ أَسْلَفْتُمْ فِى ٱلْأَيَّامِ ٱلْخَالِيَةِ', 69, 'كلوا واشربوا هنيئا بما اسلفتم في الايام الخالية', 567, 29),
  (5348, 25, '69:25', 57, 227, 502, 7, NULL, 'وَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَـٰلَيْتَنِى لَمْ أُوتَ كِتَـٰبِيَهْ', 69, 'واما من اوتي كتابه بشماله فيقول يا ليتني لم اوت كتابيه', 567, 29),
  (5349, 26, '69:26', 57, 227, 502, 7, NULL, 'وَلَمْ أَدْرِ مَا حِسَابِيَهْ', 69, 'ولم ادر ما حسابيه', 567, 29),
  (5350, 27, '69:27', 57, 227, 502, 7, NULL, 'يَـٰلَيْتَهَا كَانَتِ ٱلْقَاضِيَةَ', 69, 'يا ليتها كانت القاضية', 567, 29),
  (5351, 28, '69:28', 57, 227, 502, 7, NULL, 'مَآ أَغْنَىٰ عَنِّى مَالِيَهْ ۜ', 69, 'ما اغنى عني ماليه', 567, 29),
  (5352, 29, '69:29', 57, 227, 502, 7, NULL, 'هَلَكَ عَنِّى سُلْطَـٰنِيَهْ', 69, 'هلك عني سلطانيه', 567, 29),
  (5353, 30, '69:30', 57, 227, 502, 7, NULL, 'خُذُوهُ فَغُلُّوهُ', 69, 'خذوه فغلوه', 567, 29),
  (5354, 31, '69:31', 57, 227, 502, 7, NULL, 'ثُمَّ ٱلْجَحِيمَ صَلُّوهُ', 69, 'ثم الجحيم صلوه', 567, 29),
  (5355, 32, '69:32', 57, 227, 502, 7, NULL, 'ثُمَّ فِى سِلْسِلَةٍ ذَرْعُهَا سَبْعُونَ ذِرَاعًا فَٱسْلُكُوهُ', 69, 'ثم في سلسلة ذرعها سبعون ذراعا فاسلكوه', 567, 29),
  (5356, 33, '69:33', 57, 227, 502, 7, NULL, 'إِنَّهُۥ كَانَ لَا يُؤْمِنُ بِٱللَّهِ ٱلْعَظِيمِ', 69, 'انه كان لا يؤمن بالله العظيم', 567, 29),
  (5357, 34, '69:34', 57, 227, 502, 7, NULL, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 69, 'ولا يحض على طعام المسكين', 567, 29),
  (5358, 35, '69:35', 57, 227, 502, 7, NULL, 'فَلَيْسَ لَهُ ٱلْيَوْمَ هَـٰهُنَا حَمِيمٌ', 69, 'فليس له اليوم هاهنا حميم', 568, 29),
  (5359, 36, '69:36', 57, 227, 502, 7, NULL, 'وَلَا طَعَامٌ إِلَّا مِنْ غِسْلِينٍ', 69, 'ولا طعام الا من غسلين', 568, 29),
  (5360, 37, '69:37', 57, 227, 502, 7, NULL, 'لَّا يَأْكُلُهُۥٓ إِلَّا ٱلْخَـٰطِـُٔونَ', 69, 'لا ياكله الا الخاطئون', 568, 29),
  (5361, 38, '69:38', 57, 227, 503, 7, NULL, 'فَلَآ أُقْسِمُ بِمَا تُبْصِرُونَ', 69, 'فلا اقسم بما تبصرون', 568, 29),
  (5362, 39, '69:39', 57, 227, 503, 7, NULL, 'وَمَا لَا تُبْصِرُونَ', 69, 'وما لا تبصرون', 568, 29),
  (5363, 40, '69:40', 57, 227, 503, 7, NULL, 'إِنَّهُۥ لَقَوْلُ رَسُولٍ كَرِيمٍ', 69, 'انه لقول رسول كريم', 568, 29),
  (5364, 41, '69:41', 57, 227, 503, 7, NULL, 'وَمَا هُوَ بِقَوْلِ شَاعِرٍ ۚ قَلِيلًا مَّا تُؤْمِنُونَ', 69, 'وما هو بقول شاعر قليلا ما تؤمنون', 568, 29),
  (5365, 42, '69:42', 57, 227, 503, 7, NULL, 'وَلَا بِقَوْلِ كَاهِنٍ ۚ قَلِيلًا مَّا تَذَكَّرُونَ', 69, 'ولا بقول كاهن قليلا ما تذكرون', 568, 29),
  (5366, 43, '69:43', 57, 227, 503, 7, NULL, 'تَنزِيلٌ مِّن رَّبِّ ٱلْعَـٰلَمِينَ', 69, 'تنزيل من رب العالمين', 568, 29),
  (5367, 44, '69:44', 57, 227, 503, 7, NULL, 'وَلَوْ تَقَوَّلَ عَلَيْنَا بَعْضَ ٱلْأَقَاوِيلِ', 69, 'ولو تقول علينا بعض الاقاويل', 568, 29),
  (5368, 45, '69:45', 57, 227, 503, 7, NULL, 'لَأَخَذْنَا مِنْهُ بِٱلْيَمِينِ', 69, 'لاخذنا منه باليمين', 568, 29),
  (5369, 46, '69:46', 57, 227, 503, 7, NULL, 'ثُمَّ لَقَطَعْنَا مِنْهُ ٱلْوَتِينَ', 69, 'ثم لقطعنا منه الوتين', 568, 29),
  (5370, 47, '69:47', 57, 227, 503, 7, NULL, 'فَمَا مِنكُم مِّنْ أَحَدٍ عَنْهُ حَـٰجِزِينَ', 69, 'فما منكم من احد عنه حاجزين', 568, 29),
  (5371, 48, '69:48', 57, 227, 503, 7, NULL, 'وَإِنَّهُۥ لَتَذْكِرَةٌ لِّلْمُتَّقِينَ', 69, 'وانه لتذكرة للمتقين', 568, 29),
  (5372, 49, '69:49', 57, 227, 503, 7, NULL, 'وَإِنَّا لَنَعْلَمُ أَنَّ مِنكُم مُّكَذِّبِينَ', 69, 'وانا لنعلم ان منكم مكذبين', 568, 29),
  (5373, 50, '69:50', 57, 227, 503, 7, NULL, 'وَإِنَّهُۥ لَحَسْرَةٌ عَلَى ٱلْكَـٰفِرِينَ', 69, 'وانه لحسرة على الكافرين', 568, 29),
  (5374, 51, '69:51', 57, 227, 503, 7, NULL, 'وَإِنَّهُۥ لَحَقُّ ٱلْيَقِينِ', 69, 'وانه لحق اليقين', 568, 29),
  (5375, 52, '69:52', 57, 227, 503, 7, NULL, 'فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ', 69, 'فسبح باسم ربك العظيم', 568, 29),
  (5376, 1, '70:1', 57, 227, 504, 7, NULL, ' سَأَلَ سَآئِلٌۢ بِعَذَابٍ وَاقِعٍ', 70, 'سال سائل بعذاب واقع', 568, 29),
  (5377, 2, '70:2', 57, 227, 504, 7, NULL, 'لِّلْكَـٰفِرِينَ لَيْسَ لَهُۥ دَافِعٌ', 70, 'للكافرين ليس له دافع', 568, 29),
  (5378, 3, '70:3', 57, 227, 504, 7, NULL, 'مِّنَ ٱللَّهِ ذِى ٱلْمَعَارِجِ', 70, 'من الله ذي المعارج', 568, 29),
  (5379, 4, '70:4', 57, 227, 504, 7, NULL, 'تَعْرُجُ ٱلْمَلَـٰٓئِكَةُ وَٱلرُّوحُ إِلَيْهِ فِى يَوْمٍ كَانَ مِقْدَارُهُۥ خَمْسِينَ أَلْفَ سَنَةٍ', 70, 'تعرج الملائكة والروح اليه في يوم كان مقداره خمسين الف سنة', 568, 29),
  (5380, 5, '70:5', 57, 227, 504, 7, NULL, 'فَٱصْبِرْ صَبْرًا جَمِيلًا', 70, 'فاصبر صبرا جميلا', 568, 29),
  (5381, 6, '70:6', 57, 227, 504, 7, NULL, 'إِنَّهُمْ يَرَوْنَهُۥ بَعِيدًا', 70, 'انهم يرونه بعيدا', 568, 29),
  (5382, 7, '70:7', 57, 227, 504, 7, NULL, 'وَنَرَىٰهُ قَرِيبًا', 70, 'ونراه قريبا', 568, 29),
  (5383, 8, '70:8', 57, 227, 504, 7, NULL, 'يَوْمَ تَكُونُ ٱلسَّمَآءُ كَٱلْمُهْلِ', 70, 'يوم تكون السماء كالمهل', 568, 29),
  (5384, 9, '70:9', 57, 227, 504, 7, NULL, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ', 70, 'وتكون الجبال كالعهن', 568, 29),
  (5385, 10, '70:10', 57, 227, 504, 7, NULL, 'وَلَا يَسْـَٔلُ حَمِيمٌ حَمِيمًا', 70, 'ولا يسال حميم حميما', 568, 29),
  (5386, 11, '70:11', 57, 227, 504, 7, NULL, 'يُبَصَّرُونَهُمْ ۚ يَوَدُّ ٱلْمُجْرِمُ لَوْ يَفْتَدِى مِنْ عَذَابِ يَوْمِئِذٍۭ بِبَنِيهِ', 70, 'يبصرونهم يود المجرم لو يفتدي من عذاب يومئذ ببنيه', 569, 29),
  (5387, 12, '70:12', 57, 227, 504, 7, NULL, 'وَصَـٰحِبَتِهِۦ وَأَخِيهِ', 70, 'وصاحبته واخيه', 569, 29),
  (5388, 13, '70:13', 57, 227, 504, 7, NULL, 'وَفَصِيلَتِهِ ٱلَّتِى تُـْٔوِيهِ', 70, 'وفصيلته التي تؤويه', 569, 29),
  (5389, 14, '70:14', 57, 227, 504, 7, NULL, 'وَمَن فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ يُنجِيهِ', 70, 'ومن في الارض جميعا ثم ينجيه', 569, 29),
  (5390, 15, '70:15', 57, 227, 504, 7, NULL, 'كَلَّآ ۖ إِنَّهَا لَظَىٰ', 70, 'كلا انها لظى', 569, 29),
  (5391, 16, '70:16', 57, 227, 504, 7, NULL, 'نَزَّاعَةً لِّلشَّوَىٰ', 70, 'نزاعة للشوى', 569, 29),
  (5392, 17, '70:17', 57, 227, 504, 7, NULL, 'تَدْعُوا۟ مَنْ أَدْبَرَ وَتَوَلَّىٰ', 70, 'تدعو من ادبر وتولى', 569, 29),
  (5393, 18, '70:18', 57, 227, 504, 7, NULL, 'وَجَمَعَ فَأَوْعَىٰٓ', 70, 'وجمع فاوعى', 569, 29),
  (5394, 19, '70:19', 57, 228, 504, 7, NULL, '۞ إِنَّ ٱلْإِنسَـٰنَ خُلِقَ هَلُوعًا', 70, 'ان الانسان خلق هلوعا', 569, 29),
  (5395, 20, '70:20', 57, 228, 504, 7, NULL, 'إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعًا', 70, 'اذا مسه الشر جزوعا', 569, 29),
  (5396, 21, '70:21', 57, 228, 504, 7, NULL, 'وَإِذَا مَسَّهُ ٱلْخَيْرُ مَنُوعًا', 70, 'واذا مسه الخير منوعا', 569, 29),
  (5397, 22, '70:22', 57, 228, 504, 7, NULL, 'إِلَّا ٱلْمُصَلِّينَ', 70, 'الا المصلين', 569, 29),
  (5398, 23, '70:23', 57, 228, 504, 7, NULL, 'ٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ دَآئِمُونَ', 70, 'الذين هم على صلاتهم دائمون', 569, 29),
  (5399, 24, '70:24', 57, 228, 504, 7, NULL, 'وَٱلَّذِينَ فِىٓ أَمْوَٰلِهِمْ حَقٌّ مَّعْلُومٌ', 70, 'والذين في اموالهم حق معلوم', 569, 29),
  (5400, 25, '70:25', 57, 228, 504, 7, NULL, 'لِّلسَّآئِلِ وَٱلْمَحْرُومِ', 70, 'للسائل والمحروم', 569, 29),
  (5401, 26, '70:26', 57, 228, 504, 7, NULL, 'وَٱلَّذِينَ يُصَدِّقُونَ بِيَوْمِ ٱلدِّينِ', 70, 'والذين يصدقون بيوم الدين', 569, 29),
  (5402, 27, '70:27', 57, 228, 504, 7, NULL, 'وَٱلَّذِينَ هُم مِّنْ عَذَابِ رَبِّهِم مُّشْفِقُونَ', 70, 'والذين هم من عذاب ربهم مشفقون', 569, 29),
  (5403, 28, '70:28', 57, 228, 504, 7, NULL, 'إِنَّ عَذَابَ رَبِّهِمْ غَيْرُ مَأْمُونٍ', 70, 'ان عذاب ربهم غير مامون', 569, 29),
  (5404, 29, '70:29', 57, 228, 504, 7, NULL, 'وَٱلَّذِينَ هُمْ لِفُرُوجِهِمْ حَـٰفِظُونَ', 70, 'والذين هم لفروجهم حافظون', 569, 29),
  (5405, 30, '70:30', 57, 228, 504, 7, NULL, 'إِلَّا عَلَىٰٓ أَزْوَٰجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَـٰنُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ', 70, 'الا على ازواجهم او ما ملكت ايمانهم فانهم غير ملومين', 569, 29),
  (5406, 31, '70:31', 57, 228, 504, 7, NULL, 'فَمَنِ ٱبْتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُو۟لَـٰٓئِكَ هُمُ ٱلْعَادُونَ', 70, 'فمن ابتغى وراء ذلك فاولئك هم العادون', 569, 29),
  (5407, 32, '70:32', 57, 228, 504, 7, NULL, 'وَٱلَّذِينَ هُمْ لِأَمَـٰنَـٰتِهِمْ وَعَهْدِهِمْ رَٰعُونَ', 70, 'والذين هم لاماناتهم وعهدهم راعون', 569, 29),
  (5408, 33, '70:33', 57, 228, 504, 7, NULL, 'وَٱلَّذِينَ هُم بِشَهَـٰدَٰتِهِمْ قَآئِمُونَ', 70, 'والذين هم بشهاداتهم قائمون', 569, 29),
  (5409, 34, '70:34', 57, 228, 504, 7, NULL, 'وَٱلَّذِينَ هُمْ عَلَىٰ صَلَاتِهِمْ يُحَافِظُونَ', 70, 'والذين هم على صلاتهم يحافظون', 569, 29),
  (5410, 35, '70:35', 57, 228, 504, 7, NULL, 'أُو۟لَـٰٓئِكَ فِى جَنَّـٰتٍ مُّكْرَمُونَ', 70, 'اولئك في جنات مكرمون', 569, 29),
  (5411, 36, '70:36', 57, 228, 505, 7, NULL, 'فَمَالِ ٱلَّذِينَ كَفَرُوا۟ قِبَلَكَ مُهْطِعِينَ', 70, 'فمال الذين كفروا قبلك مهطعين', 569, 29),
  (5412, 37, '70:37', 57, 228, 505, 7, NULL, 'عَنِ ٱلْيَمِينِ وَعَنِ ٱلشِّمَالِ عِزِينَ', 70, 'عن اليمين وعن الشمال عزين', 569, 29),
  (5413, 38, '70:38', 57, 228, 505, 7, NULL, 'أَيَطْمَعُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُدْخَلَ جَنَّةَ نَعِيمٍ', 70, 'ايطمع كل امرئ منهم ان يدخل جنة نعيم', 569, 29),
  (5414, 39, '70:39', 57, 228, 505, 7, NULL, 'كَلَّآ ۖ إِنَّا خَلَقْنَـٰهُم مِّمَّا يَعْلَمُونَ', 70, 'كلا انا خلقناهم مما يعلمون', 569, 29),
  (5415, 40, '70:40', 57, 228, 505, 7, NULL, 'فَلَآ أُقْسِمُ بِرَبِّ ٱلْمَشَـٰرِقِ وَٱلْمَغَـٰرِبِ إِنَّا لَقَـٰدِرُونَ', 70, 'فلا اقسم برب المشارق والمغارب انا لقادرون', 570, 29),
  (5416, 41, '70:41', 57, 228, 505, 7, NULL, 'عَلَىٰٓ أَن نُّبَدِّلَ خَيْرًا مِّنْهُمْ وَمَا نَحْنُ بِمَسْبُوقِينَ', 70, 'على ان نبدل خيرا منهم وما نحن بمسبوقين', 570, 29),
  (5417, 42, '70:42', 57, 228, 505, 7, NULL, 'فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَـٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ', 70, 'فذرهم يخوضوا ويلعبوا حتى يلاقوا يومهم الذي يوعدون', 570, 29),
  (5418, 43, '70:43', 57, 228, 505, 7, NULL, 'يَوْمَ يَخْرُجُونَ مِنَ ٱلْأَجْدَاثِ سِرَاعًا كَأَنَّهُمْ إِلَىٰ نُصُبٍ يُوفِضُونَ', 70, 'يوم يخرجون من الاجداث سراعا كانهم الى نصب يوفضون', 570, 29),
  (5419, 44, '70:44', 57, 228, 505, 7, NULL, 'خَـٰشِعَةً أَبْصَـٰرُهُمْ تَرْهَقُهُمْ ذِلَّةٌ ۚ ذَٰلِكَ ٱلْيَوْمُ ٱلَّذِى كَانُوا۟ يُوعَدُونَ', 70, 'خاشعة ابصارهم ترهقهم ذلة ذلك اليوم الذي كانوا يوعدون', 570, 29),
  (5420, 1, '71:1', 57, 228, 506, 7, NULL, ' إِنَّآ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦٓ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ', 71, 'انا ارسلنا نوحا الى قومه ان انذر قومك من قبل ان ياتيهم عذاب اليم', 570, 29),
  (5421, 2, '71:2', 57, 228, 506, 7, NULL, 'قَالَ يَـٰقَوْمِ إِنِّى لَكُمْ نَذِيرٌ مُّبِينٌ', 71, 'قال يا قوم اني لكم نذير مبين', 570, 29),
  (5422, 3, '71:3', 57, 228, 506, 7, NULL, 'أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ', 71, 'ان اعبدوا الله واتقوه واطيعون', 570, 29),
  (5423, 4, '71:4', 57, 228, 506, 7, NULL, 'يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرْكُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى ۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُ ۖ لَوْ كُنتُمْ تَعْلَمُونَ', 71, 'يغفر لكم من ذنوبكم ويؤخركم الى اجل مسمى ان اجل الله اذا جاء لا يؤخر لو كنتم تعلمون', 570, 29),
  (5424, 5, '71:5', 57, 228, 506, 7, NULL, 'قَالَ رَبِّ إِنِّى دَعَوْتُ قَوْمِى لَيْلًا وَنَهَارًا', 71, 'قال رب اني دعوت قومي ليلا ونهارا', 570, 29),
  (5425, 6, '71:6', 57, 228, 506, 7, NULL, 'فَلَمْ يَزِدْهُمْ دُعَآءِىٓ إِلَّا فِرَارًا', 71, 'فلم يزدهم دعائي الا فرارا', 570, 29),
  (5426, 7, '71:7', 57, 228, 506, 7, NULL, 'وَإِنِّى كُلَّمَا دَعَوْتُهُمْ لِتَغْفِرَ لَهُمْ جَعَلُوٓا۟ أَصَـٰبِعَهُمْ فِىٓ ءَاذَانِهِمْ وَٱسْتَغْشَوْا۟ ثِيَابَهُمْ وَأَصَرُّوا۟ وَٱسْتَكْبَرُوا۟ ٱسْتِكْبَارًا', 71, 'واني كلما دعوتهم لتغفر لهم جعلوا اصابعهم في اذانهم واستغشوا ثيابهم واصروا واستكبروا استكبارا', 570, 29),
  (5427, 8, '71:8', 57, 228, 506, 7, NULL, 'ثُمَّ إِنِّى دَعَوْتُهُمْ جِهَارًا', 71, 'ثم اني دعوتهم جهارا', 570, 29),
  (5428, 9, '71:9', 57, 228, 506, 7, NULL, 'ثُمَّ إِنِّىٓ أَعْلَنتُ لَهُمْ وَأَسْرَرْتُ لَهُمْ إِسْرَارًا', 71, 'ثم اني اعلنت لهم واسررت لهم اسرارا', 570, 29),
  (5429, 10, '71:10', 57, 228, 506, 7, NULL, 'فَقُلْتُ ٱسْتَغْفِرُوا۟ رَبَّكُمْ إِنَّهُۥ كَانَ غَفَّارًا', 71, 'فقلت استغفروا ربكم انه كان غفارا', 570, 29),
  (5430, 11, '71:11', 57, 228, 506, 7, NULL, 'يُرْسِلِ ٱلسَّمَآءَ عَلَيْكُم مِّدْرَارًا', 71, 'يرسل السماء عليكم مدرارا', 571, 29),
  (5431, 12, '71:12', 57, 228, 506, 7, NULL, 'وَيُمْدِدْكُم بِأَمْوَٰلٍ وَبَنِينَ وَيَجْعَل لَّكُمْ جَنَّـٰتٍ وَيَجْعَل لَّكُمْ أَنْهَـٰرًا', 71, 'ويمددكم باموال وبنين ويجعل لكم جنات ويجعل لكم انهارا', 571, 29),
  (5432, 13, '71:13', 57, 228, 506, 7, NULL, 'مَّا لَكُمْ لَا تَرْجُونَ لِلَّهِ وَقَارًا', 71, 'ما لكم لا ترجون لله وقارا', 571, 29),
  (5433, 14, '71:14', 57, 228, 506, 7, NULL, 'وَقَدْ خَلَقَكُمْ أَطْوَارًا', 71, 'وقد خلقكم اطوارا', 571, 29),
  (5434, 15, '71:15', 57, 228, 506, 7, NULL, 'أَلَمْ تَرَوْا۟ كَيْفَ خَلَقَ ٱللَّهُ سَبْعَ سَمَـٰوَٰتٍ طِبَاقًا', 71, 'الم تروا كيف خلق الله سبع سماوات طباقا', 571, 29),
  (5435, 16, '71:16', 57, 228, 506, 7, NULL, 'وَجَعَلَ ٱلْقَمَرَ فِيهِنَّ نُورًا وَجَعَلَ ٱلشَّمْسَ سِرَاجًا', 71, 'وجعل القمر فيهن نورا وجعل الشمس سراجا', 571, 29),
  (5436, 17, '71:17', 57, 228, 506, 7, NULL, 'وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلْأَرْضِ نَبَاتًا', 71, 'والله انبتكم من الارض نباتا', 571, 29),
  (5437, 18, '71:18', 57, 228, 506, 7, NULL, 'ثُمَّ يُعِيدُكُمْ فِيهَا وَيُخْرِجُكُمْ إِخْرَاجًا', 71, 'ثم يعيدكم فيها ويخرجكم اخراجا', 571, 29),
  (5438, 19, '71:19', 57, 228, 506, 7, NULL, 'وَٱللَّهُ جَعَلَ لَكُمُ ٱلْأَرْضَ بِسَاطًا', 71, 'والله جعل لكم الارض بساطا', 571, 29),
  (5439, 20, '71:20', 57, 228, 506, 7, NULL, 'لِّتَسْلُكُوا۟ مِنْهَا سُبُلًا فِجَاجًا', 71, 'لتسلكوا منها سبلا فجاجا', 571, 29),
  (5440, 21, '71:21', 57, 228, 507, 7, NULL, 'قَالَ نُوحٌ رَّبِّ إِنَّهُمْ عَصَوْنِى وَٱتَّبَعُوا۟ مَن لَّمْ يَزِدْهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارًا', 71, 'قال نوح رب انهم عصوني واتبعوا من لم يزده ماله وولده الا خسارا', 571, 29),
  (5441, 22, '71:22', 57, 228, 507, 7, NULL, 'وَمَكَرُوا۟ مَكْرًا كُبَّارًا', 71, 'ومكروا مكرا كبارا', 571, 29),
  (5442, 23, '71:23', 57, 228, 507, 7, NULL, 'وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمْ وَلَا تَذَرُنَّ وَدًّا وَلَا سُوَاعًا وَلَا يَغُوثَ وَيَعُوقَ وَنَسْرًا', 71, 'وقالوا لا تذرن الهتكم ولا تذرن ودا ولا سواعا ولا يغوث ويعوق ونسرا', 571, 29),
  (5443, 24, '71:24', 57, 228, 507, 7, NULL, 'وَقَدْ أَضَلُّوا۟ كَثِيرًا ۖ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا ضَلَـٰلًا', 71, 'وقد اضلوا كثيرا ولا تزد الظالمين الا ضلالا', 571, 29),
  (5444, 25, '71:25', 57, 228, 507, 7, NULL, 'مِّمَّا خَطِيٓـَٔـٰتِهِمْ أُغْرِقُوا۟ فَأُدْخِلُوا۟ نَارًا فَلَمْ يَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارًا', 71, 'مما خطيئاتهم اغرقوا فادخلوا نارا فلم يجدوا لهم من دون الله انصارا', 571, 29),
  (5445, 26, '71:26', 57, 228, 507, 7, NULL, 'وَقَالَ نُوحٌ رَّبِّ لَا تَذَرْ عَلَى ٱلْأَرْضِ مِنَ ٱلْكَـٰفِرِينَ دَيَّارًا', 71, 'وقال نوح رب لا تذر على الارض من الكافرين ديارا', 571, 29),
  (5446, 27, '71:27', 57, 228, 507, 7, NULL, 'إِنَّكَ إِن تَذَرْهُمْ يُضِلُّوا۟ عِبَادَكَ وَلَا يَلِدُوٓا۟ إِلَّا فَاجِرًا كَفَّارًا', 71, 'انك ان تذرهم يضلوا عبادك ولا يلدوا الا فاجرا كفارا', 571, 29),
  (5447, 28, '71:28', 57, 228, 507, 7, NULL, 'رَّبِّ ٱغْفِرْ لِى وَلِوَٰلِدَىَّ وَلِمَن دَخَلَ بَيْتِىَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ وَلَا تَزِدِ ٱلظَّـٰلِمِينَ إِلَّا تَبَارًۢا', 71, 'رب اغفر لي ولوالدي ولمن دخل بيتي مؤمنا وللمؤمنين والمؤمنات ولا تزد الظالمين الا تبارا', 571, 29),
  (5448, 1, '72:1', 58, 229, 508, 7, NULL, ' قُلْ أُوحِىَ إِلَىَّ أَنَّهُ ٱسْتَمَعَ نَفَرٌ مِّنَ ٱلْجِنِّ فَقَالُوٓا۟ إِنَّا سَمِعْنَا قُرْءَانًا عَجَبًا', 72, 'قل اوحي الي انه استمع نفر من الجن فقالوا انا سمعنا قرانا عجبا', 572, 29),
  (5449, 2, '72:2', 58, 229, 508, 7, NULL, 'يَهْدِىٓ إِلَى ٱلرُّشْدِ فَـَٔامَنَّا بِهِۦ ۖ وَلَن نُّشْرِكَ بِرَبِّنَآ أَحَدًا', 72, 'يهدي الى الرشد فامنا به ولن نشرك بربنا احدا', 572, 29),
  (5450, 3, '72:3', 58, 229, 508, 7, NULL, 'وَأَنَّهُۥ تَعَـٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَـٰحِبَةً وَلَا وَلَدًا', 72, 'وانه تعالى جد ربنا ما اتخذ صاحبة ولا ولدا', 572, 29),
  (5451, 4, '72:4', 58, 229, 508, 7, NULL, 'وَأَنَّهُۥ كَانَ يَقُولُ سَفِيهُنَا عَلَى ٱللَّهِ شَطَطًا', 72, 'وانه كان يقول سفيهنا على الله شططا', 572, 29),
  (5452, 5, '72:5', 58, 229, 508, 7, NULL, 'وَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلْإِنسُ وَٱلْجِنُّ عَلَى ٱللَّهِ كَذِبًا', 72, 'وانا ظننا ان لن تقول الانس والجن على الله كذبا', 572, 29),
  (5453, 6, '72:6', 58, 229, 508, 7, NULL, 'وَأَنَّهُۥ كَانَ رِجَالٌ مِّنَ ٱلْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ ٱلْجِنِّ فَزَادُوهُمْ رَهَقًا', 72, 'وانه كان رجال من الانس يعوذون برجال من الجن فزادوهم رهقا', 572, 29),
  (5454, 7, '72:7', 58, 229, 508, 7, NULL, 'وَأَنَّهُمْ ظَنُّوا۟ كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ ٱللَّهُ أَحَدًا', 72, 'وانهم ظنوا كما ظننتم ان لن يبعث الله احدا', 572, 29),
  (5455, 8, '72:8', 58, 229, 508, 7, NULL, 'وَأَنَّا لَمَسْنَا ٱلسَّمَآءَ فَوَجَدْنَـٰهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا', 72, 'وانا لمسنا السماء فوجدناها ملئت حرسا شديدا وشهبا', 572, 29),
  (5456, 9, '72:9', 58, 229, 508, 7, NULL, 'وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَـٰعِدَ لِلسَّمْعِ ۖ فَمَن يَسْتَمِعِ ٱلْـَٔانَ يَجِدْ لَهُۥ شِهَابًا رَّصَدًا', 72, 'وانا كنا نقعد منها مقاعد للسمع فمن يستمع الان يجد له شهابا رصدا', 572, 29),
  (5457, 10, '72:10', 58, 229, 508, 7, NULL, 'وَأَنَّا لَا نَدْرِىٓ أَشَرٌّ أُرِيدَ بِمَن فِى ٱلْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا', 72, 'وانا لا ندري اشر اريد بمن في الارض ام اراد بهم ربهم رشدا', 572, 29),
  (5458, 11, '72:11', 58, 229, 508, 7, NULL, 'وَأَنَّا مِنَّا ٱلصَّـٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَ ۖ كُنَّا طَرَآئِقَ قِدَدًا', 72, 'وانا منا الصالحون ومنا دون ذلك كنا طرائق قددا', 572, 29),
  (5459, 12, '72:12', 58, 229, 508, 7, NULL, 'وَأَنَّا ظَنَنَّآ أَن لَّن نُّعْجِزَ ٱللَّهَ فِى ٱلْأَرْضِ وَلَن نُّعْجِزَهُۥ هَرَبًا', 72, 'وانا ظننا ان لن نعجز الله في الارض ولن نعجزه هربا', 572, 29),
  (5460, 13, '72:13', 58, 229, 508, 7, NULL, 'وَأَنَّا لَمَّا سَمِعْنَا ٱلْهُدَىٰٓ ءَامَنَّا بِهِۦ ۖ فَمَن يُؤْمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخْسًا وَلَا رَهَقًا', 72, 'وانا لما سمعنا الهدى امنا به فمن يؤمن بربه فلا يخاف بخسا ولا رهقا', 572, 29),
  (5461, 14, '72:14', 58, 229, 508, 7, NULL, 'وَأَنَّا مِنَّا ٱلْمُسْلِمُونَ وَمِنَّا ٱلْقَـٰسِطُونَ ۖ فَمَنْ أَسْلَمَ فَأُو۟لَـٰٓئِكَ تَحَرَّوْا۟ رَشَدًا', 72, 'وانا منا المسلمون ومنا القاسطون فمن اسلم فاولئك تحروا رشدا', 573, 29),
  (5462, 15, '72:15', 58, 229, 508, 7, NULL, 'وَأَمَّا ٱلْقَـٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبًا', 72, 'واما القاسطون فكانوا لجهنم حطبا', 573, 29),
  (5463, 16, '72:16', 58, 229, 508, 7, NULL, 'وَأَلَّوِ ٱسْتَقَـٰمُوا۟ عَلَى ٱلطَّرِيقَةِ لَأَسْقَيْنَـٰهُم مَّآءً غَدَقًا', 72, 'وان لو استقاموا على الطريقة لاسقيناهم ماء غدقا', 573, 29),
  (5464, 17, '72:17', 58, 229, 508, 7, NULL, 'لِّنَفْتِنَهُمْ فِيهِ ۚ وَمَن يُعْرِضْ عَن ذِكْرِ رَبِّهِۦ يَسْلُكْهُ عَذَابًا صَعَدًا', 72, 'لنفتنهم فيه ومن يعرض عن ذكر ربه يسلكه عذابا صعدا', 573, 29),
  (5465, 18, '72:18', 58, 229, 508, 7, NULL, 'وَأَنَّ ٱلْمَسَـٰجِدَ لِلَّهِ فَلَا تَدْعُوا۟ مَعَ ٱللَّهِ أَحَدًا', 72, 'وان المساجد لله فلا تدعوا مع الله احدا', 573, 29),
  (5466, 19, '72:19', 58, 229, 508, 7, NULL, 'وَأَنَّهُۥ لَمَّا قَامَ عَبْدُ ٱللَّهِ يَدْعُوهُ كَادُوا۟ يَكُونُونَ عَلَيْهِ لِبَدًا', 72, 'وانه لما قام عبد الله يدعوه كادوا يكونون عليه لبدا', 573, 29),
  (5467, 20, '72:20', 58, 229, 509, 7, NULL, 'قُلْ إِنَّمَآ أَدْعُوا۟ رَبِّى وَلَآ أُشْرِكُ بِهِۦٓ أَحَدًا', 72, 'قل انما ادعو ربي ولا اشرك به احدا', 573, 29),
  (5468, 21, '72:21', 58, 229, 509, 7, NULL, 'قُلْ إِنِّى لَآ أَمْلِكُ لَكُمْ ضَرًّا وَلَا رَشَدًا', 72, 'قل اني لا املك لكم ضرا ولا رشدا', 573, 29),
  (5469, 22, '72:22', 58, 229, 509, 7, NULL, 'قُلْ إِنِّى لَن يُجِيرَنِى مِنَ ٱللَّهِ أَحَدٌ وَلَنْ أَجِدَ مِن دُونِهِۦ مُلْتَحَدًا', 72, 'قل اني لن يجيرني من الله احد ولن اجد من دونه ملتحدا', 573, 29),
  (5470, 23, '72:23', 58, 229, 509, 7, NULL, 'إِلَّا بَلَـٰغًا مِّنَ ٱللَّهِ وَرِسَـٰلَـٰتِهِۦ ۚ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ أَبَدًا', 72, 'الا بلاغا من الله ورسالاته ومن يعص الله ورسوله فان له نار جهنم خالدين فيها ابدا', 573, 29),
  (5471, 24, '72:24', 58, 229, 509, 7, NULL, 'حَتَّىٰٓ إِذَا رَأَوْا۟ مَا يُوعَدُونَ فَسَيَعْلَمُونَ مَنْ أَضْعَفُ نَاصِرًا وَأَقَلُّ عَدَدًا', 72, 'حتى اذا راوا ما يوعدون فسيعلمون من اضعف ناصرا واقل عددا', 573, 29),
  (5472, 25, '72:25', 58, 229, 509, 7, NULL, 'قُلْ إِنْ أَدْرِىٓ أَقَرِيبٌ مَّا تُوعَدُونَ أَمْ يَجْعَلُ لَهُۥ رَبِّىٓ أَمَدًا', 72, 'قل ان ادري اقريب ما توعدون ام يجعل له ربي امدا', 573, 29),
  (5473, 26, '72:26', 58, 229, 509, 7, NULL, 'عَـٰلِمُ ٱلْغَيْبِ فَلَا يُظْهِرُ عَلَىٰ غَيْبِهِۦٓ أَحَدًا', 72, 'عالم الغيب فلا يظهر على غيبه احدا', 573, 29),
  (5474, 27, '72:27', 58, 229, 509, 7, NULL, 'إِلَّا مَنِ ٱرْتَضَىٰ مِن رَّسُولٍ فَإِنَّهُۥ يَسْلُكُ مِنۢ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِۦ رَصَدًا', 72, 'الا من ارتضى من رسول فانه يسلك من بين يديه ومن خلفه رصدا', 573, 29),
  (5475, 28, '72:28', 58, 229, 509, 7, NULL, 'لِّيَعْلَمَ أَن قَدْ أَبْلَغُوا۟ رِسَـٰلَـٰتِ رَبِّهِمْ وَأَحَاطَ بِمَا لَدَيْهِمْ وَأَحْصَىٰ كُلَّ شَىْءٍ عَدَدًۢا', 72, 'ليعلم ان قد ابلغوا رسالات ربهم واحاط بما لديهم واحصى كل شيء عددا', 573, 29),
  (5476, 1, '73:1', 58, 229, 510, 7, NULL, ' يَـٰٓأَيُّهَا ٱلْمُزَّمِّلُ', 73, 'يا ايها المزمل', 574, 29),
  (5477, 2, '73:2', 58, 229, 510, 7, NULL, 'قُمِ ٱلَّيْلَ إِلَّا قَلِيلًا', 73, 'قم الليل الا قليلا', 574, 29),
  (5478, 3, '73:3', 58, 229, 510, 7, NULL, 'نِّصْفَهُۥٓ أَوِ ٱنقُصْ مِنْهُ قَلِيلًا', 73, 'نصفه او انقص منه قليلا', 574, 29),
  (5479, 4, '73:4', 58, 229, 510, 7, NULL, 'أَوْ زِدْ عَلَيْهِ وَرَتِّلِ ٱلْقُرْءَانَ تَرْتِيلًا', 73, 'او زد عليه ورتل القران ترتيلا', 574, 29),
  (5480, 5, '73:5', 58, 229, 510, 7, NULL, 'إِنَّا سَنُلْقِى عَلَيْكَ قَوْلًا ثَقِيلًا', 73, 'انا سنلقي عليك قولا ثقيلا', 574, 29),
  (5481, 6, '73:6', 58, 229, 510, 7, NULL, 'إِنَّ نَاشِئَةَ ٱلَّيْلِ هِىَ أَشَدُّ وَطْـًٔا وَأَقْوَمُ قِيلًا', 73, 'ان ناشئة الليل هي اشد وطئا واقوم قيلا', 574, 29),
  (5482, 7, '73:7', 58, 229, 510, 7, NULL, 'إِنَّ لَكَ فِى ٱلنَّهَارِ سَبْحًا طَوِيلًا', 73, 'ان لك في النهار سبحا طويلا', 574, 29),
  (5483, 8, '73:8', 58, 229, 510, 7, NULL, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا', 73, 'واذكر اسم ربك وتبتل اليه تبتيلا', 574, 29),
  (5484, 9, '73:9', 58, 229, 510, 7, NULL, 'رَّبُّ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ لَآ إِلَـٰهَ إِلَّا هُوَ فَٱتَّخِذْهُ وَكِيلًا', 73, 'رب المشرق والمغرب لا اله الا هو فاتخذه وكيلا', 574, 29),
  (5485, 10, '73:10', 58, 229, 510, 7, NULL, 'وَٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱهْجُرْهُمْ هَجْرًا جَمِيلًا', 73, 'واصبر على ما يقولون واهجرهم هجرا جميلا', 574, 29),
  (5486, 11, '73:11', 58, 229, 510, 7, NULL, 'وَذَرْنِى وَٱلْمُكَذِّبِينَ أُو۟لِى ٱلنَّعْمَةِ وَمَهِّلْهُمْ قَلِيلًا', 73, 'وذرني والمكذبين اولي النعمة ومهلهم قليلا', 574, 29),
  (5487, 12, '73:12', 58, 229, 510, 7, NULL, 'إِنَّ لَدَيْنَآ أَنكَالًا وَجَحِيمًا', 73, 'ان لدينا انكالا وجحيما', 574, 29),
  (5488, 13, '73:13', 58, 229, 510, 7, NULL, 'وَطَعَامًا ذَا غُصَّةٍ وَعَذَابًا أَلِيمًا', 73, 'وطعاما ذا غصة وعذابا اليما', 574, 29),
  (5489, 14, '73:14', 58, 229, 510, 7, NULL, 'يَوْمَ تَرْجُفُ ٱلْأَرْضُ وَٱلْجِبَالُ وَكَانَتِ ٱلْجِبَالُ كَثِيبًا مَّهِيلًا', 73, 'يوم ترجف الارض والجبال وكانت الجبال كثيبا مهيلا', 574, 29),
  (5490, 15, '73:15', 58, 229, 510, 7, NULL, 'إِنَّآ أَرْسَلْنَآ إِلَيْكُمْ رَسُولًا شَـٰهِدًا عَلَيْكُمْ كَمَآ أَرْسَلْنَآ إِلَىٰ فِرْعَوْنَ رَسُولًا', 73, 'انا ارسلنا اليكم رسولا شاهدا عليكم كما ارسلنا الى فرعون رسولا', 574, 29),
  (5491, 16, '73:16', 58, 229, 510, 7, NULL, 'فَعَصَىٰ فِرْعَوْنُ ٱلرَّسُولَ فَأَخَذْنَـٰهُ أَخْذًا وَبِيلًا', 73, 'فعصى فرعون الرسول فاخذناه اخذا وبيلا', 574, 29),
  (5492, 17, '73:17', 58, 229, 510, 7, NULL, 'فَكَيْفَ تَتَّقُونَ إِن كَفَرْتُمْ يَوْمًا يَجْعَلُ ٱلْوِلْدَٰنَ شِيبًا', 73, 'فكيف تتقون ان كفرتم يوما يجعل الولدان شيبا', 574, 29),
  (5493, 18, '73:18', 58, 229, 510, 7, NULL, 'ٱلسَّمَآءُ مُنفَطِرٌۢ بِهِۦ ۚ كَانَ وَعْدُهُۥ مَفْعُولًا', 73, 'السماء منفطر به كان وعده مفعولا', 574, 29),
  (5494, 19, '73:19', 58, 229, 510, 7, NULL, 'إِنَّ هَـٰذِهِۦ تَذْكِرَةٌ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', 73, 'ان هذه تذكرة فمن شاء اتخذ الى ربه سبيلا', 574, 29),
  (5495, 20, '73:20', 58, 230, 511, 7, NULL, '۞ إِنَّ رَبَّكَ يَعْلَمُ أَنَّكَ تَقُومُ أَدْنَىٰ مِن ثُلُثَىِ ٱلَّيْلِ وَنِصْفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٌ مِّنَ ٱلَّذِينَ مَعَكَ ۚ وَٱللَّهُ يُقَدِّرُ ٱلَّيْلَ وَٱلنَّهَارَ ۚ عَلِمَ أَن لَّن تُحْصُوهُ فَتَابَ عَلَيْكُمْ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنَ ٱلْقُرْءَانِ ۚ عَلِمَ أَن سَيَكُونُ مِنكُم مَّرْضَىٰ ۙ وَءَاخَرُونَ يَضْرِبُونَ فِى ٱلْأَرْضِ يَبْتَغُونَ مِن فَضْلِ ٱللَّهِ ۙ وَءَاخَرُونَ يُقَـٰتِلُونَ فِى سَبِيلِ ٱللَّهِ ۖ فَٱقْرَءُوا۟ مَا تَيَسَّرَ مِنْهُ ۚ وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَقْرِضُوا۟ ٱللَّهَ قَرْضًا حَسَنًا ۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَيْرًا وَأَعْظَمَ أَجْرًا ۚ وَٱسْتَغْفِرُوا۟ ٱللَّهَ ۖ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌۢ', 73, 'ان ربك يعلم انك تقوم ادنى من ثلثي الليل ونصفه وثلثه وطائفة من الذين معك والله يقدر الليل والنهار علم ان لن تحصوه فتاب عليكم فاقرءوا ما تيسر من القران علم ان سيكون منكم مرضى واخرون يضربون في الارض يبتغون من فضل الله واخرون يقاتلون في سبيل الله فاقرءوا ما تيسر منه واقيموا الصلاة واتوا الزكاة واقرضوا الله قرضا حسنا وما تقدموا لانفسكم من خير تجدوه عند الله هو خيرا واعظم اجرا واستغفروا الله ان الله غفور رحيم', 575, 29),
  (5496, 1, '74:1', 58, 230, 512, 7, NULL, ' يَـٰٓأَيُّهَا ٱلْمُدَّثِّرُ', 74, 'يا ايها المدثر', 575, 29),
  (5497, 2, '74:2', 58, 230, 512, 7, NULL, 'قُمْ فَأَنذِرْ', 74, 'قم فانذر', 575, 29),
  (5498, 3, '74:3', 58, 230, 512, 7, NULL, 'وَرَبَّكَ فَكَبِّرْ', 74, 'وربك فكبر', 575, 29),
  (5499, 4, '74:4', 58, 230, 512, 7, NULL, 'وَثِيَابَكَ فَطَهِّرْ', 74, 'وثيابك فطهر', 575, 29),
  (5500, 5, '74:5', 58, 230, 512, 7, NULL, 'وَٱلرُّجْزَ فَٱهْجُرْ', 74, 'والرجز فاهجر', 575, 29);
INSERT INTO `verses` (`id`, `verse_number`, `verse_key`, `hizb_number`, `rub_el_hizb_number`, `ruku_number`, `manzil_number`, `sajdah_number`, `text_uthmani`, `chapter_id`, `text_imlaei_simple`, `page_number`, `juz_number`) VALUES
  (5501, 6, '74:6', 58, 230, 512, 7, NULL, 'وَلَا تَمْنُن تَسْتَكْثِرُ', 74, 'ولا تمنن تستكثر', 575, 29),
  (5502, 7, '74:7', 58, 230, 512, 7, NULL, 'وَلِرَبِّكَ فَٱصْبِرْ', 74, 'ولربك فاصبر', 575, 29),
  (5503, 8, '74:8', 58, 230, 512, 7, NULL, 'فَإِذَا نُقِرَ فِى ٱلنَّاقُورِ', 74, 'فاذا نقر في الناقور', 575, 29),
  (5504, 9, '74:9', 58, 230, 512, 7, NULL, 'فَذَٰلِكَ يَوْمَئِذٍ يَوْمٌ عَسِيرٌ', 74, 'فذلك يومئذ يوم عسير', 575, 29),
  (5505, 10, '74:10', 58, 230, 512, 7, NULL, 'عَلَى ٱلْكَـٰفِرِينَ غَيْرُ يَسِيرٍ', 74, 'على الكافرين غير يسير', 575, 29),
  (5506, 11, '74:11', 58, 230, 512, 7, NULL, 'ذَرْنِى وَمَنْ خَلَقْتُ وَحِيدًا', 74, 'ذرني ومن خلقت وحيدا', 575, 29),
  (5507, 12, '74:12', 58, 230, 512, 7, NULL, 'وَجَعَلْتُ لَهُۥ مَالًا مَّمْدُودًا', 74, 'وجعلت له مالا ممدودا', 575, 29),
  (5508, 13, '74:13', 58, 230, 512, 7, NULL, 'وَبَنِينَ شُهُودًا', 74, 'وبنين شهودا', 575, 29),
  (5509, 14, '74:14', 58, 230, 512, 7, NULL, 'وَمَهَّدتُّ لَهُۥ تَمْهِيدًا', 74, 'ومهدت له تمهيدا', 575, 29),
  (5510, 15, '74:15', 58, 230, 512, 7, NULL, 'ثُمَّ يَطْمَعُ أَنْ أَزِيدَ', 74, 'ثم يطمع ان ازيد', 575, 29),
  (5511, 16, '74:16', 58, 230, 512, 7, NULL, 'كَلَّآ ۖ إِنَّهُۥ كَانَ لِـَٔايَـٰتِنَا عَنِيدًا', 74, 'كلا انه كان لاياتنا عنيدا', 575, 29),
  (5512, 17, '74:17', 58, 230, 512, 7, NULL, 'سَأُرْهِقُهُۥ صَعُودًا', 74, 'سارهقه صعودا', 575, 29),
  (5513, 18, '74:18', 58, 230, 512, 7, NULL, 'إِنَّهُۥ فَكَّرَ وَقَدَّرَ', 74, 'انه فكر وقدر', 576, 29),
  (5514, 19, '74:19', 58, 230, 512, 7, NULL, 'فَقُتِلَ كَيْفَ قَدَّرَ', 74, 'فقتل كيف قدر', 576, 29),
  (5515, 20, '74:20', 58, 230, 512, 7, NULL, 'ثُمَّ قُتِلَ كَيْفَ قَدَّرَ', 74, 'ثم قتل كيف قدر', 576, 29),
  (5516, 21, '74:21', 58, 230, 512, 7, NULL, 'ثُمَّ نَظَرَ', 74, 'ثم نظر', 576, 29),
  (5517, 22, '74:22', 58, 230, 512, 7, NULL, 'ثُمَّ عَبَسَ وَبَسَرَ', 74, 'ثم عبس وبسر', 576, 29),
  (5518, 23, '74:23', 58, 230, 512, 7, NULL, 'ثُمَّ أَدْبَرَ وَٱسْتَكْبَرَ', 74, 'ثم ادبر واستكبر', 576, 29),
  (5519, 24, '74:24', 58, 230, 512, 7, NULL, 'فَقَالَ إِنْ هَـٰذَآ إِلَّا سِحْرٌ يُؤْثَرُ', 74, 'فقال ان هذا الا سحر يؤثر', 576, 29),
  (5520, 25, '74:25', 58, 230, 512, 7, NULL, 'إِنْ هَـٰذَآ إِلَّا قَوْلُ ٱلْبَشَرِ', 74, 'ان هذا الا قول البشر', 576, 29),
  (5521, 26, '74:26', 58, 230, 512, 7, NULL, 'سَأُصْلِيهِ سَقَرَ', 74, 'ساصليه سقر', 576, 29),
  (5522, 27, '74:27', 58, 230, 512, 7, NULL, 'وَمَآ أَدْرَىٰكَ مَا سَقَرُ', 74, 'وما ادراك ما سقر', 576, 29),
  (5523, 28, '74:28', 58, 230, 512, 7, NULL, 'لَا تُبْقِى وَلَا تَذَرُ', 74, 'لا تبقي ولا تذر', 576, 29),
  (5524, 29, '74:29', 58, 230, 512, 7, NULL, 'لَوَّاحَةٌ لِّلْبَشَرِ', 74, 'لواحة للبشر', 576, 29),
  (5525, 30, '74:30', 58, 230, 512, 7, NULL, 'عَلَيْهَا تِسْعَةَ عَشَرَ', 74, 'عليها تسعة عشر', 576, 29),
  (5526, 31, '74:31', 58, 230, 512, 7, NULL, 'وَمَا جَعَلْنَآ أَصْحَـٰبَ ٱلنَّارِ إِلَّا مَلَـٰٓئِكَةً ۙ وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةً لِّلَّذِينَ كَفَرُوا۟ لِيَسْتَيْقِنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ وَيَزْدَادَ ٱلَّذِينَ ءَامَنُوٓا۟ إِيمَـٰنًا ۙ وَلَا يَرْتَابَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ وَٱلْمُؤْمِنُونَ ۙ وَلِيَقُولَ ٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْكَـٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلًا ۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ ۚ وَمَا هِىَ إِلَّا ذِكْرَىٰ لِلْبَشَرِ', 74, 'وما جعلنا اصحاب النار الا ملائكة وما جعلنا عدتهم الا فتنة للذين كفروا ليستيقن الذين اوتوا الكتاب ويزداد الذين امنوا ايمانا ولا يرتاب الذين اوتوا الكتاب والمؤمنون وليقول الذين في قلوبهم مرض والكافرون ماذا اراد الله بهذا مثلا كذلك يضل الله من يشاء ويهدي من يشاء وما يعلم جنود ربك الا هو وما هي الا ذكرى للبشر', 576, 29),
  (5527, 32, '74:32', 58, 230, 513, 7, NULL, 'كَلَّا وَٱلْقَمَرِ', 74, 'كلا والقمر', 576, 29),
  (5528, 33, '74:33', 58, 230, 513, 7, NULL, 'وَٱلَّيْلِ إِذْ أَدْبَرَ', 74, 'والليل اذ ادبر', 576, 29),
  (5529, 34, '74:34', 58, 230, 513, 7, NULL, 'وَٱلصُّبْحِ إِذَآ أَسْفَرَ', 74, 'والصبح اذا اسفر', 576, 29),
  (5530, 35, '74:35', 58, 230, 513, 7, NULL, 'إِنَّهَا لَإِحْدَى ٱلْكُبَرِ', 74, 'انها لاحدى الكبر', 576, 29),
  (5531, 36, '74:36', 58, 230, 513, 7, NULL, 'نَذِيرًا لِّلْبَشَرِ', 74, 'نذيرا للبشر', 576, 29),
  (5532, 37, '74:37', 58, 230, 513, 7, NULL, 'لِمَن شَآءَ مِنكُمْ أَن يَتَقَدَّمَ أَوْ يَتَأَخَّرَ', 74, 'لمن شاء منكم ان يتقدم او يتاخر', 576, 29),
  (5533, 38, '74:38', 58, 230, 513, 7, NULL, 'كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ رَهِينَةٌ', 74, 'كل نفس بما كسبت رهينة', 576, 29),
  (5534, 39, '74:39', 58, 230, 513, 7, NULL, 'إِلَّآ أَصْحَـٰبَ ٱلْيَمِينِ', 74, 'الا اصحاب اليمين', 576, 29),
  (5535, 40, '74:40', 58, 230, 513, 7, NULL, 'فِى جَنَّـٰتٍ يَتَسَآءَلُونَ', 74, 'في جنات يتساءلون', 576, 29),
  (5536, 41, '74:41', 58, 230, 513, 7, NULL, 'عَنِ ٱلْمُجْرِمِينَ', 74, 'عن المجرمين', 576, 29),
  (5537, 42, '74:42', 58, 230, 513, 7, NULL, 'مَا سَلَكَكُمْ فِى سَقَرَ', 74, 'ما سلككم في سقر', 576, 29),
  (5538, 43, '74:43', 58, 230, 513, 7, NULL, 'قَالُوا۟ لَمْ نَكُ مِنَ ٱلْمُصَلِّينَ', 74, 'قالوا لم نك من المصلين', 576, 29),
  (5539, 44, '74:44', 58, 230, 513, 7, NULL, 'وَلَمْ نَكُ نُطْعِمُ ٱلْمِسْكِينَ', 74, 'ولم نك نطعم المسكين', 576, 29),
  (5540, 45, '74:45', 58, 230, 513, 7, NULL, 'وَكُنَّا نَخُوضُ مَعَ ٱلْخَآئِضِينَ', 74, 'وكنا نخوض مع الخائضين', 576, 29),
  (5541, 46, '74:46', 58, 230, 513, 7, NULL, 'وَكُنَّا نُكَذِّبُ بِيَوْمِ ٱلدِّينِ', 74, 'وكنا نكذب بيوم الدين', 576, 29),
  (5542, 47, '74:47', 58, 230, 513, 7, NULL, 'حَتَّىٰٓ أَتَىٰنَا ٱلْيَقِينُ', 74, 'حتى اتانا اليقين', 576, 29),
  (5543, 48, '74:48', 58, 230, 513, 7, NULL, 'فَمَا تَنفَعُهُمْ شَفَـٰعَةُ ٱلشَّـٰفِعِينَ', 74, 'فما تنفعهم شفاعة الشافعين', 577, 29),
  (5544, 49, '74:49', 58, 230, 513, 7, NULL, 'فَمَا لَهُمْ عَنِ ٱلتَّذْكِرَةِ مُعْرِضِينَ', 74, 'فما لهم عن التذكرة معرضين', 577, 29),
  (5545, 50, '74:50', 58, 230, 513, 7, NULL, 'كَأَنَّهُمْ حُمُرٌ مُّسْتَنفِرَةٌ', 74, 'كانهم حمر مستنفرة', 577, 29),
  (5546, 51, '74:51', 58, 230, 513, 7, NULL, 'فَرَّتْ مِن قَسْوَرَةٍۭ', 74, 'فرت من قسورة', 577, 29),
  (5547, 52, '74:52', 58, 230, 513, 7, NULL, 'بَلْ يُرِيدُ كُلُّ ٱمْرِئٍ مِّنْهُمْ أَن يُؤْتَىٰ صُحُفًا مُّنَشَّرَةً', 74, 'بل يريد كل امرئ منهم ان يؤتى صحفا منشرة', 577, 29),
  (5548, 53, '74:53', 58, 230, 513, 7, NULL, 'كَلَّا ۖ بَل لَّا يَخَافُونَ ٱلْـَٔاخِرَةَ', 74, 'كلا بل لا يخافون الاخرة', 577, 29),
  (5549, 54, '74:54', 58, 230, 513, 7, NULL, 'كَلَّآ إِنَّهُۥ تَذْكِرَةٌ', 74, 'كلا انه تذكرة', 577, 29),
  (5550, 55, '74:55', 58, 230, 513, 7, NULL, 'فَمَن شَآءَ ذَكَرَهُۥ', 74, 'فمن شاء ذكره', 577, 29),
  (5551, 56, '74:56', 58, 230, 513, 7, NULL, 'وَمَا يَذْكُرُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ هُوَ أَهْلُ ٱلتَّقْوَىٰ وَأَهْلُ ٱلْمَغْفِرَةِ', 74, 'وما يذكرون الا ان يشاء الله هو اهل التقوى واهل المغفرة', 577, 29),
  (5552, 1, '75:1', 58, 231, 514, 7, NULL, ' لَآ أُقْسِمُ بِيَوْمِ ٱلْقِيَـٰمَةِ', 75, 'لا اقسم بيوم القيامة', 577, 29),
  (5553, 2, '75:2', 58, 231, 514, 7, NULL, 'وَلَآ أُقْسِمُ بِٱلنَّفْسِ ٱللَّوَّامَةِ', 75, 'ولا اقسم بالنفس اللوامة', 577, 29),
  (5554, 3, '75:3', 58, 231, 514, 7, NULL, 'أَيَحْسَبُ ٱلْإِنسَـٰنُ أَلَّن نَّجْمَعَ عِظَامَهُۥ', 75, 'ايحسب الانسان الن نجمع عظامه', 577, 29),
  (5555, 4, '75:4', 58, 231, 514, 7, NULL, 'بَلَىٰ قَـٰدِرِينَ عَلَىٰٓ أَن نُّسَوِّىَ بَنَانَهُۥ', 75, 'بلى قادرين على ان نسوي بنانه', 577, 29),
  (5556, 5, '75:5', 58, 231, 514, 7, NULL, 'بَلْ يُرِيدُ ٱلْإِنسَـٰنُ لِيَفْجُرَ أَمَامَهُۥ', 75, 'بل يريد الانسان ليفجر امامه', 577, 29),
  (5557, 6, '75:6', 58, 231, 514, 7, NULL, 'يَسْـَٔلُ أَيَّانَ يَوْمُ ٱلْقِيَـٰمَةِ', 75, 'يسال ايان يوم القيامة', 577, 29),
  (5558, 7, '75:7', 58, 231, 514, 7, NULL, 'فَإِذَا بَرِقَ ٱلْبَصَرُ', 75, 'فاذا برق البصر', 577, 29),
  (5559, 8, '75:8', 58, 231, 514, 7, NULL, 'وَخَسَفَ ٱلْقَمَرُ', 75, 'وخسف القمر', 577, 29),
  (5560, 9, '75:9', 58, 231, 514, 7, NULL, 'وَجُمِعَ ٱلشَّمْسُ وَٱلْقَمَرُ', 75, 'وجمع الشمس والقمر', 577, 29),
  (5561, 10, '75:10', 58, 231, 514, 7, NULL, 'يَقُولُ ٱلْإِنسَـٰنُ يَوْمَئِذٍ أَيْنَ ٱلْمَفَرُّ', 75, 'يقول الانسان يومئذ اين المفر', 577, 29),
  (5562, 11, '75:11', 58, 231, 514, 7, NULL, 'كَلَّا لَا وَزَرَ', 75, 'كلا لا وزر', 577, 29),
  (5563, 12, '75:12', 58, 231, 514, 7, NULL, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمُسْتَقَرُّ', 75, 'الى ربك يومئذ المستقر', 577, 29),
  (5564, 13, '75:13', 58, 231, 514, 7, NULL, 'يُنَبَّؤُا۟ ٱلْإِنسَـٰنُ يَوْمَئِذٍۭ بِمَا قَدَّمَ وَأَخَّرَ', 75, 'ينبا الانسان يومئذ بما قدم واخر', 577, 29),
  (5565, 14, '75:14', 58, 231, 514, 7, NULL, 'بَلِ ٱلْإِنسَـٰنُ عَلَىٰ نَفْسِهِۦ بَصِيرَةٌ', 75, 'بل الانسان على نفسه بصيرة', 577, 29),
  (5566, 15, '75:15', 58, 231, 514, 7, NULL, 'وَلَوْ أَلْقَىٰ مَعَاذِيرَهُۥ', 75, 'ولو القى معاذيره', 577, 29),
  (5567, 16, '75:16', 58, 231, 514, 7, NULL, 'لَا تُحَرِّكْ بِهِۦ لِسَانَكَ لِتَعْجَلَ بِهِۦٓ', 75, 'لا تحرك به لسانك لتعجل به', 577, 29),
  (5568, 17, '75:17', 58, 231, 514, 7, NULL, 'إِنَّ عَلَيْنَا جَمْعَهُۥ وَقُرْءَانَهُۥ', 75, 'ان علينا جمعه وقرانه', 577, 29),
  (5569, 18, '75:18', 58, 231, 514, 7, NULL, 'فَإِذَا قَرَأْنَـٰهُ فَٱتَّبِعْ قُرْءَانَهُۥ', 75, 'فاذا قراناه فاتبع قرانه', 577, 29),
  (5570, 19, '75:19', 58, 231, 514, 7, NULL, 'ثُمَّ إِنَّ عَلَيْنَا بَيَانَهُۥ', 75, 'ثم ان علينا بيانه', 577, 29),
  (5571, 20, '75:20', 58, 231, 514, 7, NULL, 'كَلَّا بَلْ تُحِبُّونَ ٱلْعَاجِلَةَ', 75, 'كلا بل تحبون العاجلة', 578, 29),
  (5572, 21, '75:21', 58, 231, 514, 7, NULL, 'وَتَذَرُونَ ٱلْـَٔاخِرَةَ', 75, 'وتذرون الاخرة', 578, 29),
  (5573, 22, '75:22', 58, 231, 514, 7, NULL, 'وُجُوهٌ يَوْمَئِذٍ نَّاضِرَةٌ', 75, 'وجوه يومئذ ناضرة', 578, 29),
  (5574, 23, '75:23', 58, 231, 514, 7, NULL, 'إِلَىٰ رَبِّهَا نَاظِرَةٌ', 75, 'الى ربها ناظرة', 578, 29),
  (5575, 24, '75:24', 58, 231, 514, 7, NULL, 'وَوُجُوهٌ يَوْمَئِذٍۭ بَاسِرَةٌ', 75, 'ووجوه يومئذ باسرة', 578, 29),
  (5576, 25, '75:25', 58, 231, 514, 7, NULL, 'تَظُنُّ أَن يُفْعَلَ بِهَا فَاقِرَةٌ', 75, 'تظن ان يفعل بها فاقرة', 578, 29),
  (5577, 26, '75:26', 58, 231, 514, 7, NULL, 'كَلَّآ إِذَا بَلَغَتِ ٱلتَّرَاقِىَ', 75, 'كلا اذا بلغت التراقي', 578, 29),
  (5578, 27, '75:27', 58, 231, 514, 7, NULL, 'وَقِيلَ مَنْ ۜ رَاقٍ', 75, 'وقيل من راق', 578, 29),
  (5579, 28, '75:28', 58, 231, 514, 7, NULL, 'وَظَنَّ أَنَّهُ ٱلْفِرَاقُ', 75, 'وظن انه الفراق', 578, 29),
  (5580, 29, '75:29', 58, 231, 514, 7, NULL, 'وَٱلْتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ', 75, 'والتفت الساق بالساق', 578, 29),
  (5581, 30, '75:30', 58, 231, 514, 7, NULL, 'إِلَىٰ رَبِّكَ يَوْمَئِذٍ ٱلْمَسَاقُ', 75, 'الى ربك يومئذ المساق', 578, 29),
  (5582, 31, '75:31', 58, 231, 515, 7, NULL, 'فَلَا صَدَّقَ وَلَا صَلَّىٰ', 75, 'فلا صدق ولا صلى', 578, 29),
  (5583, 32, '75:32', 58, 231, 515, 7, NULL, 'وَلَـٰكِن كَذَّبَ وَتَوَلَّىٰ', 75, 'ولكن كذب وتولى', 578, 29),
  (5584, 33, '75:33', 58, 231, 515, 7, NULL, 'ثُمَّ ذَهَبَ إِلَىٰٓ أَهْلِهِۦ يَتَمَطَّىٰٓ', 75, 'ثم ذهب الى اهله يتمطى', 578, 29),
  (5585, 34, '75:34', 58, 231, 515, 7, NULL, 'أَوْلَىٰ لَكَ فَأَوْلَىٰ', 75, 'اولى لك فاولى', 578, 29),
  (5586, 35, '75:35', 58, 231, 515, 7, NULL, 'ثُمَّ أَوْلَىٰ لَكَ فَأَوْلَىٰٓ', 75, 'ثم اولى لك فاولى', 578, 29),
  (5587, 36, '75:36', 58, 231, 515, 7, NULL, 'أَيَحْسَبُ ٱلْإِنسَـٰنُ أَن يُتْرَكَ سُدًى', 75, 'ايحسب الانسان ان يترك سدى', 578, 29),
  (5588, 37, '75:37', 58, 231, 515, 7, NULL, 'أَلَمْ يَكُ نُطْفَةً مِّن مَّنِىٍّ يُمْنَىٰ', 75, 'الم يك نطفة من مني يمنى', 578, 29),
  (5589, 38, '75:38', 58, 231, 515, 7, NULL, 'ثُمَّ كَانَ عَلَقَةً فَخَلَقَ فَسَوَّىٰ', 75, 'ثم كان علقة فخلق فسوى', 578, 29),
  (5590, 39, '75:39', 58, 231, 515, 7, NULL, 'فَجَعَلَ مِنْهُ ٱلزَّوْجَيْنِ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', 75, 'فجعل منه الزوجين الذكر والانثى', 578, 29),
  (5591, 40, '75:40', 58, 231, 515, 7, NULL, 'أَلَيْسَ ذَٰلِكَ بِقَـٰدِرٍ عَلَىٰٓ أَن يُحْـِۧىَ ٱلْمَوْتَىٰ', 75, 'اليس ذلك بقادر على ان يحيي الموتى', 578, 29),
  (5592, 1, '76:1', 58, 231, 516, 7, NULL, ' هَلْ أَتَىٰ عَلَى ٱلْإِنسَـٰنِ حِينٌ مِّنَ ٱلدَّهْرِ لَمْ يَكُن شَيْـًٔا مَّذْكُورًا', 76, 'هل اتى على الانسان حين من الدهر لم يكن شيئا مذكورا', 578, 29),
  (5593, 2, '76:2', 58, 231, 516, 7, NULL, 'إِنَّا خَلَقْنَا ٱلْإِنسَـٰنَ مِن نُّطْفَةٍ أَمْشَاجٍ نَّبْتَلِيهِ فَجَعَلْنَـٰهُ سَمِيعًۢا بَصِيرًا', 76, 'انا خلقنا الانسان من نطفة امشاج نبتليه فجعلناه سميعا بصيرا', 578, 29),
  (5594, 3, '76:3', 58, 231, 516, 7, NULL, 'إِنَّا هَدَيْنَـٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا', 76, 'انا هديناه السبيل اما شاكرا واما كفورا', 578, 29),
  (5595, 4, '76:4', 58, 231, 516, 7, NULL, 'إِنَّآ أَعْتَدْنَا لِلْكَـٰفِرِينَ سَلَـٰسِلَا۟ وَأَغْلَـٰلًا وَسَعِيرًا', 76, 'انا اعتدنا للكافرين سلاسل واغلالا وسعيرا', 578, 29),
  (5596, 5, '76:5', 58, 231, 516, 7, NULL, 'إِنَّ ٱلْأَبْرَارَ يَشْرَبُونَ مِن كَأْسٍ كَانَ مِزَاجُهَا كَافُورًا', 76, 'ان الابرار يشربون من كاس كان مزاجها كافورا', 578, 29),
  (5597, 6, '76:6', 58, 231, 516, 7, NULL, 'عَيْنًا يَشْرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفْجِيرًا', 76, 'عينا يشرب بها عباد الله يفجرونها تفجيرا', 579, 29),
  (5598, 7, '76:7', 58, 231, 516, 7, NULL, 'يُوفُونَ بِٱلنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُۥ مُسْتَطِيرًا', 76, 'يوفون بالنذر ويخافون يوما كان شره مستطيرا', 579, 29),
  (5599, 8, '76:8', 58, 231, 516, 7, NULL, 'وَيُطْعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا', 76, 'ويطعمون الطعام على حبه مسكينا ويتيما واسيرا', 579, 29),
  (5600, 9, '76:9', 58, 231, 516, 7, NULL, 'إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ ٱللَّهِ لَا نُرِيدُ مِنكُمْ جَزَآءً وَلَا شُكُورًا', 76, 'انما نطعمكم لوجه الله لا نريد منكم جزاء ولا شكورا', 579, 29),
  (5601, 10, '76:10', 58, 231, 516, 7, NULL, 'إِنَّا نَخَافُ مِن رَّبِّنَا يَوْمًا عَبُوسًا قَمْطَرِيرًا', 76, 'انا نخاف من ربنا يوما عبوسا قمطريرا', 579, 29),
  (5602, 11, '76:11', 58, 231, 516, 7, NULL, 'فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَٰلِكَ ٱلْيَوْمِ وَلَقَّىٰهُمْ نَضْرَةً وَسُرُورًا', 76, 'فوقاهم الله شر ذلك اليوم ولقاهم نضرة وسرورا', 579, 29),
  (5603, 12, '76:12', 58, 231, 516, 7, NULL, 'وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةً وَحَرِيرًا', 76, 'وجزاهم بما صبروا جنة وحريرا', 579, 29),
  (5604, 13, '76:13', 58, 231, 516, 7, NULL, 'مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلْأَرَآئِكِ ۖ لَا يَرَوْنَ فِيهَا شَمْسًا وَلَا زَمْهَرِيرًا', 76, 'متكئين فيها على الارائك لا يرون فيها شمسا ولا زمهريرا', 579, 29),
  (5605, 14, '76:14', 58, 231, 516, 7, NULL, 'وَدَانِيَةً عَلَيْهِمْ ظِلَـٰلُهَا وَذُلِّلَتْ قُطُوفُهَا تَذْلِيلًا', 76, 'ودانية عليهم ظلالها وذللت قطوفها تذليلا', 579, 29),
  (5606, 15, '76:15', 58, 231, 516, 7, NULL, 'وَيُطَافُ عَلَيْهِم بِـَٔانِيَةٍ مِّن فِضَّةٍ وَأَكْوَابٍ كَانَتْ قَوَارِيرَا۠', 76, 'ويطاف عليهم بانية من فضة واكواب كانت قواريرا', 579, 29),
  (5607, 16, '76:16', 58, 231, 516, 7, NULL, 'قَوَارِيرَا۟ مِن فِضَّةٍ قَدَّرُوهَا تَقْدِيرًا', 76, 'قوارير من فضة قدروها تقديرا', 579, 29),
  (5608, 17, '76:17', 58, 231, 516, 7, NULL, 'وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنجَبِيلًا', 76, 'ويسقون فيها كاسا كان مزاجها زنجبيلا', 579, 29),
  (5609, 18, '76:18', 58, 231, 516, 7, NULL, 'عَيْنًا فِيهَا تُسَمَّىٰ سَلْسَبِيلًا', 76, 'عينا فيها تسمى سلسبيلا', 579, 29),
  (5610, 19, '76:19', 58, 232, 516, 7, NULL, '۞ وَيَطُوفُ عَلَيْهِمْ وِلْدَٰنٌ مُّخَلَّدُونَ إِذَا رَأَيْتَهُمْ حَسِبْتَهُمْ لُؤْلُؤًا مَّنثُورًا', 76, 'ويطوف عليهم ولدان مخلدون اذا رايتهم حسبتهم لؤلؤا منثورا', 579, 29),
  (5611, 20, '76:20', 58, 232, 516, 7, NULL, 'وَإِذَا رَأَيْتَ ثَمَّ رَأَيْتَ نَعِيمًا وَمُلْكًا كَبِيرًا', 76, 'واذا رايت ثم رايت نعيما وملكا كبيرا', 579, 29),
  (5612, 21, '76:21', 58, 232, 516, 7, NULL, 'عَـٰلِيَهُمْ ثِيَابُ سُندُسٍ خُضْرٌ وَإِسْتَبْرَقٌ ۖ وَحُلُّوٓا۟ أَسَاوِرَ مِن فِضَّةٍ وَسَقَىٰهُمْ رَبُّهُمْ شَرَابًا طَهُورًا', 76, 'عاليهم ثياب سندس خضر واستبرق وحلوا اساور من فضة وسقاهم ربهم شرابا طهورا', 579, 29),
  (5613, 22, '76:22', 58, 232, 516, 7, NULL, 'إِنَّ هَـٰذَا كَانَ لَكُمْ جَزَآءً وَكَانَ سَعْيُكُم مَّشْكُورًا', 76, 'ان هذا كان لكم جزاء وكان سعيكم مشكورا', 579, 29),
  (5614, 23, '76:23', 58, 232, 517, 7, NULL, 'إِنَّا نَحْنُ نَزَّلْنَا عَلَيْكَ ٱلْقُرْءَانَ تَنزِيلًا', 76, 'انا نحن نزلنا عليك القران تنزيلا', 579, 29),
  (5615, 24, '76:24', 58, 232, 517, 7, NULL, 'فَٱصْبِرْ لِحُكْمِ رَبِّكَ وَلَا تُطِعْ مِنْهُمْ ءَاثِمًا أَوْ كَفُورًا', 76, 'فاصبر لحكم ربك ولا تطع منهم اثما او كفورا', 579, 29),
  (5616, 25, '76:25', 58, 232, 517, 7, NULL, 'وَٱذْكُرِ ٱسْمَ رَبِّكَ بُكْرَةً وَأَصِيلًا', 76, 'واذكر اسم ربك بكرة واصيلا', 579, 29),
  (5617, 26, '76:26', 58, 232, 517, 7, NULL, 'وَمِنَ ٱلَّيْلِ فَٱسْجُدْ لَهُۥ وَسَبِّحْهُ لَيْلًا طَوِيلًا', 76, 'ومن الليل فاسجد له وسبحه ليلا طويلا', 580, 29),
  (5618, 27, '76:27', 58, 232, 517, 7, NULL, 'إِنَّ هَـٰٓؤُلَآءِ يُحِبُّونَ ٱلْعَاجِلَةَ وَيَذَرُونَ وَرَآءَهُمْ يَوْمًا ثَقِيلًا', 76, 'ان هؤلاء يحبون العاجلة ويذرون وراءهم يوما ثقيلا', 580, 29),
  (5619, 28, '76:28', 58, 232, 517, 7, NULL, 'نَّحْنُ خَلَقْنَـٰهُمْ وَشَدَدْنَآ أَسْرَهُمْ ۖ وَإِذَا شِئْنَا بَدَّلْنَآ أَمْثَـٰلَهُمْ تَبْدِيلًا', 76, 'نحن خلقناهم وشددنا اسرهم واذا شئنا بدلنا امثالهم تبديلا', 580, 29),
  (5620, 29, '76:29', 58, 232, 517, 7, NULL, 'إِنَّ هَـٰذِهِۦ تَذْكِرَةٌ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا', 76, 'ان هذه تذكرة فمن شاء اتخذ الى ربه سبيلا', 580, 29),
  (5621, 30, '76:30', 58, 232, 517, 7, NULL, 'وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ ۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا', 76, 'وما تشاءون الا ان يشاء الله ان الله كان عليما حكيما', 580, 29),
  (5622, 31, '76:31', 58, 232, 517, 7, NULL, 'يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ ۚ وَٱلظَّـٰلِمِينَ أَعَدَّ لَهُمْ عَذَابًا أَلِيمًۢا', 76, 'يدخل من يشاء في رحمته والظالمين اعد لهم عذابا اليما', 580, 29),
  (5623, 1, '77:1', 58, 232, 518, 7, NULL, ' وَٱلْمُرْسَلَـٰتِ عُرْفًا', 77, 'والمرسلات عرفا', 580, 29),
  (5624, 2, '77:2', 58, 232, 518, 7, NULL, 'فَٱلْعَـٰصِفَـٰتِ عَصْفًا', 77, 'فالعاصفات عصفا', 580, 29),
  (5625, 3, '77:3', 58, 232, 518, 7, NULL, 'وَٱلنَّـٰشِرَٰتِ نَشْرًا', 77, 'والناشرات نشرا', 580, 29),
  (5626, 4, '77:4', 58, 232, 518, 7, NULL, 'فَٱلْفَـٰرِقَـٰتِ فَرْقًا', 77, 'فالفارقات فرقا', 580, 29),
  (5627, 5, '77:5', 58, 232, 518, 7, NULL, 'فَٱلْمُلْقِيَـٰتِ ذِكْرًا', 77, 'فالملقيات ذكرا', 580, 29),
  (5628, 6, '77:6', 58, 232, 518, 7, NULL, 'عُذْرًا أَوْ نُذْرًا', 77, 'عذرا او نذرا', 580, 29),
  (5629, 7, '77:7', 58, 232, 518, 7, NULL, 'إِنَّمَا تُوعَدُونَ لَوَٰقِعٌ', 77, 'انما توعدون لواقع', 580, 29),
  (5630, 8, '77:8', 58, 232, 518, 7, NULL, 'فَإِذَا ٱلنُّجُومُ طُمِسَتْ', 77, 'فاذا النجوم طمست', 580, 29),
  (5631, 9, '77:9', 58, 232, 518, 7, NULL, 'وَإِذَا ٱلسَّمَآءُ فُرِجَتْ', 77, 'واذا السماء فرجت', 580, 29),
  (5632, 10, '77:10', 58, 232, 518, 7, NULL, 'وَإِذَا ٱلْجِبَالُ نُسِفَتْ', 77, 'واذا الجبال نسفت', 580, 29),
  (5633, 11, '77:11', 58, 232, 518, 7, NULL, 'وَإِذَا ٱلرُّسُلُ أُقِّتَتْ', 77, 'واذا الرسل اقتت', 580, 29),
  (5634, 12, '77:12', 58, 232, 518, 7, NULL, 'لِأَىِّ يَوْمٍ أُجِّلَتْ', 77, 'لاي يوم اجلت', 580, 29),
  (5635, 13, '77:13', 58, 232, 518, 7, NULL, 'لِيَوْمِ ٱلْفَصْلِ', 77, 'ليوم الفصل', 580, 29),
  (5636, 14, '77:14', 58, 232, 518, 7, NULL, 'وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلْفَصْلِ', 77, 'وما ادراك ما يوم الفصل', 580, 29),
  (5637, 15, '77:15', 58, 232, 518, 7, NULL, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 77, 'ويل يومئذ للمكذبين', 580, 29),
  (5638, 16, '77:16', 58, 232, 518, 7, NULL, 'أَلَمْ نُهْلِكِ ٱلْأَوَّلِينَ', 77, 'الم نهلك الاولين', 580, 29),
  (5639, 17, '77:17', 58, 232, 518, 7, NULL, 'ثُمَّ نُتْبِعُهُمُ ٱلْـَٔاخِرِينَ', 77, 'ثم نتبعهم الاخرين', 580, 29),
  (5640, 18, '77:18', 58, 232, 518, 7, NULL, 'كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ', 77, 'كذلك نفعل بالمجرمين', 580, 29),
  (5641, 19, '77:19', 58, 232, 518, 7, NULL, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 77, 'ويل يومئذ للمكذبين', 580, 29),
  (5642, 20, '77:20', 58, 232, 518, 7, NULL, 'أَلَمْ نَخْلُقكُّم مِّن مَّآءٍ مَّهِينٍ', 77, 'الم نخلقكم من ماء مهين', 581, 29),
  (5643, 21, '77:21', 58, 232, 518, 7, NULL, 'فَجَعَلْنَـٰهُ فِى قَرَارٍ مَّكِينٍ', 77, 'فجعلناه في قرار مكين', 581, 29),
  (5644, 22, '77:22', 58, 232, 518, 7, NULL, 'إِلَىٰ قَدَرٍ مَّعْلُومٍ', 77, 'الى قدر معلوم', 581, 29),
  (5645, 23, '77:23', 58, 232, 518, 7, NULL, 'فَقَدَرْنَا فَنِعْمَ ٱلْقَـٰدِرُونَ', 77, 'فقدرنا فنعم القادرون', 581, 29),
  (5646, 24, '77:24', 58, 232, 518, 7, NULL, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 77, 'ويل يومئذ للمكذبين', 581, 29),
  (5647, 25, '77:25', 58, 232, 518, 7, NULL, 'أَلَمْ نَجْعَلِ ٱلْأَرْضَ كِفَاتًا', 77, 'الم نجعل الارض كفاتا', 581, 29),
  (5648, 26, '77:26', 58, 232, 518, 7, NULL, 'أَحْيَآءً وَأَمْوَٰتًا', 77, 'احياء وامواتا', 581, 29),
  (5649, 27, '77:27', 58, 232, 518, 7, NULL, 'وَجَعَلْنَا فِيهَا رَوَٰسِىَ شَـٰمِخَـٰتٍ وَأَسْقَيْنَـٰكُم مَّآءً فُرَاتًا', 77, 'وجعلنا فيها رواسي شامخات واسقيناكم ماء فراتا', 581, 29),
  (5650, 28, '77:28', 58, 232, 518, 7, NULL, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 77, 'ويل يومئذ للمكذبين', 581, 29),
  (5651, 29, '77:29', 58, 232, 518, 7, NULL, 'ٱنطَلِقُوٓا۟ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ', 77, 'انطلقوا الى ما كنتم به تكذبون', 581, 29),
  (5652, 30, '77:30', 58, 232, 518, 7, NULL, 'ٱنطَلِقُوٓا۟ إِلَىٰ ظِلٍّ ذِى ثَلَـٰثِ شُعَبٍ', 77, 'انطلقوا الى ظل ذي ثلاث شعب', 581, 29),
  (5653, 31, '77:31', 58, 232, 518, 7, NULL, 'لَّا ظَلِيلٍ وَلَا يُغْنِى مِنَ ٱللَّهَبِ', 77, 'لا ظليل ولا يغني من اللهب', 581, 29),
  (5654, 32, '77:32', 58, 232, 518, 7, NULL, 'إِنَّهَا تَرْمِى بِشَرَرٍ كَٱلْقَصْرِ', 77, 'انها ترمي بشرر كالقصر', 581, 29),
  (5655, 33, '77:33', 58, 232, 518, 7, NULL, 'كَأَنَّهُۥ جِمَـٰلَتٌ صُفْرٌ', 77, 'كانه جمالت صفر', 581, 29),
  (5656, 34, '77:34', 58, 232, 518, 7, NULL, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 77, 'ويل يومئذ للمكذبين', 581, 29),
  (5657, 35, '77:35', 58, 232, 518, 7, NULL, 'هَـٰذَا يَوْمُ لَا يَنطِقُونَ', 77, 'هذا يوم لا ينطقون', 581, 29),
  (5658, 36, '77:36', 58, 232, 518, 7, NULL, 'وَلَا يُؤْذَنُ لَهُمْ فَيَعْتَذِرُونَ', 77, 'ولا يؤذن لهم فيعتذرون', 581, 29),
  (5659, 37, '77:37', 58, 232, 518, 7, NULL, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 77, 'ويل يومئذ للمكذبين', 581, 29),
  (5660, 38, '77:38', 58, 232, 518, 7, NULL, 'هَـٰذَا يَوْمُ ٱلْفَصْلِ ۖ جَمَعْنَـٰكُمْ وَٱلْأَوَّلِينَ', 77, 'هذا يوم الفصل جمعناكم والاولين', 581, 29),
  (5661, 39, '77:39', 58, 232, 518, 7, NULL, 'فَإِن كَانَ لَكُمْ كَيْدٌ فَكِيدُونِ', 77, 'فان كان لكم كيد فكيدون', 581, 29),
  (5662, 40, '77:40', 58, 232, 518, 7, NULL, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 77, 'ويل يومئذ للمكذبين', 581, 29),
  (5663, 41, '77:41', 58, 232, 519, 7, NULL, 'إِنَّ ٱلْمُتَّقِينَ فِى ظِلَـٰلٍ وَعُيُونٍ', 77, 'ان المتقين في ظلال وعيون', 581, 29),
  (5664, 42, '77:42', 58, 232, 519, 7, NULL, 'وَفَوَٰكِهَ مِمَّا يَشْتَهُونَ', 77, 'وفواكه مما يشتهون', 581, 29),
  (5665, 43, '77:43', 58, 232, 519, 7, NULL, 'كُلُوا۟ وَٱشْرَبُوا۟ هَنِيٓـًٔۢا بِمَا كُنتُمْ تَعْمَلُونَ', 77, 'كلوا واشربوا هنيئا بما كنتم تعملون', 581, 29),
  (5666, 44, '77:44', 58, 232, 519, 7, NULL, 'إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ', 77, 'انا كذلك نجزي المحسنين', 581, 29),
  (5667, 45, '77:45', 58, 232, 519, 7, NULL, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 77, 'ويل يومئذ للمكذبين', 581, 29),
  (5668, 46, '77:46', 58, 232, 519, 7, NULL, 'كُلُوا۟ وَتَمَتَّعُوا۟ قَلِيلًا إِنَّكُم مُّجْرِمُونَ', 77, 'كلوا وتمتعوا قليلا انكم مجرمون', 581, 29),
  (5669, 47, '77:47', 58, 232, 519, 7, NULL, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 77, 'ويل يومئذ للمكذبين', 581, 29),
  (5670, 48, '77:48', 58, 232, 519, 7, NULL, 'وَإِذَا قِيلَ لَهُمُ ٱرْكَعُوا۟ لَا يَرْكَعُونَ', 77, 'واذا قيل لهم اركعوا لا يركعون', 581, 29),
  (5671, 49, '77:49', 58, 232, 519, 7, NULL, 'وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ', 77, 'ويل يومئذ للمكذبين', 581, 29),
  (5672, 50, '77:50', 58, 232, 519, 7, NULL, 'فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ', 77, 'فباي حديث بعده يؤمنون', 581, 29),
  (5673, 1, '78:1', 59, 233, 520, 7, NULL, ' عَمَّ يَتَسَآءَلُونَ', 78, 'عم يتساءلون', 582, 30),
  (5674, 2, '78:2', 59, 233, 520, 7, NULL, 'عَنِ ٱلنَّبَإِ ٱلْعَظِيمِ', 78, 'عن النبا العظيم', 582, 30),
  (5675, 3, '78:3', 59, 233, 520, 7, NULL, 'ٱلَّذِى هُمْ فِيهِ مُخْتَلِفُونَ', 78, 'الذي هم فيه مختلفون', 582, 30),
  (5676, 4, '78:4', 59, 233, 520, 7, NULL, 'كَلَّا سَيَعْلَمُونَ', 78, 'كلا سيعلمون', 582, 30),
  (5677, 5, '78:5', 59, 233, 520, 7, NULL, 'ثُمَّ كَلَّا سَيَعْلَمُونَ', 78, 'ثم كلا سيعلمون', 582, 30),
  (5678, 6, '78:6', 59, 233, 520, 7, NULL, 'أَلَمْ نَجْعَلِ ٱلْأَرْضَ مِهَـٰدًا', 78, 'الم نجعل الارض مهادا', 582, 30),
  (5679, 7, '78:7', 59, 233, 520, 7, NULL, 'وَٱلْجِبَالَ أَوْتَادًا', 78, 'والجبال اوتادا', 582, 30),
  (5680, 8, '78:8', 59, 233, 520, 7, NULL, 'وَخَلَقْنَـٰكُمْ أَزْوَٰجًا', 78, 'وخلقناكم ازواجا', 582, 30),
  (5681, 9, '78:9', 59, 233, 520, 7, NULL, 'وَجَعَلْنَا نَوْمَكُمْ سُبَاتًا', 78, 'وجعلنا نومكم سباتا', 582, 30),
  (5682, 10, '78:10', 59, 233, 520, 7, NULL, 'وَجَعَلْنَا ٱلَّيْلَ لِبَاسًا', 78, 'وجعلنا الليل لباسا', 582, 30),
  (5683, 11, '78:11', 59, 233, 520, 7, NULL, 'وَجَعَلْنَا ٱلنَّهَارَ مَعَاشًا', 78, 'وجعلنا النهار معاشا', 582, 30),
  (5684, 12, '78:12', 59, 233, 520, 7, NULL, 'وَبَنَيْنَا فَوْقَكُمْ سَبْعًا شِدَادًا', 78, 'وبنينا فوقكم سبعا شدادا', 582, 30),
  (5685, 13, '78:13', 59, 233, 520, 7, NULL, 'وَجَعَلْنَا سِرَاجًا وَهَّاجًا', 78, 'وجعلنا سراجا وهاجا', 582, 30),
  (5686, 14, '78:14', 59, 233, 520, 7, NULL, 'وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءً ثَجَّاجًا', 78, 'وانزلنا من المعصرات ماء ثجاجا', 582, 30),
  (5687, 15, '78:15', 59, 233, 520, 7, NULL, 'لِّنُخْرِجَ بِهِۦ حَبًّا وَنَبَاتًا', 78, 'لنخرج به حبا ونباتا', 582, 30),
  (5688, 16, '78:16', 59, 233, 520, 7, NULL, 'وَجَنَّـٰتٍ أَلْفَافًا', 78, 'وجنات الفافا', 582, 30),
  (5689, 17, '78:17', 59, 233, 520, 7, NULL, 'إِنَّ يَوْمَ ٱلْفَصْلِ كَانَ مِيقَـٰتًا', 78, 'ان يوم الفصل كان ميقاتا', 582, 30),
  (5690, 18, '78:18', 59, 233, 520, 7, NULL, 'يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًا', 78, 'يوم ينفخ في الصور فتاتون افواجا', 582, 30),
  (5691, 19, '78:19', 59, 233, 520, 7, NULL, 'وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًا', 78, 'وفتحت السماء فكانت ابوابا', 582, 30),
  (5692, 20, '78:20', 59, 233, 520, 7, NULL, 'وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا', 78, 'وسيرت الجبال فكانت سرابا', 582, 30),
  (5693, 21, '78:21', 59, 233, 520, 7, NULL, 'إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًا', 78, 'ان جهنم كانت مرصادا', 582, 30),
  (5694, 22, '78:22', 59, 233, 520, 7, NULL, 'لِّلطَّـٰغِينَ مَـَٔابًا', 78, 'للطاغين مابا', 582, 30),
  (5695, 23, '78:23', 59, 233, 520, 7, NULL, 'لَّـٰبِثِينَ فِيهَآ أَحْقَابًا', 78, 'لابثين فيها احقابا', 582, 30),
  (5696, 24, '78:24', 59, 233, 520, 7, NULL, 'لَّا يَذُوقُونَ فِيهَا بَرْدًا وَلَا شَرَابًا', 78, 'لا يذوقون فيها بردا ولا شرابا', 582, 30),
  (5697, 25, '78:25', 59, 233, 520, 7, NULL, 'إِلَّا حَمِيمًا وَغَسَّاقًا', 78, 'الا حميما وغساقا', 582, 30),
  (5698, 26, '78:26', 59, 233, 520, 7, NULL, 'جَزَآءً وِفَاقًا', 78, 'جزاء وفاقا', 582, 30),
  (5699, 27, '78:27', 59, 233, 520, 7, NULL, 'إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًا', 78, 'انهم كانوا لا يرجون حسابا', 582, 30),
  (5700, 28, '78:28', 59, 233, 520, 7, NULL, 'وَكَذَّبُوا۟ بِـَٔايَـٰتِنَا كِذَّابًا', 78, 'وكذبوا باياتنا كذابا', 582, 30),
  (5701, 29, '78:29', 59, 233, 520, 7, NULL, 'وَكُلَّ شَىْءٍ أَحْصَيْنَـٰهُ كِتَـٰبًا', 78, 'وكل شيء احصيناه كتابا', 582, 30),
  (5702, 30, '78:30', 59, 233, 520, 7, NULL, 'فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا', 78, 'فذوقوا فلن نزيدكم الا عذابا', 582, 30),
  (5703, 31, '78:31', 59, 233, 521, 7, NULL, 'إِنَّ لِلْمُتَّقِينَ مَفَازًا', 78, 'ان للمتقين مفازا', 583, 30),
  (5704, 32, '78:32', 59, 233, 521, 7, NULL, 'حَدَآئِقَ وَأَعْنَـٰبًا', 78, 'حدائق واعنابا', 583, 30),
  (5705, 33, '78:33', 59, 233, 521, 7, NULL, 'وَكَوَاعِبَ أَتْرَابًا', 78, 'وكواعب اترابا', 583, 30),
  (5706, 34, '78:34', 59, 233, 521, 7, NULL, 'وَكَأْسًا دِهَاقًا', 78, 'وكاسا دهاقا', 583, 30),
  (5707, 35, '78:35', 59, 233, 521, 7, NULL, 'لَّا يَسْمَعُونَ فِيهَا لَغْوًا وَلَا كِذَّٰبًا', 78, 'لا يسمعون فيها لغوا ولا كذابا', 583, 30),
  (5708, 36, '78:36', 59, 233, 521, 7, NULL, 'جَزَآءً مِّن رَّبِّكَ عَطَآءً حِسَابًا', 78, 'جزاء من ربك عطاء حسابا', 583, 30),
  (5709, 37, '78:37', 59, 233, 521, 7, NULL, 'رَّبِّ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَـٰنِ ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًا', 78, 'رب السماوات والارض وما بينهما الرحمن لا يملكون منه خطابا', 583, 30),
  (5710, 38, '78:38', 59, 233, 521, 7, NULL, 'يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَـٰٓئِكَةُ صَفًّا ۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَـٰنُ وَقَالَ صَوَابًا', 78, 'يوم يقوم الروح والملائكة صفا لا يتكلمون الا من اذن له الرحمن وقال صوابا', 583, 30),
  (5711, 39, '78:39', 59, 233, 521, 7, NULL, 'ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا', 78, 'ذلك اليوم الحق فمن شاء اتخذ الى ربه مابا', 583, 30),
  (5712, 40, '78:40', 59, 233, 521, 7, NULL, 'إِنَّآ أَنذَرْنَـٰكُمْ عَذَابًا قَرِيبًا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَـٰلَيْتَنِى كُنتُ تُرَٰبًۢا', 78, 'انا انذرناكم عذابا قريبا يوم ينظر المرء ما قدمت يداه ويقول الكافر يا ليتني كنت ترابا', 583, 30),
  (5713, 1, '79:1', 59, 233, 522, 7, NULL, ' وَٱلنَّـٰزِعَـٰتِ غَرْقًا', 79, 'والنازعات غرقا', 583, 30),
  (5714, 2, '79:2', 59, 233, 522, 7, NULL, 'وَٱلنَّـٰشِطَـٰتِ نَشْطًا', 79, 'والناشطات نشطا', 583, 30),
  (5715, 3, '79:3', 59, 233, 522, 7, NULL, 'وَٱلسَّـٰبِحَـٰتِ سَبْحًا', 79, 'والسابحات سبحا', 583, 30),
  (5716, 4, '79:4', 59, 233, 522, 7, NULL, 'فَٱلسَّـٰبِقَـٰتِ سَبْقًا', 79, 'فالسابقات سبقا', 583, 30),
  (5717, 5, '79:5', 59, 233, 522, 7, NULL, 'فَٱلْمُدَبِّرَٰتِ أَمْرًا', 79, 'فالمدبرات امرا', 583, 30),
  (5718, 6, '79:6', 59, 233, 522, 7, NULL, 'يَوْمَ تَرْجُفُ ٱلرَّاجِفَةُ', 79, 'يوم ترجف الراجفة', 583, 30),
  (5719, 7, '79:7', 59, 233, 522, 7, NULL, 'تَتْبَعُهَا ٱلرَّادِفَةُ', 79, 'تتبعها الرادفة', 583, 30),
  (5720, 8, '79:8', 59, 233, 522, 7, NULL, 'قُلُوبٌ يَوْمَئِذٍ وَاجِفَةٌ', 79, 'قلوب يومئذ واجفة', 583, 30),
  (5721, 9, '79:9', 59, 233, 522, 7, NULL, 'أَبْصَـٰرُهَا خَـٰشِعَةٌ', 79, 'ابصارها خاشعة', 583, 30),
  (5722, 10, '79:10', 59, 233, 522, 7, NULL, 'يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِى ٱلْحَافِرَةِ', 79, 'يقولون اانا لمردودون في الحافرة', 583, 30),
  (5723, 11, '79:11', 59, 233, 522, 7, NULL, 'أَءِذَا كُنَّا عِظَـٰمًا نَّخِرَةً', 79, 'ااذا كنا عظاما نخرة', 583, 30),
  (5724, 12, '79:12', 59, 233, 522, 7, NULL, 'قَالُوا۟ تِلْكَ إِذًا كَرَّةٌ خَاسِرَةٌ', 79, 'قالوا تلك اذا كرة خاسرة', 583, 30),
  (5725, 13, '79:13', 59, 233, 522, 7, NULL, 'فَإِنَّمَا هِىَ زَجْرَةٌ وَٰحِدَةٌ', 79, 'فانما هي زجرة واحدة', 583, 30),
  (5726, 14, '79:14', 59, 233, 522, 7, NULL, 'فَإِذَا هُم بِٱلسَّاهِرَةِ', 79, 'فاذا هم بالساهرة', 583, 30),
  (5727, 15, '79:15', 59, 233, 522, 7, NULL, 'هَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ', 79, 'هل اتاك حديث موسى', 583, 30),
  (5728, 16, '79:16', 59, 233, 522, 7, NULL, 'إِذْ نَادَىٰهُ رَبُّهُۥ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى', 79, 'اذ ناداه ربه بالواد المقدس طوى', 584, 30),
  (5729, 17, '79:17', 59, 233, 522, 7, NULL, 'ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ', 79, 'اذهب الى فرعون انه طغى', 584, 30),
  (5730, 18, '79:18', 59, 233, 522, 7, NULL, 'فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ', 79, 'فقل هل لك الى ان تزكى', 584, 30),
  (5731, 19, '79:19', 59, 233, 522, 7, NULL, 'وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ', 79, 'واهديك الى ربك فتخشى', 584, 30),
  (5732, 20, '79:20', 59, 233, 522, 7, NULL, 'فَأَرَىٰهُ ٱلْـَٔايَةَ ٱلْكُبْرَىٰ', 79, 'فاراه الاية الكبرى', 584, 30),
  (5733, 21, '79:21', 59, 233, 522, 7, NULL, 'فَكَذَّبَ وَعَصَىٰ', 79, 'فكذب وعصى', 584, 30),
  (5734, 22, '79:22', 59, 233, 522, 7, NULL, 'ثُمَّ أَدْبَرَ يَسْعَىٰ', 79, 'ثم ادبر يسعى', 584, 30),
  (5735, 23, '79:23', 59, 233, 522, 7, NULL, 'فَحَشَرَ فَنَادَىٰ', 79, 'فحشر فنادى', 584, 30),
  (5736, 24, '79:24', 59, 233, 522, 7, NULL, 'فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ', 79, 'فقال انا ربكم الاعلى', 584, 30),
  (5737, 25, '79:25', 59, 233, 522, 7, NULL, 'فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْـَٔاخِرَةِ وَٱلْأُولَىٰٓ', 79, 'فاخذه الله نكال الاخرة والاولى', 584, 30),
  (5738, 26, '79:26', 59, 233, 522, 7, NULL, 'إِنَّ فِى ذَٰلِكَ لَعِبْرَةً لِّمَن يَخْشَىٰٓ', 79, 'ان في ذلك لعبرة لمن يخشى', 584, 30),
  (5739, 27, '79:27', 59, 233, 523, 7, NULL, 'ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ ۚ بَنَىٰهَا', 79, 'اانتم اشد خلقا ام السماء بناها', 584, 30),
  (5740, 28, '79:28', 59, 233, 523, 7, NULL, 'رَفَعَ سَمْكَهَا فَسَوَّىٰهَا', 79, 'رفع سمكها فسواها', 584, 30),
  (5741, 29, '79:29', 59, 233, 523, 7, NULL, 'وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا', 79, 'واغطش ليلها واخرج ضحاها', 584, 30),
  (5742, 30, '79:30', 59, 233, 523, 7, NULL, 'وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ', 79, 'والارض بعد ذلك دحاها', 584, 30),
  (5743, 31, '79:31', 59, 233, 523, 7, NULL, 'أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا', 79, 'اخرج منها ماءها ومرعاها', 584, 30),
  (5744, 32, '79:32', 59, 233, 523, 7, NULL, 'وَٱلْجِبَالَ أَرْسَىٰهَا', 79, 'والجبال ارساها', 584, 30),
  (5745, 33, '79:33', 59, 233, 523, 7, NULL, 'مَتَـٰعًا لَّكُمْ وَلِأَنْعَـٰمِكُمْ', 79, 'متاعا لكم ولانعامكم', 584, 30),
  (5746, 34, '79:34', 59, 233, 523, 7, NULL, 'فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ', 79, 'فاذا جاءت الطامة الكبرى', 584, 30),
  (5747, 35, '79:35', 59, 233, 523, 7, NULL, 'يَوْمَ يَتَذَكَّرُ ٱلْإِنسَـٰنُ مَا سَعَىٰ', 79, 'يوم يتذكر الانسان ما سعى', 584, 30),
  (5748, 36, '79:36', 59, 233, 523, 7, NULL, 'وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ', 79, 'وبرزت الجحيم لمن يرى', 584, 30),
  (5749, 37, '79:37', 59, 233, 523, 7, NULL, 'فَأَمَّا مَن طَغَىٰ', 79, 'فاما من طغى', 584, 30),
  (5750, 38, '79:38', 59, 233, 523, 7, NULL, 'وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', 79, 'واثر الحياة الدنيا', 584, 30),
  (5751, 39, '79:39', 59, 233, 523, 7, NULL, 'فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ', 79, 'فان الجحيم هي الماوى', 584, 30),
  (5752, 40, '79:40', 59, 233, 523, 7, NULL, 'وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ', 79, 'واما من خاف مقام ربه ونهى النفس عن الهوى', 584, 30),
  (5753, 41, '79:41', 59, 233, 523, 7, NULL, 'فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ', 79, 'فان الجنة هي الماوى', 584, 30),
  (5754, 42, '79:42', 59, 233, 523, 7, NULL, 'يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا', 79, 'يسالونك عن الساعة ايان مرساها', 584, 30),
  (5755, 43, '79:43', 59, 233, 523, 7, NULL, 'فِيمَ أَنتَ مِن ذِكْرَىٰهَآ', 79, 'فيم انت من ذكراها', 584, 30),
  (5756, 44, '79:44', 59, 233, 523, 7, NULL, 'إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ', 79, 'الى ربك منتهاها', 584, 30),
  (5757, 45, '79:45', 59, 233, 523, 7, NULL, 'إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا', 79, 'انما انت منذر من يخشاها', 584, 30),
  (5758, 46, '79:46', 59, 233, 523, 7, NULL, 'كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا', 79, 'كانهم يوم يرونها لم يلبثوا الا عشية او ضحاها', 584, 30),
  (5759, 1, '80:1', 59, 234, 524, 7, NULL, ' عَبَسَ وَتَوَلَّىٰٓ', 80, 'عبس وتولى', 585, 30),
  (5760, 2, '80:2', 59, 234, 524, 7, NULL, 'أَن جَآءَهُ ٱلْأَعْمَىٰ', 80, 'ان جاءه الاعمى', 585, 30),
  (5761, 3, '80:3', 59, 234, 524, 7, NULL, 'وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ', 80, 'وما يدريك لعله يزكى', 585, 30),
  (5762, 4, '80:4', 59, 234, 524, 7, NULL, 'أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ', 80, 'او يذكر فتنفعه الذكرى', 585, 30),
  (5763, 5, '80:5', 59, 234, 524, 7, NULL, 'أَمَّا مَنِ ٱسْتَغْنَىٰ', 80, 'اما من استغنى', 585, 30),
