  (5765, 7, '80:7', 59, 234, 524, 7, NULL, 'وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ', 80, 'وما عليك الا يزكى', 585, 30),
  (5766, 8, '80:8', 59, 234, 524, 7, NULL, 'وَأَمَّا مَن جَآءَكَ يَسْعَىٰ', 80, 'واما من جاءك يسعى', 585, 30),
  (5767, 9, '80:9', 59, 234, 524, 7, NULL, 'وَهُوَ يَخْشَىٰ', 80, 'وهو يخشى', 585, 30),
  (5768, 10, '80:10', 59, 234, 524, 7, NULL, 'فَأَنتَ عَنْهُ تَلَهَّىٰ', 80, 'فانت عنه تلهى', 585, 30),
  (5769, 11, '80:11', 59, 234, 524, 7, NULL, 'كَلَّآ إِنَّهَا تَذْكِرَةٌ', 80, 'كلا انها تذكرة', 585, 30),
  (5770, 12, '80:12', 59, 234, 524, 7, NULL, 'فَمَن شَآءَ ذَكَرَهُۥ', 80, 'فمن شاء ذكره', 585, 30),
  (5771, 13, '80:13', 59, 234, 524, 7, NULL, 'فِى صُحُفٍ مُّكَرَّمَةٍ', 80, 'في صحف مكرمة', 585, 30),
  (5772, 14, '80:14', 59, 234, 524, 7, NULL, 'مَّرْفُوعَةٍ مُّطَهَّرَةٍۭ', 80, 'مرفوعة مطهرة', 585, 30),
  (5773, 15, '80:15', 59, 234, 524, 7, NULL, 'بِأَيْدِى سَفَرَةٍ', 80, 'بايدي سفرة', 585, 30),
  (5774, 16, '80:16', 59, 234, 524, 7, NULL, 'كِرَامٍۭ بَرَرَةٍ', 80, 'كرام بررة', 585, 30),
  (5775, 17, '80:17', 59, 234, 524, 7, NULL, 'قُتِلَ ٱلْإِنسَـٰنُ مَآ أَكْفَرَهُۥ', 80, 'قتل الانسان ما اكفره', 585, 30),
  (5776, 18, '80:18', 59, 234, 524, 7, NULL, 'مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ', 80, 'من اي شيء خلقه', 585, 30),
