  (5778, 20, '80:20', 59, 234, 524, 7, NULL, 'ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ', 80, 'ثم السبيل يسره', 585, 30),
  (5779, 21, '80:21', 59, 234, 524, 7, NULL, 'ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ', 80, 'ثم اماته فاقبره', 585, 30),
  (5780, 22, '80:22', 59, 234, 524, 7, NULL, 'ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ', 80, 'ثم اذا شاء انشره', 585, 30),
  (5781, 23, '80:23', 59, 234, 524, 7, NULL, 'كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ', 80, 'كلا لما يقض ما امره', 585, 30),
  (5782, 24, '80:24', 59, 234, 524, 7, NULL, 'فَلْيَنظُرِ ٱلْإِنسَـٰنُ إِلَىٰ طَعَامِهِۦٓ', 80, 'فلينظر الانسان الى طعامه', 585, 30),
  (5783, 25, '80:25', 59, 234, 524, 7, NULL, 'أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّا', 80, 'انا صببنا الماء صبا', 585, 30),
