  (5830, 1, '82:1', 59, 235, 526, 7, NULL, ' إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ', 82, 'اذا السماء انفطرت', 587, 30),
  (5831, 2, '82:2', 59, 235, 526, 7, NULL, 'وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ', 82, 'واذا الكواكب انتثرت', 587, 30),
