  (5849, 1, '83:1', 59, 235, 527, 7, NULL, ' وَيْلٌ لِّلْمُطَفِّفِينَ', 83, 'ويل للمطففين', 587, 30),
  (5850, 2, '83:2', 59, 235, 527, 7, NULL, 'ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ', 83, 'الذين اذا اكتالوا على الناس يستوفون', 587, 30),
