  (5865, 17, '83:17', 59, 235, 527, 7, NULL, 'ثُمَّ يُقَالُ هَـٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 83, 'ثم يقال هذا الذي كنتم به تكذبون', 588, 30),
  (5866, 18, '83:18', 59, 235, 527, 7, NULL, 'كَلَّآ إِنَّ كِتَـٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ', 83, 'كلا ان كتاب الابرار لفي عليين', 588, 30),
  (5867, 19, '83:19', 59, 235, 527, 7, NULL, 'وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ', 83, 'وما ادراك ما عليون', 588, 30),
  (5868, 20, '83:20', 59, 235, 527, 7, NULL, 'كِتَـٰبٌ مَّرْقُومٌ', 83, 'كتاب مرقوم', 588, 30),
  (5869, 21, '83:21', 59, 235, 527, 7, NULL, 'يَشْهَدُهُ ٱلْمُقَرَّبُونَ', 83, 'يشهده المقربون', 588, 30),
  (5870, 22, '83:22', 59, 235, 527, 7, NULL, 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ', 83, 'ان الابرار لفي نعيم', 588, 30),
