  (5875, 27, '83:27', 59, 235, 527, 7, NULL, 'وَمِزَاجُهُۥ مِن تَسْنِيمٍ', 83, 'ومزاجه من تسنيم', 588, 30),
  (5876, 28, '83:28', 59, 235, 527, 7, NULL, 'عَيْنًا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ', 83, 'عينا يشرب بها المقربون', 588, 30),
  (5877, 29, '83:29', 59, 235, 527, 7, NULL, 'إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ', 83, 'ان الذين اجرموا كانوا من الذين امنوا يضحكون', 588, 30),
  (5878, 30, '83:30', 59, 235, 527, 7, NULL, 'وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ', 83, 'واذا مروا بهم يتغامزون', 588, 30),
  (5879, 31, '83:31', 59, 235, 527, 7, NULL, 'وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ', 83, 'واذا انقلبوا الى اهلهم انقلبوا فكهين', 588, 30),
  (5880, 32, '83:32', 59, 235, 527, 7, NULL, 'وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَـٰٓؤُلَآءِ لَضَآلُّونَ', 83, 'واذا راوهم قالوا ان هؤلاء لضالون', 588, 30),
  (5881, 33, '83:33', 59, 235, 527, 7, NULL, 'وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَـٰفِظِينَ', 83, 'وما ارسلوا عليهم حافظين', 588, 30),
  (5882, 34, '83:34', 59, 235, 527, 7, NULL, 'فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ', 83, 'فاليوم الذين امنوا من الكفار يضحكون', 588, 30),
  (5883, 35, '83:35', 59, 235, 527, 7, NULL, 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 83, 'على الارائك ينظرون', 589, 30),
  (5884, 36, '83:36', 59, 235, 527, 7, NULL, 'هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ', 83, 'هل ثوب الكفار ما كانوا يفعلون', 589, 30),
  (5885, 1, '84:1', 59, 236, 528, 7, NULL, ' إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ', 84, 'اذا السماء انشقت', 589, 30),
  (5886, 2, '84:2', 59, 236, 528, 7, NULL, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 84, 'واذنت لربها وحقت', 589, 30),
  (5887, 3, '84:3', 59, 236, 528, 7, NULL, 'وَإِذَا ٱلْأَرْضُ مُدَّتْ', 84, 'واذا الارض مدت', 589, 30),
  (5888, 4, '84:4', 59, 236, 528, 7, NULL, 'وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ', 84, 'والقت ما فيها وتخلت', 589, 30),
  (5889, 5, '84:5', 59, 236, 528, 7, NULL, 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 84, 'واذنت لربها وحقت', 589, 30),
  (5890, 6, '84:6', 59, 236, 528, 7, NULL, 'يَـٰٓأَيُّهَا ٱلْإِنسَـٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًا فَمُلَـٰقِيهِ', 84, 'يا ايها الانسان انك كادح الى ربك كدحا فملاقيه', 589, 30),
  (5891, 7, '84:7', 59, 236, 528, 7, NULL, 'فَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِيَمِينِهِۦ', 84, 'فاما من اوتي كتابه بيمينه', 589, 30),
  (5892, 8, '84:8', 59, 236, 528, 7, NULL, 'فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا', 84, 'فسوف يحاسب حسابا يسيرا', 589, 30),
  (5893, 9, '84:9', 59, 236, 528, 7, NULL, 'وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًا', 84, 'وينقلب الى اهله مسرورا', 589, 30),
  (5894, 10, '84:10', 59, 236, 528, 7, NULL, 'وَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ وَرَآءَ ظَهْرِهِۦ', 84, 'واما من اوتي كتابه وراء ظهره', 589, 30),
  (5895, 11, '84:11', 59, 236, 528, 7, NULL, 'فَسَوْفَ يَدْعُوا۟ ثُبُورًا', 84, 'فسوف يدعو ثبورا', 589, 30),
  (5896, 12, '84:12', 59, 236, 528, 7, NULL, 'وَيَصْلَىٰ سَعِيرًا', 84, 'ويصلى سعيرا', 589, 30),
  (5897, 13, '84:13', 59, 236, 528, 7, NULL, 'إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا', 84, 'انه كان في اهله مسرورا', 589, 30),
  (5898, 14, '84:14', 59, 236, 528, 7, NULL, 'إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ', 84, 'انه ظن ان لن يحور', 589, 30),
  (5899, 15, '84:15', 59, 236, 528, 7, NULL, 'بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًا', 84, 'بلى ان ربه كان به بصيرا', 589, 30),
  (5900, 16, '84:16', 59, 236, 528, 7, NULL, 'فَلَآ أُقْسِمُ بِٱلشَّفَقِ', 84, 'فلا اقسم بالشفق', 589, 30),
  (5901, 17, '84:17', 59, 236, 528, 7, NULL, 'وَٱلَّيْلِ وَمَا وَسَقَ', 84, 'والليل وما وسق', 589, 30),
  (5902, 18, '84:18', 59, 236, 528, 7, NULL, 'وَٱلْقَمَرِ إِذَا ٱتَّسَقَ', 84, 'والقمر اذا اتسق', 589, 30),
  (5903, 19, '84:19', 59, 236, 528, 7, NULL, 'لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍ', 84, 'لتركبن طبقا عن طبق', 589, 30),
  (5904, 20, '84:20', 59, 236, 528, 7, NULL, 'فَمَا لَهُمْ لَا يُؤْمِنُونَ', 84, 'فما لهم لا يؤمنون', 589, 30),
  (5905, 21, '84:21', 59, 236, 528, 7, 13, 'وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ ۩', 84, 'واذا قرئ عليهم القران لا يسجدون', 589, 30),
  (5906, 22, '84:22', 59, 236, 528, 7, NULL, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ', 84, 'بل الذين كفروا يكذبون', 589, 30),
  (5907, 23, '84:23', 59, 236, 528, 7, NULL, 'وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ', 84, 'والله اعلم بما يوعون', 589, 30),
  (5908, 24, '84:24', 59, 236, 528, 7, NULL, 'فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 84, 'فبشرهم بعذاب اليم', 589, 30),
  (5909, 25, '84:25', 59, 236, 528, 7, NULL, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ', 84, 'الا الذين امنوا وعملوا الصالحات لهم اجر غير ممنون', 589, 30),
  (5910, 1, '85:1', 59, 236, 529, 7, NULL, ' وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ', 85, 'والسماء ذات البروج', 590, 30),
  (5911, 2, '85:2', 59, 236, 529, 7, NULL, 'وَٱلْيَوْمِ ٱلْمَوْعُودِ', 85, 'واليوم الموعود', 590, 30),
  (5912, 3, '85:3', 59, 236, 529, 7, NULL, 'وَشَاهِدٍ وَمَشْهُودٍ', 85, 'وشاهد ومشهود', 590, 30),
  (5913, 4, '85:4', 59, 236, 529, 7, NULL, 'قُتِلَ أَصْحَـٰبُ ٱلْأُخْدُودِ', 85, 'قتل اصحاب الاخدود', 590, 30),
  (5914, 5, '85:5', 59, 236, 529, 7, NULL, 'ٱلنَّارِ ذَاتِ ٱلْوَقُودِ', 85, 'النار ذات الوقود', 590, 30),
  (5915, 6, '85:6', 59, 236, 529, 7, NULL, 'إِذْ هُمْ عَلَيْهَا قُعُودٌ', 85, 'اذ هم عليها قعود', 590, 30),
  (5916, 7, '85:7', 59, 236, 529, 7, NULL, 'وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌ', 85, 'وهم على ما يفعلون بالمؤمنين شهود', 590, 30),
  (5917, 8, '85:8', 59, 236, 529, 7, NULL, 'وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ', 85, 'وما نقموا منهم الا ان يؤمنوا بالله العزيز الحميد', 590, 30),
  (5918, 9, '85:9', 59, 236, 529, 7, NULL, 'ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ', 85, 'الذي له ملك السماوات والارض والله على كل شيء شهيد', 590, 30),
  (5919, 10, '85:10', 59, 236, 529, 7, NULL, 'إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَـٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ', 85, 'ان الذين فتنوا المؤمنين والمؤمنات ثم لم يتوبوا فلهم عذاب جهنم ولهم عذاب الحريق', 590, 30),
  (5920, 11, '85:11', 59, 236, 529, 7, NULL, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ جَنَّـٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ', 85, 'ان الذين امنوا وعملوا الصالحات لهم جنات تجري من تحتها الانهار ذلك الفوز الكبير', 590, 30),
  (5921, 12, '85:12', 59, 236, 529, 7, NULL, 'إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ', 85, 'ان بطش ربك لشديد', 590, 30),
  (5922, 13, '85:13', 59, 236, 529, 7, NULL, 'إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ', 85, 'انه هو يبدئ ويعيد', 590, 30),
  (5923, 14, '85:14', 59, 236, 529, 7, NULL, 'وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ', 85, 'وهو الغفور الودود', 590, 30),
  (5924, 15, '85:15', 59, 236, 529, 7, NULL, 'ذُو ٱلْعَرْشِ ٱلْمَجِيدُ', 85, 'ذو العرش المجيد', 590, 30),
  (5925, 16, '85:16', 59, 236, 529, 7, NULL, 'فَعَّالٌ لِّمَا يُرِيدُ', 85, 'فعال لما يريد', 590, 30),
  (5926, 17, '85:17', 59, 236, 529, 7, NULL, 'هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ', 85, 'هل اتاك حديث الجنود', 590, 30),
  (5927, 18, '85:18', 59, 236, 529, 7, NULL, 'فِرْعَوْنَ وَثَمُودَ', 85, 'فرعون وثمود', 590, 30),
  (5928, 19, '85:19', 59, 236, 529, 7, NULL, 'بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍ', 85, 'بل الذين كفروا في تكذيب', 590, 30),
  (5929, 20, '85:20', 59, 236, 529, 7, NULL, 'وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ', 85, 'والله من ورائهم محيط', 590, 30),
  (5930, 21, '85:21', 59, 236, 529, 7, NULL, 'بَلْ هُوَ قُرْءَانٌ مَّجِيدٌ', 85, 'بل هو قران مجيد', 590, 30),
  (5931, 22, '85:22', 59, 236, 529, 7, NULL, 'فِى لَوْحٍ مَّحْفُوظٍۭ', 85, 'في لوح محفوظ', 590, 30),
  (5932, 1, '86:1', 59, 236, 530, 7, NULL, ' وَٱلسَّمَآءِ وَٱلطَّارِقِ', 86, 'والسماء والطارق', 591, 30),
  (5933, 2, '86:2', 59, 236, 530, 7, NULL, 'وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ', 86, 'وما ادراك ما الطارق', 591, 30),
  (5934, 3, '86:3', 59, 236, 530, 7, NULL, 'ٱلنَّجْمُ ٱلثَّاقِبُ', 86, 'النجم الثاقب', 591, 30),
  (5935, 4, '86:4', 59, 236, 530, 7, NULL, 'إِن كُلُّ نَفْسٍ لَّمَّا عَلَيْهَا حَافِظٌ', 86, 'ان كل نفس لما عليها حافظ', 591, 30),
  (5936, 5, '86:5', 59, 236, 530, 7, NULL, 'فَلْيَنظُرِ ٱلْإِنسَـٰنُ مِمَّ خُلِقَ', 86, 'فلينظر الانسان مم خلق', 591, 30),
  (5937, 6, '86:6', 59, 236, 530, 7, NULL, 'خُلِقَ مِن مَّآءٍ دَافِقٍ', 86, 'خلق من ماء دافق', 591, 30),
  (5938, 7, '86:7', 59, 236, 530, 7, NULL, 'يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ', 86, 'يخرج من بين الصلب والترائب', 591, 30),
  (5939, 8, '86:8', 59, 236, 530, 7, NULL, 'إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌ', 86, 'انه على رجعه لقادر', 591, 30),
  (5940, 9, '86:9', 59, 236, 530, 7, NULL, 'يَوْمَ تُبْلَى ٱلسَّرَآئِرُ', 86, 'يوم تبلى السرائر', 591, 30),
  (5941, 10, '86:10', 59, 236, 530, 7, NULL, 'فَمَا لَهُۥ مِن قُوَّةٍ وَلَا نَاصِرٍ', 86, 'فما له من قوة ولا ناصر', 591, 30),
  (5942, 11, '86:11', 59, 236, 530, 7, NULL, 'وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ', 86, 'والسماء ذات الرجع', 591, 30),
  (5943, 12, '86:12', 59, 236, 530, 7, NULL, 'وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ', 86, 'والارض ذات الصدع', 591, 30),
  (5944, 13, '86:13', 59, 236, 530, 7, NULL, 'إِنَّهُۥ لَقَوْلٌ فَصْلٌ', 86, 'انه لقول فصل', 591, 30),
  (5945, 14, '86:14', 59, 236, 530, 7, NULL, 'وَمَا هُوَ بِٱلْهَزْلِ', 86, 'وما هو بالهزل', 591, 30),
  (5946, 15, '86:15', 59, 236, 530, 7, NULL, 'إِنَّهُمْ يَكِيدُونَ كَيْدًا', 86, 'انهم يكيدون كيدا', 591, 30),
  (5947, 16, '86:16', 59, 236, 530, 7, NULL, 'وَأَكِيدُ كَيْدًا', 86, 'واكيد كيدا', 591, 30),
  (5948, 17, '86:17', 59, 236, 530, 7, NULL, 'فَمَهِّلِ ٱلْكَـٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا', 86, 'فمهل الكافرين امهلهم رويدا', 591, 30),
  (5949, 1, '87:1', 60, 237, 531, 7, NULL, ' سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى', 87, 'سبح اسم ربك الاعلى', 591, 30),
  (5950, 2, '87:2', 60, 237, 531, 7, NULL, 'ٱلَّذِى خَلَقَ فَسَوَّىٰ', 87, 'الذي خلق فسوى', 591, 30),
  (5951, 3, '87:3', 60, 237, 531, 7, NULL, 'وَٱلَّذِى قَدَّرَ فَهَدَىٰ', 87, 'والذي قدر فهدى', 591, 30),
  (5952, 4, '87:4', 60, 237, 531, 7, NULL, 'وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ', 87, 'والذي اخرج المرعى', 591, 30),
  (5953, 5, '87:5', 60, 237, 531, 7, NULL, 'فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ', 87, 'فجعله غثاء احوى', 591, 30),
  (5954, 6, '87:6', 60, 237, 531, 7, NULL, 'سَنُقْرِئُكَ فَلَا تَنسَىٰٓ', 87, 'سنقرئك فلا تنسى', 591, 30),
  (5955, 7, '87:7', 60, 237, 531, 7, NULL, 'إِلَّا مَا شَآءَ ٱللَّهُ ۚ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ', 87, 'الا ما شاء الله انه يعلم الجهر وما يخفى', 591, 30),
  (5956, 8, '87:8', 60, 237, 531, 7, NULL, 'وَنُيَسِّرُكَ لِلْيُسْرَىٰ', 87, 'ونيسرك لليسرى', 591, 30),
  (5957, 9, '87:9', 60, 237, 531, 7, NULL, 'فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ', 87, 'فذكر ان نفعت الذكرى', 591, 30),
  (5958, 10, '87:10', 60, 237, 531, 7, NULL, 'سَيَذَّكَّرُ مَن يَخْشَىٰ', 87, 'سيذكر من يخشى', 591, 30),
  (5959, 11, '87:11', 60, 237, 531, 7, NULL, 'وَيَتَجَنَّبُهَا ٱلْأَشْقَى', 87, 'ويتجنبها الاشقى', 591, 30),
  (5960, 12, '87:12', 60, 237, 531, 7, NULL, 'ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ', 87, 'الذي يصلى النار الكبرى', 591, 30),
  (5961, 13, '87:13', 60, 237, 531, 7, NULL, 'ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ', 87, 'ثم لا يموت فيها ولا يحيى', 591, 30),
  (5962, 14, '87:14', 60, 237, 531, 7, NULL, 'قَدْ أَفْلَحَ مَن تَزَكَّىٰ', 87, 'قد افلح من تزكى', 591, 30),
  (5963, 15, '87:15', 60, 237, 531, 7, NULL, 'وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ', 87, 'وذكر اسم ربه فصلى', 591, 30),
  (5964, 16, '87:16', 60, 237, 531, 7, NULL, 'بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا', 87, 'بل تؤثرون الحياة الدنيا', 592, 30),
  (5965, 17, '87:17', 60, 237, 531, 7, NULL, 'وَٱلْـَٔاخِرَةُ خَيْرٌ وَأَبْقَىٰٓ', 87, 'والاخرة خير وابقى', 592, 30),
  (5966, 18, '87:18', 60, 237, 531, 7, NULL, 'إِنَّ هَـٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ', 87, 'ان هذا لفي الصحف الاولى', 592, 30),
  (5967, 19, '87:19', 60, 237, 531, 7, NULL, 'صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ', 87, 'صحف ابراهيم وموسى', 592, 30),
  (5968, 1, '88:1', 60, 237, 532, 7, NULL, ' هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَـٰشِيَةِ', 88, 'هل اتاك حديث الغاشية', 592, 30),
  (5969, 2, '88:2', 60, 237, 532, 7, NULL, 'وُجُوهٌ يَوْمَئِذٍ خَـٰشِعَةٌ', 88, 'وجوه يومئذ خاشعة', 592, 30),
  (5970, 3, '88:3', 60, 237, 532, 7, NULL, 'عَامِلَةٌ نَّاصِبَةٌ', 88, 'عاملة ناصبة', 592, 30),
  (5971, 4, '88:4', 60, 237, 532, 7, NULL, 'تَصْلَىٰ نَارًا حَامِيَةً', 88, 'تصلى نارا حامية', 592, 30),
  (5972, 5, '88:5', 60, 237, 532, 7, NULL, 'تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍ', 88, 'تسقى من عين انية', 592, 30),
  (5973, 6, '88:6', 60, 237, 532, 7, NULL, 'لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍ', 88, 'ليس لهم طعام الا من ضريع', 592, 30),
  (5974, 7, '88:7', 60, 237, 532, 7, NULL, 'لَّا يُسْمِنُ وَلَا يُغْنِى مِن جُوعٍ', 88, 'لا يسمن ولا يغني من جوع', 592, 30),
  (5975, 8, '88:8', 60, 237, 532, 7, NULL, 'وُجُوهٌ يَوْمَئِذٍ نَّاعِمَةٌ', 88, 'وجوه يومئذ ناعمة', 592, 30),
  (5976, 9, '88:9', 60, 237, 532, 7, NULL, 'لِّسَعْيِهَا رَاضِيَةٌ', 88, 'لسعيها راضية', 592, 30),
  (5977, 10, '88:10', 60, 237, 532, 7, NULL, 'فِى جَنَّةٍ عَالِيَةٍ', 88, 'في جنة عالية', 592, 30),
  (5978, 11, '88:11', 60, 237, 532, 7, NULL, 'لَّا تَسْمَعُ فِيهَا لَـٰغِيَةً', 88, 'لا تسمع فيها لاغية', 592, 30),
  (5979, 12, '88:12', 60, 237, 532, 7, NULL, 'فِيهَا عَيْنٌ جَارِيَةٌ', 88, 'فيها عين جارية', 592, 30),
  (5980, 13, '88:13', 60, 237, 532, 7, NULL, 'فِيهَا سُرُرٌ مَّرْفُوعَةٌ', 88, 'فيها سرر مرفوعة', 592, 30),
  (5981, 14, '88:14', 60, 237, 532, 7, NULL, 'وَأَكْوَابٌ مَّوْضُوعَةٌ', 88, 'واكواب موضوعة', 592, 30),
  (5982, 15, '88:15', 60, 237, 532, 7, NULL, 'وَنَمَارِقُ مَصْفُوفَةٌ', 88, 'ونمارق مصفوفة', 592, 30),
  (5983, 16, '88:16', 60, 237, 532, 7, NULL, 'وَزَرَابِىُّ مَبْثُوثَةٌ', 88, 'وزرابي مبثوثة', 592, 30),
  (5984, 17, '88:17', 60, 237, 532, 7, NULL, 'أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ', 88, 'افلا ينظرون الى الابل كيف خلقت', 592, 30),
  (5985, 18, '88:18', 60, 237, 532, 7, NULL, 'وَإِلَى ٱلسَّمَآءِ كَيْفَ رُفِعَتْ', 88, 'والى السماء كيف رفعت', 592, 30),
  (5986, 19, '88:19', 60, 237, 532, 7, NULL, 'وَإِلَى ٱلْجِبَالِ كَيْفَ نُصِبَتْ', 88, 'والى الجبال كيف نصبت', 592, 30),
  (5987, 20, '88:20', 60, 237, 532, 7, NULL, 'وَإِلَى ٱلْأَرْضِ كَيْفَ سُطِحَتْ', 88, 'والى الارض كيف سطحت', 592, 30),
  (5988, 21, '88:21', 60, 237, 532, 7, NULL, 'فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌ', 88, 'فذكر انما انت مذكر', 592, 30),
  (5989, 22, '88:22', 60, 237, 532, 7, NULL, 'لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ', 88, 'لست عليهم بمصيطر', 592, 30),
  (5990, 23, '88:23', 60, 237, 532, 7, NULL, 'إِلَّا مَن تَوَلَّىٰ وَكَفَرَ', 88, 'الا من تولى وكفر', 592, 30),
  (5991, 24, '88:24', 60, 237, 532, 7, NULL, 'فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ', 88, 'فيعذبه الله العذاب الاكبر', 592, 30),
  (5992, 25, '88:25', 60, 237, 532, 7, NULL, 'إِنَّ إِلَيْنَآ إِيَابَهُمْ', 88, 'ان الينا ايابهم', 592, 30),
  (5993, 26, '88:26', 60, 237, 532, 7, NULL, 'ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم', 88, 'ثم ان علينا حسابهم', 592, 30),
  (5994, 1, '89:1', 60, 237, 533, 7, NULL, ' وَٱلْفَجْرِ', 89, 'والفجر', 593, 30),
  (5995, 2, '89:2', 60, 237, 533, 7, NULL, 'وَلَيَالٍ عَشْرٍ', 89, 'وليال عشر', 593, 30),
  (5996, 3, '89:3', 60, 237, 533, 7, NULL, 'وَٱلشَّفْعِ وَٱلْوَتْرِ', 89, 'والشفع والوتر', 593, 30),
  (5997, 4, '89:4', 60, 237, 533, 7, NULL, 'وَٱلَّيْلِ إِذَا يَسْرِ', 89, 'والليل اذا يسر', 593, 30),
  (5998, 5, '89:5', 60, 237, 533, 7, NULL, 'هَلْ فِى ذَٰلِكَ قَسَمٌ لِّذِى حِجْرٍ', 89, 'هل في ذلك قسم لذي حجر', 593, 30),
  (5999, 6, '89:6', 60, 237, 533, 7, NULL, 'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ', 89, 'الم تر كيف فعل ربك بعاد', 593, 30),
  (6000, 7, '89:7', 60, 237, 533, 7, NULL, 'إِرَمَ ذَاتِ ٱلْعِمَادِ', 89, 'ارم ذات العماد', 593, 30);
INSERT INTO `verses` (`id`, `verse_number`, `verse_key`, `hizb_number`, `rub_el_hizb_number`, `ruku_number`, `manzil_number`, `sajdah_number`, `text_uthmani`, `chapter_id`, `text_imlaei_simple`, `page_number`, `juz_number`) VALUES
  (6001, 8, '89:8', 60, 237, 533, 7, NULL, 'ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَـٰدِ', 89, 'التي لم يخلق مثلها في البلاد', 593, 30),
  (6002, 9, '89:9', 60, 237, 533, 7, NULL, 'وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ', 89, 'وثمود الذين جابوا الصخر بالواد', 593, 30),
  (6003, 10, '89:10', 60, 237, 533, 7, NULL, 'وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ', 89, 'وفرعون ذي الاوتاد', 593, 30),
  (6004, 11, '89:11', 60, 237, 533, 7, NULL, 'ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَـٰدِ', 89, 'الذين طغوا في البلاد', 593, 30),
  (6005, 12, '89:12', 60, 237, 533, 7, NULL, 'فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ', 89, 'فاكثروا فيها الفساد', 593, 30),
  (6006, 13, '89:13', 60, 237, 533, 7, NULL, 'فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ', 89, 'فصب عليهم ربك سوط عذاب', 593, 30),
  (6007, 14, '89:14', 60, 237, 533, 7, NULL, 'إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ', 89, 'ان ربك لبالمرصاد', 593, 30),
  (6008, 15, '89:15', 60, 237, 533, 7, NULL, 'فَأَمَّا ٱلْإِنسَـٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ', 89, 'فاما الانسان اذا ما ابتلاه ربه فاكرمه ونعمه فيقول ربي اكرمن', 593, 30),
  (6009, 16, '89:16', 60, 237, 533, 7, NULL, 'وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَـٰنَنِ', 89, 'واما اذا ما ابتلاه فقدر عليه رزقه فيقول ربي اهانن', 593, 30),
  (6010, 17, '89:17', 60, 237, 533, 7, NULL, 'كَلَّا ۖ بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ', 89, 'كلا بل لا تكرمون اليتيم', 593, 30),
  (6011, 18, '89:18', 60, 237, 533, 7, NULL, 'وَلَا تَحَـٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 89, 'ولا تحاضون على طعام المسكين', 593, 30),
  (6012, 19, '89:19', 60, 237, 533, 7, NULL, 'وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًا لَّمًّا', 89, 'وتاكلون التراث اكلا لما', 593, 30),
  (6013, 20, '89:20', 60, 237, 533, 7, NULL, 'وَتُحِبُّونَ ٱلْمَالَ حُبًّا جَمًّا', 89, 'وتحبون المال حبا جما', 593, 30),
  (6014, 21, '89:21', 60, 237, 533, 7, NULL, 'كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّا دَكًّا', 89, 'كلا اذا دكت الارض دكا دكا', 593, 30),
  (6015, 22, '89:22', 60, 237, 533, 7, NULL, 'وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّا صَفًّا', 89, 'وجاء ربك والملك صفا صفا', 593, 30),
  (6016, 23, '89:23', 60, 237, 533, 7, NULL, 'وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ ۚ يَوْمَئِذٍ يَتَذَكَّرُ ٱلْإِنسَـٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ', 89, 'وجيء يومئذ بجهنم يومئذ يتذكر الانسان وانى له الذكرى', 593, 30),
  (6017, 24, '89:24', 60, 237, 533, 7, NULL, 'يَقُولُ يَـٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى', 89, 'يقول يا ليتني قدمت لحياتي', 594, 30),
  (6018, 25, '89:25', 60, 237, 533, 7, NULL, 'فَيَوْمَئِذٍ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌ', 89, 'فيومئذ لا يعذب عذابه احد', 594, 30),
  (6019, 26, '89:26', 60, 237, 533, 7, NULL, 'وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌ', 89, 'ولا يوثق وثاقه احد', 594, 30),
  (6020, 27, '89:27', 60, 237, 533, 7, NULL, 'يَـٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ', 89, 'يا ايتها النفس المطمئنة', 594, 30),
  (6021, 28, '89:28', 60, 237, 533, 7, NULL, 'ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةً مَّرْضِيَّةً', 89, 'ارجعي الى ربك راضية مرضية', 594, 30),
  (6022, 29, '89:29', 60, 237, 533, 7, NULL, 'فَٱدْخُلِى فِى عِبَـٰدِى', 89, 'فادخلي في عبادي', 594, 30),
  (6023, 30, '89:30', 60, 237, 533, 7, NULL, 'وَٱدْخُلِى جَنَّتِى', 89, 'وادخلي جنتي', 594, 30),
  (6024, 1, '90:1', 60, 238, 534, 7, NULL, ' لَآ أُقْسِمُ بِهَـٰذَا ٱلْبَلَدِ', 90, 'لا اقسم بهذا البلد', 594, 30),
  (6025, 2, '90:2', 60, 238, 534, 7, NULL, 'وَأَنتَ حِلٌّۢ بِهَـٰذَا ٱلْبَلَدِ', 90, 'وانت حل بهذا البلد', 594, 30),
  (6026, 3, '90:3', 60, 238, 534, 7, NULL, 'وَوَالِدٍ وَمَا وَلَدَ', 90, 'ووالد وما ولد', 594, 30),
  (6027, 4, '90:4', 60, 238, 534, 7, NULL, 'لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِى كَبَدٍ', 90, 'لقد خلقنا الانسان في كبد', 594, 30),
  (6028, 5, '90:5', 60, 238, 534, 7, NULL, 'أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ', 90, 'ايحسب ان لن يقدر عليه احد', 594, 30),
  (6029, 6, '90:6', 60, 238, 534, 7, NULL, 'يَقُولُ أَهْلَكْتُ مَالًا لُّبَدًا', 90, 'يقول اهلكت مالا لبدا', 594, 30),
  (6030, 7, '90:7', 60, 238, 534, 7, NULL, 'أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ', 90, 'ايحسب ان لم يره احد', 594, 30),
  (6031, 8, '90:8', 60, 238, 534, 7, NULL, 'أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ', 90, 'الم نجعل له عينين', 594, 30),
  (6032, 9, '90:9', 60, 238, 534, 7, NULL, 'وَلِسَانًا وَشَفَتَيْنِ', 90, 'ولسانا وشفتين', 594, 30),
  (6033, 10, '90:10', 60, 238, 534, 7, NULL, 'وَهَدَيْنَـٰهُ ٱلنَّجْدَيْنِ', 90, 'وهديناه النجدين', 594, 30),
  (6034, 11, '90:11', 60, 238, 534, 7, NULL, 'فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ', 90, 'فلا اقتحم العقبة', 594, 30),
  (6035, 12, '90:12', 60, 238, 534, 7, NULL, 'وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ', 90, 'وما ادراك ما العقبة', 594, 30),
  (6036, 13, '90:13', 60, 238, 534, 7, NULL, 'فَكُّ رَقَبَةٍ', 90, 'فك رقبة', 594, 30),
  (6037, 14, '90:14', 60, 238, 534, 7, NULL, 'أَوْ إِطْعَـٰمٌ فِى يَوْمٍ ذِى مَسْغَبَةٍ', 90, 'او اطعام في يوم ذي مسغبة', 594, 30),
  (6038, 15, '90:15', 60, 238, 534, 7, NULL, 'يَتِيمًا ذَا مَقْرَبَةٍ', 90, 'يتيما ذا مقربة', 594, 30),
  (6039, 16, '90:16', 60, 238, 534, 7, NULL, 'أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ', 90, 'او مسكينا ذا متربة', 594, 30),
  (6040, 17, '90:17', 60, 238, 534, 7, NULL, 'ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ', 90, 'ثم كان من الذين امنوا وتواصوا بالصبر وتواصوا بالمرحمة', 594, 30),
  (6041, 18, '90:18', 60, 238, 534, 7, NULL, 'أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْمَيْمَنَةِ', 90, 'اولئك اصحاب الميمنة', 594, 30),
  (6042, 19, '90:19', 60, 238, 534, 7, NULL, 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِنَا هُمْ أَصْحَـٰبُ ٱلْمَشْـَٔمَةِ', 90, 'والذين كفروا باياتنا هم اصحاب المشامة', 594, 30),
  (6043, 20, '90:20', 60, 238, 534, 7, NULL, 'عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌۢ', 90, 'عليهم نار مؤصدة', 594, 30),
  (6044, 1, '91:1', 60, 238, 535, 7, NULL, ' وَٱلشَّمْسِ وَضُحَىٰهَا', 91, 'والشمس وضحاها', 595, 30),
  (6045, 2, '91:2', 60, 238, 535, 7, NULL, 'وَٱلْقَمَرِ إِذَا تَلَىٰهَا', 91, 'والقمر اذا تلاها', 595, 30),
  (6046, 3, '91:3', 60, 238, 535, 7, NULL, 'وَٱلنَّهَارِ إِذَا جَلَّىٰهَا', 91, 'والنهار اذا جلاها', 595, 30),
  (6047, 4, '91:4', 60, 238, 535, 7, NULL, 'وَٱلَّيْلِ إِذَا يَغْشَىٰهَا', 91, 'والليل اذا يغشاها', 595, 30),
  (6048, 5, '91:5', 60, 238, 535, 7, NULL, 'وَٱلسَّمَآءِ وَمَا بَنَىٰهَا', 91, 'والسماء وما بناها', 595, 30),
  (6049, 6, '91:6', 60, 238, 535, 7, NULL, 'وَٱلْأَرْضِ وَمَا طَحَىٰهَا', 91, 'والارض وما طحاها', 595, 30),
  (6050, 7, '91:7', 60, 238, 535, 7, NULL, 'وَنَفْسٍ وَمَا سَوَّىٰهَا', 91, 'ونفس وما سواها', 595, 30),
  (6051, 8, '91:8', 60, 238, 535, 7, NULL, 'فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا', 91, 'فالهمها فجورها وتقواها', 595, 30),
  (6052, 9, '91:9', 60, 238, 535, 7, NULL, 'قَدْ أَفْلَحَ مَن زَكَّىٰهَا', 91, 'قد افلح من زكاها', 595, 30),
  (6053, 10, '91:10', 60, 238, 535, 7, NULL, 'وَقَدْ خَابَ مَن دَسَّىٰهَا', 91, 'وقد خاب من دساها', 595, 30),
  (6054, 11, '91:11', 60, 238, 535, 7, NULL, 'كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ', 91, 'كذبت ثمود بطغواها', 595, 30),
  (6055, 12, '91:12', 60, 238, 535, 7, NULL, 'إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا', 91, 'اذ انبعث اشقاها', 595, 30),
  (6056, 13, '91:13', 60, 238, 535, 7, NULL, 'فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَـٰهَا', 91, 'فقال لهم رسول الله ناقة الله وسقياها', 595, 30),
  (6057, 14, '91:14', 60, 238, 535, 7, NULL, 'فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا', 91, 'فكذبوه فعقروها فدمدم عليهم ربهم بذنبهم فسواها', 595, 30),
  (6058, 15, '91:15', 60, 238, 535, 7, NULL, 'وَلَا يَخَافُ عُقْبَـٰهَا', 91, 'ولا يخاف عقباها', 595, 30),
  (6059, 1, '92:1', 60, 238, 536, 7, NULL, ' وَٱلَّيْلِ إِذَا يَغْشَىٰ', 92, 'والليل اذا يغشى', 595, 30),
  (6060, 2, '92:2', 60, 238, 536, 7, NULL, 'وَٱلنَّهَارِ إِذَا تَجَلَّىٰ', 92, 'والنهار اذا تجلى', 595, 30),
  (6061, 3, '92:3', 60, 238, 536, 7, NULL, 'وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', 92, 'وما خلق الذكر والانثى', 595, 30),
  (6062, 4, '92:4', 60, 238, 536, 7, NULL, 'إِنَّ سَعْيَكُمْ لَشَتَّىٰ', 92, 'ان سعيكم لشتى', 595, 30),
  (6063, 5, '92:5', 60, 238, 536, 7, NULL, 'فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ', 92, 'فاما من اعطى واتقى', 595, 30),
  (6064, 6, '92:6', 60, 238, 536, 7, NULL, 'وَصَدَّقَ بِٱلْحُسْنَىٰ', 92, 'وصدق بالحسنى', 595, 30),
  (6065, 7, '92:7', 60, 238, 536, 7, NULL, 'فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ', 92, 'فسنيسره لليسرى', 595, 30),
  (6066, 8, '92:8', 60, 238, 536, 7, NULL, 'وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ', 92, 'واما من بخل واستغنى', 595, 30),
  (6067, 9, '92:9', 60, 238, 536, 7, NULL, 'وَكَذَّبَ بِٱلْحُسْنَىٰ', 92, 'وكذب بالحسنى', 595, 30),
  (6068, 10, '92:10', 60, 238, 536, 7, NULL, 'فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ', 92, 'فسنيسره للعسرى', 595, 30),
  (6069, 11, '92:11', 60, 238, 536, 7, NULL, 'وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ', 92, 'وما يغني عنه ماله اذا تردى', 595, 30),
  (6070, 12, '92:12', 60, 238, 536, 7, NULL, 'إِنَّ عَلَيْنَا لَلْهُدَىٰ', 92, 'ان علينا للهدى', 595, 30),
  (6071, 13, '92:13', 60, 238, 536, 7, NULL, 'وَإِنَّ لَنَا لَلْـَٔاخِرَةَ وَٱلْأُولَىٰ', 92, 'وان لنا للاخرة والاولى', 595, 30),
  (6072, 14, '92:14', 60, 238, 536, 7, NULL, 'فَأَنذَرْتُكُمْ نَارًا تَلَظَّىٰ', 92, 'فانذرتكم نارا تلظى', 595, 30),
  (6073, 15, '92:15', 60, 238, 536, 7, NULL, 'لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى', 92, 'لا يصلاها الا الاشقى', 596, 30),
  (6074, 16, '92:16', 60, 238, 536, 7, NULL, 'ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ', 92, 'الذي كذب وتولى', 596, 30),
  (6075, 17, '92:17', 60, 238, 536, 7, NULL, 'وَسَيُجَنَّبُهَا ٱلْأَتْقَى', 92, 'وسيجنبها الاتقى', 596, 30),
  (6076, 18, '92:18', 60, 238, 536, 7, NULL, 'ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ', 92, 'الذي يؤتي ماله يتزكى', 596, 30),
  (6077, 19, '92:19', 60, 238, 536, 7, NULL, 'وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍ تُجْزَىٰٓ', 92, 'وما لاحد عنده من نعمة تجزى', 596, 30),
  (6078, 20, '92:20', 60, 238, 536, 7, NULL, 'إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ', 92, 'الا ابتغاء وجه ربه الاعلى', 596, 30),
  (6079, 21, '92:21', 60, 238, 536, 7, NULL, 'وَلَسَوْفَ يَرْضَىٰ', 92, 'ولسوف يرضى', 596, 30),
  (6080, 1, '93:1', 60, 238, 537, 7, NULL, ' وَٱلضُّحَىٰ', 93, 'والضحى', 596, 30),
  (6081, 2, '93:2', 60, 238, 537, 7, NULL, 'وَٱلَّيْلِ إِذَا سَجَىٰ', 93, 'والليل اذا سجى', 596, 30),
  (6082, 3, '93:3', 60, 238, 537, 7, NULL, 'مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ', 93, 'ما ودعك ربك وما قلى', 596, 30),
  (6083, 4, '93:4', 60, 238, 537, 7, NULL, 'وَلَلْـَٔاخِرَةُ خَيْرٌ لَّكَ مِنَ ٱلْأُولَىٰ', 93, 'وللاخرة خير لك من الاولى', 596, 30),
  (6084, 5, '93:5', 60, 238, 537, 7, NULL, 'وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ', 93, 'ولسوف يعطيك ربك فترضى', 596, 30),
  (6085, 6, '93:6', 60, 238, 537, 7, NULL, 'أَلَمْ يَجِدْكَ يَتِيمًا فَـَٔاوَىٰ', 93, 'الم يجدك يتيما فاوى', 596, 30),
  (6086, 7, '93:7', 60, 238, 537, 7, NULL, 'وَوَجَدَكَ ضَآلًّا فَهَدَىٰ', 93, 'ووجدك ضالا فهدى', 596, 30),
  (6087, 8, '93:8', 60, 238, 537, 7, NULL, 'وَوَجَدَكَ عَآئِلًا فَأَغْنَىٰ', 93, 'ووجدك عائلا فاغنى', 596, 30),
  (6088, 9, '93:9', 60, 238, 537, 7, NULL, 'فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ', 93, 'فاما اليتيم فلا تقهر', 596, 30),
  (6089, 10, '93:10', 60, 238, 537, 7, NULL, 'وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ', 93, 'واما السائل فلا تنهر', 596, 30),
  (6090, 11, '93:11', 60, 238, 537, 7, NULL, 'وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ', 93, 'واما بنعمة ربك فحدث', 596, 30),
  (6091, 1, '94:1', 60, 239, 538, 7, NULL, ' أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ', 94, 'الم نشرح لك صدرك', 596, 30),
  (6092, 2, '94:2', 60, 239, 538, 7, NULL, 'وَوَضَعْنَا عَنكَ وِزْرَكَ', 94, 'ووضعنا عنك وزرك', 596, 30),
  (6093, 3, '94:3', 60, 239, 538, 7, NULL, 'ٱلَّذِىٓ أَنقَضَ ظَهْرَكَ', 94, 'الذي انقض ظهرك', 596, 30),
  (6094, 4, '94:4', 60, 239, 538, 7, NULL, 'وَرَفَعْنَا لَكَ ذِكْرَكَ', 94, 'ورفعنا لك ذكرك', 596, 30),
  (6095, 5, '94:5', 60, 239, 538, 7, NULL, 'فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا', 94, 'فان مع العسر يسرا', 596, 30),
  (6096, 6, '94:6', 60, 239, 538, 7, NULL, 'إِنَّ مَعَ ٱلْعُسْرِ يُسْرًا', 94, 'ان مع العسر يسرا', 596, 30),
  (6097, 7, '94:7', 60, 239, 538, 7, NULL, 'فَإِذَا فَرَغْتَ فَٱنصَبْ', 94, 'فاذا فرغت فانصب', 596, 30),
  (6098, 8, '94:8', 60, 239, 538, 7, NULL, 'وَإِلَىٰ رَبِّكَ فَٱرْغَب', 94, 'والى ربك فارغب', 596, 30),
  (6099, 1, '95:1', 60, 239, 539, 7, NULL, 'وَٱلتِّينِ وَٱلزَّيْتُونِ', 95, 'والتين والزيتون', 597, 30),
  (6100, 2, '95:2', 60, 239, 539, 7, NULL, 'وَطُورِ سِينِينَ', 95, 'وطور سينين', 597, 30),
  (6101, 3, '95:3', 60, 239, 539, 7, NULL, 'وَهَـٰذَا ٱلْبَلَدِ ٱلْأَمِينِ', 95, 'وهذا البلد الامين', 597, 30),
  (6102, 4, '95:4', 60, 239, 539, 7, NULL, 'لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍ', 95, 'لقد خلقنا الانسان في احسن تقويم', 597, 30),
  (6103, 5, '95:5', 60, 239, 539, 7, NULL, 'ثُمَّ رَدَدْنَـٰهُ أَسْفَلَ سَـٰفِلِينَ', 95, 'ثم رددناه اسفل سافلين', 597, 30),
  (6104, 6, '95:6', 60, 239, 539, 7, NULL, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ', 95, 'الا الذين امنوا وعملوا الصالحات فلهم اجر غير ممنون', 597, 30),
  (6105, 7, '95:7', 60, 239, 539, 7, NULL, 'فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ', 95, 'فما يكذبك بعد بالدين', 597, 30),
  (6106, 8, '95:8', 60, 239, 539, 7, NULL, 'أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَـٰكِمِينَ', 95, 'اليس الله باحكم الحاكمين', 597, 30),
  (6107, 1, '96:1', 60, 239, 540, 7, NULL, ' ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ', 96, 'اقرا باسم ربك الذي خلق', 597, 30),
  (6108, 2, '96:2', 60, 239, 540, 7, NULL, 'خَلَقَ ٱلْإِنسَـٰنَ مِنْ عَلَقٍ', 96, 'خلق الانسان من علق', 597, 30),
  (6109, 3, '96:3', 60, 239, 540, 7, NULL, 'ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ', 96, 'اقرا وربك الاكرم', 597, 30),
  (6110, 4, '96:4', 60, 239, 540, 7, NULL, 'ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ', 96, 'الذي علم بالقلم', 597, 30),
  (6111, 5, '96:5', 60, 239, 540, 7, NULL, 'عَلَّمَ ٱلْإِنسَـٰنَ مَا لَمْ يَعْلَمْ', 96, 'علم الانسان ما لم يعلم', 597, 30),
  (6112, 6, '96:6', 60, 239, 540, 7, NULL, 'كَلَّآ إِنَّ ٱلْإِنسَـٰنَ لَيَطْغَىٰٓ', 96, 'كلا ان الانسان ليطغى', 597, 30),
  (6113, 7, '96:7', 60, 239, 540, 7, NULL, 'أَن رَّءَاهُ ٱسْتَغْنَىٰٓ', 96, 'ان راه استغنى', 597, 30),
  (6114, 8, '96:8', 60, 239, 540, 7, NULL, 'إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ', 96, 'ان الى ربك الرجعى', 597, 30),
  (6115, 9, '96:9', 60, 239, 540, 7, NULL, 'أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ', 96, 'ارايت الذي ينهى', 597, 30),
  (6116, 10, '96:10', 60, 239, 540, 7, NULL, 'عَبْدًا إِذَا صَلَّىٰٓ', 96, 'عبدا اذا صلى', 597, 30),
  (6117, 11, '96:11', 60, 239, 540, 7, NULL, 'أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ', 96, 'ارايت ان كان على الهدى', 597, 30),
  (6118, 12, '96:12', 60, 239, 540, 7, NULL, 'أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ', 96, 'او امر بالتقوى', 597, 30),
  (6119, 13, '96:13', 60, 239, 540, 7, NULL, 'أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ', 96, 'ارايت ان كذب وتولى', 597, 30),
  (6120, 14, '96:14', 60, 239, 540, 7, NULL, 'أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ', 96, 'الم يعلم بان الله يرى', 597, 30),
  (6121, 15, '96:15', 60, 239, 540, 7, NULL, 'كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ', 96, 'كلا لئن لم ينته لنسفعا بالناصية', 597, 30),
  (6122, 16, '96:16', 60, 239, 540, 7, NULL, 'نَاصِيَةٍ كَـٰذِبَةٍ خَاطِئَةٍ', 96, 'ناصية كاذبة خاطئة', 597, 30),
  (6123, 17, '96:17', 60, 239, 540, 7, NULL, 'فَلْيَدْعُ نَادِيَهُۥ', 96, 'فليدع ناديه', 597, 30),
  (6124, 18, '96:18', 60, 239, 540, 7, NULL, 'سَنَدْعُ ٱلزَّبَانِيَةَ', 96, 'سندع الزبانية', 597, 30),
  (6125, 19, '96:19', 60, 239, 540, 7, 14, 'كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩', 96, 'كلا لا تطعه واسجد واقترب', 597, 30),
  (6126, 1, '97:1', 60, 239, 541, 7, NULL, 'إِنَّآ أَنزَلْنَـٰهُ فِى لَيْلَةِ ٱلْقَدْرِ', 97, 'انا انزلناه في ليلة القدر', 598, 30),
  (6127, 2, '97:2', 60, 239, 541, 7, NULL, 'وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ', 97, 'وما ادراك ما ليلة القدر', 598, 30),
  (6128, 3, '97:3', 60, 239, 541, 7, NULL, 'لَيْلَةُ ٱلْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ', 97, 'ليلة القدر خير من الف شهر', 598, 30),
  (6129, 4, '97:4', 60, 239, 541, 7, NULL, 'تَنَزَّلُ ٱلْمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ', 97, 'تنزل الملائكة والروح فيها باذن ربهم من كل امر', 598, 30),
  (6130, 5, '97:5', 60, 239, 541, 7, NULL, 'سَلَـٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ', 97, 'سلام هي حتى مطلع الفجر', 598, 30),
  (6131, 1, '98:1', 60, 239, 542, 7, NULL, ' لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ', 98, 'لم يكن الذين كفروا من اهل الكتاب والمشركين منفكين حتى تاتيهم البينة', 598, 30),
  (6132, 2, '98:2', 60, 239, 542, 7, NULL, 'رَسُولٌ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًا مُّطَهَّرَةً', 98, 'رسول من الله يتلو صحفا مطهرة', 598, 30),
  (6133, 3, '98:3', 60, 239, 542, 7, NULL, 'فِيهَا كُتُبٌ قَيِّمَةٌ', 98, 'فيها كتب قيمة', 598, 30),
  (6134, 4, '98:4', 60, 239, 542, 7, NULL, 'وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ', 98, 'وما تفرق الذين اوتوا الكتاب الا من بعد ما جاءتهم البينة', 598, 30),
  (6135, 5, '98:5', 60, 239, 542, 7, NULL, 'وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ', 98, 'وما امروا الا ليعبدوا الله مخلصين له الدين حنفاء ويقيموا الصلاة ويؤتوا الزكاة وذلك دين القيمة', 598, 30),
  (6136, 6, '98:6', 60, 239, 542, 7, NULL, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ ۚ أُو۟لَـٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ', 98, 'ان الذين كفروا من اهل الكتاب والمشركين في نار جهنم خالدين فيها اولئك هم شر البرية', 598, 30),
  (6137, 7, '98:7', 60, 239, 542, 7, NULL, 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ', 98, 'ان الذين امنوا وعملوا الصالحات اولئك هم خير البرية', 598, 30),
  (6138, 8, '98:8', 60, 239, 542, 7, NULL, 'جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّـٰتُ عَدْنٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ', 98, 'جزاؤهم عند ربهم جنات عدن تجري من تحتها الانهار خالدين فيها ابدا رضي الله عنهم ورضوا عنه ذلك لمن خشي ربه', 599, 30),
  (6139, 1, '99:1', 60, 239, 543, 7, NULL, ' إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا', 99, 'اذا زلزلت الارض زلزالها', 599, 30),
  (6140, 2, '99:2', 60, 239, 543, 7, NULL, 'وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا', 99, 'واخرجت الارض اثقالها', 599, 30),
  (6141, 3, '99:3', 60, 239, 543, 7, NULL, 'وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا', 99, 'وقال الانسان ما لها', 599, 30),
  (6142, 4, '99:4', 60, 239, 543, 7, NULL, 'يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا', 99, 'يومئذ تحدث اخبارها', 599, 30),
  (6143, 5, '99:5', 60, 239, 543, 7, NULL, 'بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا', 99, 'بان ربك اوحى لها', 599, 30),
  (6144, 6, '99:6', 60, 239, 543, 7, NULL, 'يَوْمَئِذٍ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ', 99, 'يومئذ يصدر الناس اشتاتا ليروا اعمالهم', 599, 30),
  (6145, 7, '99:7', 60, 239, 543, 7, NULL, 'فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ', 99, 'فمن يعمل مثقال ذرة خيرا يره', 599, 30),
  (6146, 8, '99:8', 60, 239, 543, 7, NULL, 'وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ', 99, 'ومن يعمل مثقال ذرة شرا يره', 599, 30),
  (6147, 1, '100:1', 60, 239, 544, 7, NULL, ' وَٱلْعَـٰدِيَـٰتِ ضَبْحًا', 100, 'والعاديات ضبحا', 599, 30),
  (6148, 2, '100:2', 60, 239, 544, 7, NULL, 'فَٱلْمُورِيَـٰتِ قَدْحًا', 100, 'فالموريات قدحا', 599, 30),
  (6149, 3, '100:3', 60, 239, 544, 7, NULL, 'فَٱلْمُغِيرَٰتِ صُبْحًا', 100, 'فالمغيرات صبحا', 599, 30),
  (6150, 4, '100:4', 60, 239, 544, 7, NULL, 'فَأَثَرْنَ بِهِۦ نَقْعًا', 100, 'فاثرن به نقعا', 599, 30),
  (6151, 5, '100:5', 60, 239, 544, 7, NULL, 'فَوَسَطْنَ بِهِۦ جَمْعًا', 100, 'فوسطن به جمعا', 599, 30),
  (6152, 6, '100:6', 60, 239, 544, 7, NULL, 'إِنَّ ٱلْإِنسَـٰنَ لِرَبِّهِۦ لَكَنُودٌ', 100, 'ان الانسان لربه لكنود', 599, 30),
  (6153, 7, '100:7', 60, 239, 544, 7, NULL, 'وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ', 100, 'وانه على ذلك لشهيد', 599, 30),
  (6154, 8, '100:8', 60, 239, 544, 7, NULL, 'وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ', 100, 'وانه لحب الخير لشديد', 599, 30),
  (6155, 9, '100:9', 60, 240, 544, 7, NULL, '۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ', 100, 'افلا يعلم اذا بعثر ما في القبور', 599, 30),
  (6156, 10, '100:10', 60, 240, 544, 7, NULL, 'وَحُصِّلَ مَا فِى ٱلصُّدُورِ', 100, 'وحصل ما في الصدور', 600, 30),
  (6157, 11, '100:11', 60, 240, 544, 7, NULL, 'إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌۢ', 100, 'ان ربهم بهم يومئذ لخبير', 600, 30),
  (6158, 1, '101:1', 60, 240, 545, 7, NULL, ' ٱلْقَارِعَةُ', 101, 'القارعة', 600, 30),
  (6159, 2, '101:2', 60, 240, 545, 7, NULL, 'مَا ٱلْقَارِعَةُ', 101, 'ما القارعة', 600, 30),
  (6160, 3, '101:3', 60, 240, 545, 7, NULL, 'وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ', 101, 'وما ادراك ما القارعة', 600, 30),
  (6161, 4, '101:4', 60, 240, 545, 7, NULL, 'يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ', 101, 'يوم يكون الناس كالفراش المبثوث', 600, 30),
  (6162, 5, '101:5', 60, 240, 545, 7, NULL, 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ', 101, 'وتكون الجبال كالعهن المنفوش', 600, 30),
  (6163, 6, '101:6', 60, 240, 545, 7, NULL, 'فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ', 101, 'فاما من ثقلت موازينه', 600, 30),
  (6164, 7, '101:7', 60, 240, 545, 7, NULL, 'فَهُوَ فِى عِيشَةٍ رَّاضِيَةٍ', 101, 'فهو في عيشة راضية', 600, 30),
  (6165, 8, '101:8', 60, 240, 545, 7, NULL, 'وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ', 101, 'واما من خفت موازينه', 600, 30),
  (6166, 9, '101:9', 60, 240, 545, 7, NULL, 'فَأُمُّهُۥ هَاوِيَةٌ', 101, 'فامه هاوية', 600, 30),
  (6167, 10, '101:10', 60, 240, 545, 7, NULL, 'وَمَآ أَدْرَىٰكَ مَا هِيَهْ', 101, 'وما ادراك ما هيه', 600, 30),
  (6168, 11, '101:11', 60, 240, 545, 7, NULL, 'نَارٌ حَامِيَةٌۢ', 101, 'نار حامية', 600, 30),
  (6169, 1, '102:1', 60, 240, 546, 7, NULL, ' أَلْهَىٰكُمُ ٱلتَّكَاثُرُ', 102, 'الهاكم التكاثر', 600, 30),
  (6170, 2, '102:2', 60, 240, 546, 7, NULL, 'حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ', 102, 'حتى زرتم المقابر', 600, 30),
  (6171, 3, '102:3', 60, 240, 546, 7, NULL, 'كَلَّا سَوْفَ تَعْلَمُونَ', 102, 'كلا سوف تعلمون', 600, 30),
  (6172, 4, '102:4', 60, 240, 546, 7, NULL, 'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ', 102, 'ثم كلا سوف تعلمون', 600, 30),
  (6173, 5, '102:5', 60, 240, 546, 7, NULL, 'كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ', 102, 'كلا لو تعلمون علم اليقين', 600, 30),
  (6174, 6, '102:6', 60, 240, 546, 7, NULL, 'لَتَرَوُنَّ ٱلْجَحِيمَ', 102, 'لترون الجحيم', 600, 30),
  (6175, 7, '102:7', 60, 240, 546, 7, NULL, 'ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ', 102, 'ثم لترونها عين اليقين', 600, 30),
  (6176, 8, '102:8', 60, 240, 546, 7, NULL, 'ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ', 102, 'ثم لتسالن يومئذ عن النعيم', 600, 30),
  (6177, 1, '103:1', 60, 240, 547, 7, NULL, ' وَٱلْعَصْرِ', 103, 'والعصر', 601, 30),
  (6178, 2, '103:2', 60, 240, 547, 7, NULL, 'إِنَّ ٱلْإِنسَـٰنَ لَفِى خُسْرٍ', 103, 'ان الانسان لفي خسر', 601, 30),
  (6179, 3, '103:3', 60, 240, 547, 7, NULL, 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ', 103, 'الا الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر', 601, 30),
  (6180, 1, '104:1', 60, 240, 548, 7, NULL, ' وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ', 104, 'ويل لكل همزة لمزة', 601, 30),
  (6181, 2, '104:2', 60, 240, 548, 7, NULL, 'ٱلَّذِى جَمَعَ مَالًا وَعَدَّدَهُۥ', 104, 'الذي جمع مالا وعدده', 601, 30),
  (6182, 3, '104:3', 60, 240, 548, 7, NULL, 'يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ', 104, 'يحسب ان ماله اخلده', 601, 30),
  (6183, 4, '104:4', 60, 240, 548, 7, NULL, 'كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ', 104, 'كلا لينبذن في الحطمة', 601, 30),
  (6184, 5, '104:5', 60, 240, 548, 7, NULL, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ', 104, 'وما ادراك ما الحطمة', 601, 30),
  (6185, 6, '104:6', 60, 240, 548, 7, NULL, 'نَارُ ٱللَّهِ ٱلْمُوقَدَةُ', 104, 'نار الله الموقدة', 601, 30),
  (6186, 7, '104:7', 60, 240, 548, 7, NULL, 'ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ', 104, 'التي تطلع على الافئدة', 601, 30),
  (6187, 8, '104:8', 60, 240, 548, 7, NULL, 'إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ', 104, 'انها عليهم مؤصدة', 601, 30),
  (6188, 9, '104:9', 60, 240, 548, 7, NULL, 'فِى عَمَدٍ مُّمَدَّدَةٍۭ', 104, 'في عمد ممددة', 601, 30),
  (6189, 1, '105:1', 60, 240, 549, 7, NULL, ' أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَـٰبِ ٱلْفِيلِ', 105, 'الم تر كيف فعل ربك باصحاب الفيل', 601, 30),
  (6190, 2, '105:2', 60, 240, 549, 7, NULL, 'أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍ', 105, 'الم يجعل كيدهم في تضليل', 601, 30),
  (6191, 3, '105:3', 60, 240, 549, 7, NULL, 'وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ', 105, 'وارسل عليهم طيرا ابابيل', 601, 30),
  (6192, 4, '105:4', 60, 240, 549, 7, NULL, 'تَرْمِيهِم بِحِجَارَةٍ مِّن سِجِّيلٍ', 105, 'ترميهم بحجارة من سجيل', 601, 30),
  (6193, 5, '105:5', 60, 240, 549, 7, NULL, 'فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍۭ', 105, 'فجعلهم كعصف ماكول', 601, 30),
  (6194, 1, '106:1', 60, 240, 550, 7, NULL, ' لِإِيلَـٰفِ قُرَيْشٍ', 106, 'لايلاف قريش', 602, 30),
  (6195, 2, '106:2', 60, 240, 550, 7, NULL, 'إِۦلَـٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ', 106, 'ايلافهم رحلة الشتاء والصيف', 602, 30),
  (6196, 3, '106:3', 60, 240, 550, 7, NULL, 'فَلْيَعْبُدُوا۟ رَبَّ هَـٰذَا ٱلْبَيْتِ', 106, 'فليعبدوا رب هذا البيت', 602, 30),
  (6197, 4, '106:4', 60, 240, 550, 7, NULL, 'ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍ وَءَامَنَهُم مِّنْ خَوْفٍۭ', 106, 'الذي اطعمهم من جوع وامنهم من خوف', 602, 30),
  (6198, 1, '107:1', 60, 240, 551, 7, NULL, ' أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ', 107, 'ارايت الذي يكذب بالدين', 602, 30),
  (6199, 2, '107:2', 60, 240, 551, 7, NULL, 'فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ', 107, 'فذلك الذي يدع اليتيم', 602, 30),
  (6200, 3, '107:3', 60, 240, 551, 7, NULL, 'وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 107, 'ولا يحض على طعام المسكين', 602, 30),
  (6201, 4, '107:4', 60, 240, 551, 7, NULL, 'فَوَيْلٌ لِّلْمُصَلِّينَ', 107, 'فويل للمصلين', 602, 30),
  (6202, 5, '107:5', 60, 240, 551, 7, NULL, 'ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ', 107, 'الذين هم عن صلاتهم ساهون', 602, 30),
  (6203, 6, '107:6', 60, 240, 551, 7, NULL, 'ٱلَّذِينَ هُمْ يُرَآءُونَ', 107, 'الذين هم يراءون', 602, 30),
  (6204, 7, '107:7', 60, 240, 551, 7, NULL, 'وَيَمْنَعُونَ ٱلْمَاعُونَ', 107, 'ويمنعون الماعون', 602, 30),
  (6205, 1, '108:1', 60, 240, 552, 7, NULL, ' إِنَّآ أَعْطَيْنَـٰكَ ٱلْكَوْثَرَ', 108, 'انا اعطيناك الكوثر', 602, 30),
  (6206, 2, '108:2', 60, 240, 552, 7, NULL, 'فَصَلِّ لِرَبِّكَ وَٱنْحَرْ', 108, 'فصل لربك وانحر', 602, 30),
  (6207, 3, '108:3', 60, 240, 552, 7, NULL, 'إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ', 108, 'ان شانئك هو الابتر', 602, 30),
  (6208, 1, '109:1', 60, 240, 553, 7, NULL, ' قُلْ يَـٰٓأَيُّهَا ٱلْكَـٰفِرُونَ', 109, 'قل يا ايها الكافرون', 603, 30),
  (6209, 2, '109:2', 60, 240, 553, 7, NULL, 'لَآ أَعْبُدُ مَا تَعْبُدُونَ', 109, 'لا اعبد ما تعبدون', 603, 30),
  (6210, 3, '109:3', 60, 240, 553, 7, NULL, 'وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ', 109, 'ولا انتم عابدون ما اعبد', 603, 30),
  (6211, 4, '109:4', 60, 240, 553, 7, NULL, 'وَلَآ أَنَا۠ عَابِدٌ مَّا عَبَدتُّمْ', 109, 'ولا انا عابد ما عبدتم', 603, 30),
  (6212, 5, '109:5', 60, 240, 553, 7, NULL, 'وَلَآ أَنتُمْ عَـٰبِدُونَ مَآ أَعْبُدُ', 109, 'ولا انتم عابدون ما اعبد', 603, 30),
  (6213, 6, '109:6', 60, 240, 553, 7, NULL, 'لَكُمْ دِينُكُمْ وَلِىَ دِينِ', 109, 'لكم دينكم ولي دين', 603, 30),
  (6214, 1, '110:1', 60, 240, 554, 7, NULL, ' إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ', 110, 'اذا جاء نصر الله والفتح', 603, 30),
  (6215, 2, '110:2', 60, 240, 554, 7, NULL, 'وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًا', 110, 'ورايت الناس يدخلون في دين الله افواجا', 603, 30),
  (6216, 3, '110:3', 60, 240, 554, 7, NULL, 'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا', 110, 'فسبح بحمد ربك واستغفره انه كان توابا', 603, 30),
  (6217, 1, '111:1', 60, 240, 555, 7, NULL, ' تَبَّتْ يَدَآ أَبِى لَهَبٍ وَتَبَّ', 111, 'تبت يدا ابي لهب وتب', 603, 30),
  (6218, 2, '111:2', 60, 240, 555, 7, NULL, 'مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ', 111, 'ما اغنى عنه ماله وما كسب', 603, 30),
  (6219, 3, '111:3', 60, 240, 555, 7, NULL, 'سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ', 111, 'سيصلى نارا ذات لهب', 603, 30),
  (6220, 4, '111:4', 60, 240, 555, 7, NULL, 'وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ', 111, 'وامراته حمالة الحطب', 603, 30),
  (6221, 5, '111:5', 60, 240, 555, 7, NULL, 'فِى جِيدِهَا حَبْلٌ مِّن مَّسَدٍۭ', 111, 'في جيدها حبل من مسد', 603, 30),
  (6222, 1, '112:1', 60, 240, 556, 7, NULL, ' قُلْ هُوَ ٱللَّهُ أَحَدٌ', 112, 'قل هو الله احد', 604, 30),
  (6223, 2, '112:2', 60, 240, 556, 7, NULL, 'ٱللَّهُ ٱلصَّمَدُ', 112, 'الله الصمد', 604, 30),
  (6224, 3, '112:3', 60, 240, 556, 7, NULL, 'لَمْ يَلِدْ وَلَمْ يُولَدْ', 112, 'لم يلد ولم يولد', 604, 30),
  (6225, 4, '112:4', 60, 240, 556, 7, NULL, 'وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ', 112, 'ولم يكن له كفوا احد', 604, 30),
  (6226, 1, '113:1', 60, 240, 557, 7, NULL, ' قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ', 113, 'قل اعوذ برب الفلق', 604, 30),
  (6227, 2, '113:2', 60, 240, 557, 7, NULL, 'مِن شَرِّ مَا خَلَقَ', 113, 'من شر ما خلق', 604, 30),
  (6228, 3, '113:3', 60, 240, 557, 7, NULL, 'وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ', 113, 'ومن شر غاسق اذا وقب', 604, 30),
  (6229, 4, '113:4', 60, 240, 557, 7, NULL, 'وَمِن شَرِّ ٱلنَّفَّـٰثَـٰتِ فِى ٱلْعُقَدِ', 113, 'ومن شر النفاثات في العقد', 604, 30),
  (6230, 5, '113:5', 60, 240, 557, 7, NULL, 'وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', 113, 'ومن شر حاسد اذا حسد', 604, 30),
  (6231, 1, '114:1', 60, 240, 558, 7, NULL, ' قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ', 114, 'قل اعوذ برب الناس', 604, 30),
  (6232, 2, '114:2', 60, 240, 558, 7, NULL, 'مَلِكِ ٱلنَّاسِ', 114, 'ملك الناس', 604, 30),
  (6233, 3, '114:3', 60, 240, 558, 7, NULL, 'إِلَـٰهِ ٱلنَّاسِ', 114, 'اله الناس', 604, 30),
  (6234, 4, '114:4', 60, 240, 558, 7, NULL, 'مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ', 114, 'من شر الوسواس الخناس', 604, 30),
  (6235, 5, '114:5', 60, 240, 558, 7, NULL, 'ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ', 114, 'الذي يوسوس في صدور الناس', 604, 30),
  (6236, 6, '114:6', 60, 240, 558, 7, NULL, 'مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ', 114, 'من الجنة والناس', 604, 30);
